/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140722-6","meetingId":"h26-cm07","date":"2014年7月22日","dateIso":"2014-07-22","committee":"区民委員会","time":"午後１時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"平成２６年度地域振興基金を活用した区民活動助成事業の決定","agenda":"平成２６年度地域振興基金を活用した区民活動助成事業の決定","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この事業について、まず２点お伺いしたいのですけれども、１点目は審査・決定のところの審査委員の現在のメンバーが、どういう方がなっているのか。始められるのが７月ぐらいになるのかなと思うのですが、課題だというお考えがあるのかどうか、説明を求めました。","respondent":"寺嶋協働・国際担当課長","answer":"やはり事前の説明会とか十分にやりませんと、例えば書類のつくり方一つとってもかなり事前に念入りな説明とか相談が多いということがあります。","id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"審査委員ですけれども、メンバーがかわっているのかどうかということを知りたいので、どのような方がここにいるのかということで、フルネームでお教えほしいと求めました。","respondent":"寺嶋協働・国際担当課長","answer":"公益活動団体の代表委員につきましては、継続して東京ボランティア・市民活動センター副所長の竹内則夫様にお願いしております。区のほうから委員としては、地域振興事業部長、地域活動課長、文化スポーツ振興課長の３名です。","id":"exchange-002"},{"speaker":"井上委員","kind":"意見","question":"公募委員はやはりかわっていくということだと思うのですが、公募委員は、再任を妨げないけれども何年を限度とか、そういう定めにはなっているのかどうかとの意見を述べました。","respondent":"寺嶋協働・国際担当課長","answer":"委員につきまして、年数を明記するというふうな形はとっておりません。審査会としては成熟したものになるのでというご意見をいただきながら、今回も審査委員長の交代という形をとらせていただいたところです。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"改善してほしいと思っているのですけれども、検討というかそういったところもちょっと課題として取り上げていただきたいというふうに、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基金利子が４４万幾らということで書かれているのですけれども、この事業はやっていくという考え方なのか、その点も教えてほしいと求めました。それから、寄附金というのはどういうところから、どういう形で集められているのかということについてもお聞かせほしいと求めました。","respondent":"寺嶋協働・国際担当課長","answer":"３００万円の範囲で予算化していますので、その中で１団体でも多くの方にやっていただければと考えて実施しています。この事業を継続していただきたいという観点がありますので、継続できるような事業を支援したいという考え方から、こういう形で変更したものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この事業は平成２１年度からやってきていて、平成２５年度までに３１件採択をされて補助金を出しているということになると思うのですけれど、この３１件の中で、継続されているというのはどれぐらいになっているのか、またそこら辺での課題というのがありましたらちょっと説明を求めました。","respondent":"寺嶋協働・国際担当課長","answer":"実際に事業がどういう形で継続されているか、実施した後のこちら側の後追いというか状況把握につきましては、今後もっと力を入れていきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この採択をした、そういうところからも団体からのヒアリングなどもぜひしていただきたいと思うのですけれど、その点はいかがでしょうか。５分の１とか、そういう取り組みをぜひしていただきたいと思うのですが、いかがか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"それにつきましては、それについては今年度以降、立ち上げだけでなく継続についても力を入れていきたいというふうに考えているところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこういう取り組みというのは、ぜひ継続できるようにするための支援を、団体の意見も聞きながら今後もぜひ進めていただきたいと思っています。６月からではないようにしてほしいというご要望もいただいたのですけれど、支援を強めていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"受付番号７番は希少疾病ですか、確かにじゃあ事業はどうやって継続するのかなと、ふと思ったところです。審査基準について、この２つはどの点が厳しかったのか、教えてほしいと求めました。","respondent":"寺嶋協働・国際担当課長","answer":"その結果が形を変えても継続されるという、特別な形で今年度だけ実施したいというような説明というふうに審査会では受けとめられましたので。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"適正な審査がされて、それで事業者も納得されたことだと思いますので、また次につながる場合は、ぜひとも検討してほしいと求めました。事業の宣伝でしょうか、できればしながわすまいるネットですか、いかがか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"基本的に情報発信、まず登録をしていただくということで、こちらは事務局のほうからお願いしたところです。実際の見本展なども含めまして、事業ＰＲのほうはやっていただくように、団体に働きかけていきたいと考えております。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"いい事業をされていると思いますので、ぜひともいい意味で宣伝できるような形にしていただきたいし、また進めていってほしいと求めました。こういう形で取り組んでいただける事業者が増えることを、ぜひとも進めていってほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"４月、５月にできなかった団体はもう来年までそういったチャンスがないということになりますので、そのことについては何か余地がありそうでしょうか。何かできない理由とか、その辺をちょっとお伺いしておきたいと思います。","respondent":"寺嶋協働・国際担当課長","answer":"不用額になっていることを考えれば、可能性としてはあり得ることも考えられますので、また研究のテーマにさせていただければと思います。","id":"exchange-012"}]},{"id":"topic-02","title":"品川産業支援交流施設の募集開始","agenda":"品川産業支援交流施設の募集開始","exchanges":[{"speaker":"井上委員","kind":"質問","question":"図のほうで、デッキスペースというのはどこかになるのか、これは無料で誰でも利用できるというスペースなのでしょうか。そこはご説明がなかったのですが。","respondent":"山崎ものづくり・経営支援課長","answer":"４階の鳥瞰図で、部屋の機能としますと、交流室に含まれるものです。交流室という基本的に会員登録が必要な空間の中で、デッキにソファを置いたこのスペースも使用できますです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"では会員登録をしていなければ交流室というところは、ぶらっと来てこのデッキスペースで、１時間当たり５４０円を何らかの形でお支払いしても利用はできないということでよろしいか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"交流室につきましては、デッキスペースエリアも含めた交流スペースを活用していただけるということでご理解いただければと思っています。１時間の料金を払っていただければ、それが条件ですので、どなたでもスペースを活用していただけるというものです。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"延長時間ということで２０時から翌９時という表記になっているのですが、実際にはどういうことを想定しているのかなと。普通だと２０時から２４時とか、２５時とか、これはどういう想定でこういう表記なのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"１０時、１１時、あるいは日にちを超えてというような予約の受付もしてもらえるようなことで考えております。そのイベントが仮に夜中の１２時までのイベントであれば、１２時までの必要な警備ですとか、そういったホールの運営もそれに合わせて対応しますです。","id":"exchange-015"},{"speaker":"井上委員","kind":"意見","question":"２時、３時まで予約したいということになれば、そういうことによって必要経費ということで区の負担部分が増えてくるのではないかと思うのですね。あるいはそれだったら２日分とすれば、翌９時というのが何か現実的ではないような気がするのですけれどとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"可能性として２０時から翌９時という時間外の部分についても、時間貸しを可能にしているというようなことでお考えいただけたらと思っています。基本的には夜中の１２時から６時間借りますというようなニーズがあれば、それにも応えようというようなことで設定しているものです。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"運用してみないとどういうニーズがあるか、ちょっとご検討いただくか、あるいはちゃんと見ていただければなと思います。要望でいいですが、何かこれについて、特にあればお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"そういうときに夜中の作業時間として朝の９時までとって、９時から本番という使い方も、なかなか現実的にはうまく回らないところもあります。委員がおっしゃったそうした意味も含めて、ニーズに適切に対応するような運営を心がけてまいりたいと思ってあります。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"１日借りるとこれだけの料金になって、需要についてどう見ているのかということについて、改めてまたお聞かせほしいと求めました。どんなところがどういう形で使って、需要がどうなっていくのかということをどう見ているのか、お聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"この施設の条例の料金をさまざま区の内部で検討する際に、あるいは稼働率、こういったものを調査しました。そういった料金体系の中で十分需要が見込める、やはり立地がいいというのも品川・大崎エリアの特徴です。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうところで区内が３０％、７割はほかのところからの大手企業が使うというのが、改めて明らかになったなという思いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"ストレートなのですが、４階に便所がないのですけれども、プリントされていないだけか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"トイレの位置につきましては、このパース上には実は４階のほうは表現されておらず、「エレベーターより」という動線のところの外側についております。トイレについてはあります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認ですけれど、確認なのですけれども、思っていていいのですよね。その辺の心配があるので、ちょっとお伺いします。","respondent":"山崎ものづくり・経営支援課長","answer":"夜中あるいは早朝の時間帯にというようなことを想定して、その時間帯にも準備ができるような設定というのがメーンです。範囲を広げて規定をして、細かいところを規定してお貸しするようなことを、細かくやってまいりたいと考えております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"７時間だと幾ら、８時間だとイコールこの金額になりますとおっしゃっていたのですが、それはどういう趣旨で言いたかったのですか。安いですよという意味だったのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"時間貸しも行いますけれども、６時間あるいは７時間の使用ということで使っていただければ、１日の使用料金よりも安価でスペースが借りられますよと。１日の利用料金とそれほど差異がなくなりますということを説明したかったのですが、言葉足らずで申しわけないと思います。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"これから始まるわけですから期待をしておりますが、税金を投入してやるわけですから、一生懸命頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"一つお伺いしたいのですけれども、イベントホールは２分割対応のスライディングウォール設置というふうになっていて、これは２つの別々の団体が同時に使うということも可能にするために、そのような使い方になるのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"１日単位の一括利用というのを基本で考えさせていただいておりまして、こちらのほうは１年前から予約をとります。Ｂ面のほうもあいているところで、同じ日にそれぞれ別の団体が使っていただくような利用形態も可能だということで考えております。","id":"exchange-024"},{"speaker":"浅野委員","kind":"質問","question":"かなり遮音性とかそういうものが担保されているのかどうか、そのことがちょっと気になるところなのですね。うるさいとか、そういうふうな苦情が来る危険性があるかなというのをちょっと心配しているのですけれど、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"ホールの使用について十分に説明をするつもりでおりますけれども、ホール自体も遮音になっておりまして、レベル値があります。楽器演奏までは耐えられないですけれど、ピアノの自然の音ぐらいはシャットアウトするというレベルで設定しているものです。","id":"exchange-025"},{"speaker":"浅野委員","kind":"意見","question":"運用上苦情が来ることがないように、うまく運営していただければと思うんですけれども、この点ひとつとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"例えばここに何か道具を置いてあるのか、その辺のところを確認させていただきたい。それからカフェコーナーというのがあるのですけれども、これは何か業者の方がカフェに入るのか、その辺のことを説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"３Ｄプリンターですとかレーザー加工機など、デジタル工作機器などを配置する予定でございまして、というようなことを想定しております。場所としてはそういう、少し休んでいただけるようなコーナーを設置するというのが意図です。","id":"exchange-027"},{"speaker":"沢田副委員長","kind":"質問","question":"その工房の中のレーザープリンターとか３Ｄプリンターというのは、利用料は別途また個々に取るということですか。払っている部屋のお金とはまた別に、使うごとに別に機器使用料という形で取られるということか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"今のところ、工房の諸室の料金で工作機器も使っていただくようなことで、特定の機器の使用料という意味では徴収する予定はございません。","id":"exchange-028"},{"speaker":"あべ委員長","kind":"確認","question":"それとも条例の下に何かつくるのではなくて、あとは指定管理者との協定で全てを決めていくということなのか、一応確認させてください。朝９時って、朝９時って、こういう施設では一般的なのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"区がそこに協定という形で了解をして決定していくということで、８月１日付予定の協定書でお互いに確認をしてという形の決め方を考えてあります。時間のほうも協定の中でいろいろ工夫できるような条例の規定になっていますので、実態を見ながら検討してまいりたいと考えています。","id":"exchange-029"}]},{"id":"topic-03","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"２番の製造業の現状のところですけれども、「製造業は全ての業種の根幹であり、製造業（ものづくり）の衰退は、地域活力の低下を招く」ということですけれども、ここを具体的に、もう少しわかりやすく説明していただけますかとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"品川区のそうした産業のなりわいも考えて、多様な現状の産業構造にも対応し得るところに支援をしていく必要がありますよと。根っこには、ちょっと説明したかったのですけれども、くどい説明で申しわけないです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"一生懸命やっていただきたいという思いで質問しているのですけれども、その中で、「住宅開発による都市化」ということが出ているじゃないですか。再開発に関しては賛成ですから、住宅開発による都市化はよくないですよと言っているわけですよね、この文章で。","respondent":"山崎ものづくり・経営支援課長","answer":"委員ご指摘がありました引用箇所の説明をするとき、私ども産業振興を所管する立場から見ますと、という言い方をします。産業振興の立場からするとちょっと妨げているというか、そういう現実が見受けられるということでご理解いただければと考えております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"だって現実には減ってきてしまっている、しかし衰退は地域活力の低下を招くわけですから。最後にその辺について、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"長い歴史的な経緯ですとか、先ほどの土地利用の変化に基づいて、そうした数的な特徴が出てきているような状況です。こちらの支援を区のいろいろな支援と重ね合わせるように、やはり地域振興事業部としてさまざまな地域に対する支援をしていく中の一つとして。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問","question":"中小企業全体を見たときの製造業が１割で、情報通信業が４.３％ということなので、その辺の方向性というのはどうなのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"製造の技術が組み合わさって、こうした分野についてはそういう特性を踏まえながら、区としても応援していきたいというのが一つ。それから先ほどの２万２,５８４事業所のうち、効果的な産業支援のあり方を模索しながら、努めてまいりたいと考えているところです。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２６年ですけれども、直近の例えば平成２５年度の状況とか、ぜひ。もっと減っているのかなという思いがするのですけれど、その辺のところがわかったら教えていただけるか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"実は平成２１年の経済センサス－基礎調査を引用して、区分が、この年度をセレクトさせていただきました。直近のものに取り組んでいるところですので、そういった調査の結果が出ましたら、お知らせすることは可能かと思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何かどんどん減っているというふうな印象があるのですけれども、そこら辺の大まかなところで感覚がありましたら、ちょっと教えていただきたいのと。そこら辺の今後区としてどういうふうに、国のほうの流れも含めてわかっているところがありましたら、ちょっと説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした製造業も含めた中小事業者への支援の必要性があるということで、品川区の企業の方々にはそうした国の支援メニューでありますとか、区としてはやってまいりたいと考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中で、自治体の取り組みに対してこうしてほしいというようなことでの、一つは中小企業振興基本条例をつくってほしいと。それから３つ目に、振興会議というものを持ってほしいというような要望が３点出されていたのですけれども、この点に関していかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"したがいまして、今ご紹介いただいた３点については、いろいろやりとりをしているところに通じるものがあるかなというふうには思っております。そういう部分では実施計画でありますとか、非常に検討が必要なのではないかということもあって、要望に対しての回答で。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この中でもやはり廃業させない支援ということもすごく大事だということもありまして、そういうところでどういう支援ができるのかといったことも検討しながら、ぜひ充実させていただきたいと思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"例えば社長がほとんど１人でやっているようなところが、それを教えていただきたいのと、品川区があるのか。いろいろな施策は出ていますけれども、それに対応するような施策になっているのかということを、概略をちょっと教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうなりますと、なかなかそこに対しての対策というのが、非常に難しい側面があるなと考えています。行政としてはしっかり受け持ってやらせていただくことが、支援につながるものというふうには確信して、日々業務をさせていただいているところです。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"やはり病気とか、年齢が高くなるとそういうことも免れない部分も出てくるので、いたし方ないところもあるかと思いますが。どういうところに行っているのかなと、どういう流れ方を全体的にしているのか、わかる範囲で教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"大企業のほうのいろいろな経営方針の転化で、やはり下請け関係を脱却するようなことが、求めなければいけないというふうに思っていまして。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういう意味での中小企業を守っていく、また力をつけていくための大きな手段といいましょうか、施策だということは認識するところです。このＢＣＰというのは大変な体力というのでしょうか、その現状と課題ですか、そこら辺をちょっと教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"したがいまして、今年度につきましては委員のおっしゃったような、実績でありますけれどもＰＲも含めて強力に推し進めたいと考えています。ＢＣＰの策定は東京都のほうでも支援がありまして、十分必要性の高い事業でありますので、しっかり取り組んでまいりたいと考えています。","id":"exchange-040"},{"speaker":"浅野委員","kind":"意見","question":"例えば下請けがそういうことをやっているということは、元請けのほうに対しましてもいいアピールになっていくと思うのですね。こういう企業だったら、例えば多少のことがあっても事業が継続できるという、ぜひともこの事業については引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"中小企業支援の対象という定義、今、情報通信業と製造業というふうに言われてきたのですが、それはここの左の図のところを言うのか、品川区の中小企業支援の対象の定義というのは、どういうふうな捉え方をしているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"というか、品川区はどういうふうに。中小企業支援の対象はどこか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"いわゆる法的に中小企業と申しますのは、従業員で言いますと先ほど来、３００人未満でありますとか、業種、業態によって資本金の金額が若干違います。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"その９,０００件の、主に左の図でいくとどういったところが特徴的なのかというのは、ここでわかりますか。どこが主に、その９,０００件の中の多いところ、そういう統計とかはないのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"細かい融資の数字はないですが、実際に９,０００件の中でどのような業種、業態かという基本的な数字はあります。それから、やはり現場で物をつくる、あるいは製造業、卸売・小売業、情報通信業、運輸業といったようなところです。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"今、経営者の問題ということで後継者がもういらっしゃらないという部分については、もう支援をするということではなくなるのですよね。２階は住んでいるという、住宅政策だけでなくて一つこれから進めていくべき施策だろうなと思っているのですが、どうか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"今、そこを公共として活力ある空間として利用するという意味では、ちょっと悩ましいところもあるなというのは思っていまして。そこの活用について今こちらのほうでというのは、ちょっと頭に浮かぶものは正直ございませんけれども、そういったところでご容赦いただければと。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"融資は９,０００件でも相当の金額、もう少しきめの細かい支援というのが必要かなというふうにも思うのですけれど、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"私ども今日いろいろご紹介させていただいた基本的な考えのもとにさまざまやってございまして、エリアでちょっとルール化しようと。区全体の大きなテーマ、課題として、研究していくようなことというのは必要かなと考えています。","id":"exchange-046"},{"speaker":"沢田副委員長","kind":"意見","question":"簡単にそういうことができる時代だと思うのです。１歩、２歩進んでいくには、その辺のお考えをもう一回改めて聞かせてくださいとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"には目立つようにＰＲをし、販路を拡大すると、さまざまなフェーズがあると思うのです。企業が企業体として競争力を高めるような段階別の支援を、あるいは場合によっては財団法人などと連携して取り組んでまいりたいというのが。","id":"exchange-047"},{"speaker":"沢田副委員長","kind":"質問","question":"行政としてできる大きなことなのかなとそう思って、今、質問させていただいたのですけれども。その辺のことで、具体的にこのあたりは今後どういうふうになって、現状と今後の方向性というのはどう考えられているのか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"本体の品川区の企業が力をつけていくための海外進出の支援の一つとして、引き続きそうしたところには取り組んでまいりたいと考えております。","id":"exchange-048"},{"speaker":"あべ委員長","kind":"質問・要望","question":"これは質問というより今後の進め方ということで、要望ということでします。これは全体で足すと１２億ちょっとぐらいあるのでしょうか、先ほどおっしゃったように融資あっ旋事業が７億円弱で、シルバー人材センターなのですね。","respondent":"山崎ものづくり・経営支援課長","answer":"こういう分野も財団法人のほうと区の産業振興の役割分散をしながら一緒にやっていこうという基本方針で、旬な、検討中のところでございまして。施設の運営にかけるわけではないのですが、区としては最適な方策を一緒に勉強してまいりたいと、正直そんなふうに考えております。","id":"exchange-049"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、情報管理を徹底するように求める通知を出したという形になっているのですけれども、教えていただけますか。","respondent":"井浦戸籍住民課長","answer":"ただいま委員からお尋ねのありました通達につきましては、総務省で平成２６年６月に全国の自治体にまいりまして、品川区でも受理をしております。総務省のほうで全国に求めている責任者の設置、平時より総務省とも連携をとりながら、品川区としては１件もございません。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":47301,"voices":118}},{"id":"h26-20140722-7","meetingId":"h26-cm07","date":"2014年7月22日","dateIso":"2014-07-22","committee":"厚生委員会","time":"午後１時００分～午後３時５７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"（仮称）東五反田四丁目認知症高齢者グループホーム等の整備および運営事業者の公募","agenda":"（仮称）東五反田四丁目認知症高齢者グループホーム等の整備および運営事業者の公募","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"少し伺いたいのですけれども、区内に何カ所あって、またこの整備の考え方。今回、こういう条件をつけているという中で、そういう条件を示す際の考え方を説明を求めました。","respondent":"大串福祉計画課長","answer":"先般の条例審査のときにもご説明させていただきましたが、いわゆる個室ユニット型の特別養護老人ホームというのは、区内の法人ではやっておりません。１０カ所もう整備が終わっておりますし、１５法人ほど、このような規定をさせていただいているといったところです。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今回１カ所整備されるということで、この１３地区に１カ所ずつ整備された後の状況というのは、今後のその辺の考え方をひとつ教えていただきたい。基本は、やっぱり区内法人ということなのか、その辺りを説明を求めました。","respondent":"大串福祉計画課長","answer":"今後また、そういった地域の中で、適地等々があれば、グループホームの整備についても検討をしていきたいと考えております。違った要件が出てくれば、区内に限らず広い範囲で公募をかけするといったことも十分に考えられるかと思っているところです。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"確認","question":"２点目のほうの確認で、ちょっと私今、文章を読み違えていたのかもしれないのですけれども、区外法人でも区内で２年以上の実績があるところは公募の対象なので、１５法人ということでいいのですよね。","respondent":"大串福祉計画課長","answer":"はい、必ずしも、いわゆる区内でずっとやっている法人とは限りません。区内で２年以上実績があれば、本拠を区外に置いている法人でも対象になってくるといったところです。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、これを品川区が審査をするわけですよね、書類審査、プレゼンテーション等々。審査する品川区の体制は、どのようになっているのでしょうか、説明を求めました。","respondent":"大串福祉計画課長","answer":"我々健康福祉事業部の管理職といったものが中心となって審査をさせていただき、最終的には、区長決定を仰ぐというような形で進めていく。このような形を考えているところです。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"もちろんそうだとは思うのですが、何となく気になったのは、これは、相当詳しい資料を業者が出すようにしていますよね。例えば運営収支のシミュレーションも出していただくわけですから、この運営母体は収支、品川区にいるのかという確認をお願いしたいです。","respondent":"大串福祉計画課長","answer":"すみません、説明が不足しておりました。このような流れを考えているところです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"確認","question":"同じような形で、これから公募をほかのところでもかけていくわけですよね。それを行政側が客観的に評価をして確認できるシステムがあるかどうかということが、もう一声欲しいのですが、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"あるいは入居される方の処遇の向上といったものは望めるかどうか、こういったソフト部分の評価、これがまずは一つ大きなポイントになってまいります。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"区内の資格に絞っているわけですから、これを例えば全国に向けてとなると、いろいろなところが入ってくる可能性がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この旧品川社会保険事務所の土地を取得するまでの経緯、前に説明があったのかどうか、ちょっと記憶にないのでもう一度お願いしたい。今回が１１カ所目ということですけれども、残りの２カ所はどの辺の地域になるのか、教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"それに基づいて、区のほうといたしまして検討を重ねたところ、区のほうで、この旧社会保険事務所の跡地の購入を決めたといったところです。１３カ所というところで目標を掲げておりますが、適宜、判断をしていきたいと考えているところです。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういうことは、あまりないことなのでしょうか。品川区内でもほかに、要は品川区が買いますと言えば買える土地は、こういった国の所管の土地でも何カ所かあるという状況か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"の品川児童学園戸越ルームの開設","agenda":"の品川児童学園戸越ルームの開設","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"相談をするまでというのは、品川児童学園にまず連絡して、そちらの地域の方だったらこの戸越ルームのほうになりますということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"本園のほうで相談の受け付けをします。その中で、本園の南品川でインテークを行う方と、戸越ルームでインテークを行う方ということで振り分けをする予定になっております。","id":"exchange-010"},{"speaker":"山元委員","kind":"質問","question":"本園と振り分けをするということなのですけれども、そうすると、ある程度は、地域性と、内容等もあるでしょうけれども、その地域に近いということではなく、内容によって分けるのでしょうか、その辺どうなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"ただし、本園でないとできない相談といたしまして、各種の専門相談があります。こちらの戸越ルームでやりますのは、心理職を中心とした育てのところの相談ということになってまいります。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"３番の表のところで、月曜日と木曜日の午後に斜め線が入っていて、午前は何も入っていないのですけれども、何か意味があるのかということ。ちょっと僕も可能かどうかわからないのですけれども、そういうことも考えているのかどうか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"午前のほうが、線が抜けているのですが、すみません、こちらは午前も閉めさせてする予定になっております。もしモデル的に何か事業ができれば考えられないかということは、今、考えているところです。","id":"exchange-012"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"そういったことについて、その必要な子どもたちに対しては、手話による指導をしているのでしょうか。お願いいたします。","respondent":"中山障害者福祉課長","answer":"年齢に応じた縦の部分と、関係機関による横の連携、できるだけそれぞれのサービスのすき間から漏れることのないような対応が必要だと考えています。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、先ほどの手話の話に戻りますけれども、一部のところでは、手話言語法の制定を求める動きがあるということも聞きました。手の話、手話を、今の日本語、言語と同じような形にしてくださいと、法整備を求める動きがあるとお聞きしました。","respondent":"中山障害者福祉課長","answer":"医療依存度の高い子どもに対して、どういうサービスができているかというところは、実は非常に難しいところだと考えています。２３区の中におきましても、６区が、現在可決している状況です。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"制度は確かにあるのは助かるし、なかったら大変なものですから、ありがとうありますという話はたくさん聞きます。今さまざまなことを勉強する中で、関心を持っていますので、何かしら対処していこうということだけお話をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問","question":"特に2)の医療を必要とする場合のショートステイみたいなものは、入所でないとできないのかということ、それが１点。そういう状況等の教育委員会との共有の仕方というのですか、連携の仕方というのですか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"１点目の障害児入所支援のところになりますが、これは実施主体が都道府県ということで、権限外ということになっております。何かしらそういった情報シートの作成であるとか、親御さんへの理解の求め方であるとか、そういったところを考えていきたいと思っているところです。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"確認","question":"これは法ではないのですかね、区ではこういうものを設置してはいけないのかどうか、そこの確認。今後やっていくという話なのですけれども、その辺について、もう一言、何かあれば伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"障害児の入所支援ということになりますと、区で、ここの部分に携わることは難しいかなと思います。その計画相談を主軸に各関係機関が連携して、今年度、課題を解決していきたいと考えているところです。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"療育支援ネットワークの会議を開催していると書かれているのですけれども、これはいつ頃から、どれくらい開催されているのか。年間何回とか、１ヶ月何回とか、そういう定期的なものなのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"実はずっと療育支援ネットワークというのはあったのですが、昨年度は１回も開催できないで終わってしまいました。今年度につきましては、先週、第１回目を開催いたしまして、年度内にあと２回開催する予定です。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ここで話し合われたことが、どのように障害児やその親御さんに返されていく形になるのですか。そういった会議を開いて、その後どうなっていくのか、経緯を教えていただきたいのです。","respondent":"中山障害者福祉課長","answer":"関係機関が連携することで、この療育支援ネットワークはありますので、逆に区の相談支援のところで発揮できればと考えています。自立支援協議会の中で子ども部会というのを持ちまして、区内の療育支援ネットワークと、そんな場になっていければと思っているところです。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"わかりました。一つ、Ａ３版のほうの、巡回相談と保育所等訪問支援の違いを詳しく教えていただきたいのですが。","respondent":"中山障害者福祉課長","answer":"これは個別サービスになりますので、その子どもに対して、保育所等訪問支援というサービスを支給決定して、給付として行うものです。子どもがよい環境につながるもので、保育所等訪問支援のほうは、子どもに直接個別給付として行うものになります。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"保育所等訪問支援のほうは、私立保育園も区立保育園もどちらも、親御さんから相談があれば行くというものか尋ねました。","respondent":"中山障害者福祉課長","answer":"保育所等訪問支援は個別給付になりますので、そういうことになります。こうした近隣区であれば、保育所等訪問支援ということで、相談員が直接現地に赴くようになっております。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"ふれんどりー事業のことでお伺いします。ちょっと伺ったところによると、みたいなことをちらっと伺ったのですが、将来的にそういうお考えがあるのかどうか。","respondent":"中山障害者福祉課長","answer":"こうした支援員を使った外出サポート事業ということを、やりたいこと、もうしばらくは中学生を対象に考えていきたいと思っているところです。民間のほうで行ったりもしておりますので、そういった民間のほうの事業も活用しながら、居場所の支援ができればと考えているところです。","id":"exchange-022"},{"speaker":"山元委員","kind":"意見","question":"ふれんどりー事業に関しては、やはり親の負担を軽くするためにも、ぜひお考えを早めに小学生も対象にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こちらは法改正が必要ですから、品川区でどうこう言うことはできないと思うのですけれども、同じ条件はあるわけです。さまざまな形で国に対して法改正を求めていく中にあって、それは要望として伝えておきますが、いかがか尋ねました。","respondent":"中山障害者福祉課長、太田品川保健センター所長","answer":"こうした方々の支援をどうしていくかというのは、一番支援を必要とされている方、個人情報を管理していけるようにしていきたいと思います。特に注意が必要な方は、ケースワーカーの中でもやり取りをしていくような… １歳６カ月および３歳児健診で、自治体間で情報を共有して、療育に結びつけられるようにしております。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363412?Template=document&Id=3392#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":24773,"voices":77}},{"id":"h26-20140722-8","meetingId":"h26-cm07","date":"2014年7月22日","dateIso":"2014-07-22","committee":"建設委員会","time":"午後１時００分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 「平成２６年８月都営住宅入居者募集","agenda":"」を聴取いたします。 「平成２６年８月都営住宅入居者募集","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"５月の都営の入居募集に対して、実際にどう決まったのか、わかったら教えていただきたいのです。品川区内で決まった分と、それから全体的な東京都の入居者、わかったら教えてほしいと求めました。","respondent":"矢木住宅担当課長","answer":"定期使用住宅、これは若年層向ですが、１６.３倍です。東京都のほうの全体の平均倍率は把握してございません。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"今、３０.２倍と、１６.３倍というのは、品川区内の倍率ということで受けとめていいですか、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":5626,"voices":18}},{"id":"h26-20140722-9","meetingId":"h26-cm07","date":"2014年7月22日","dateIso":"2014-07-22","committee":"文教委員会","time":"午後１時００分～午後３時０７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"いじめ防止対策の取り組みについて（概要）","agenda":"いじめ防止対策の取り組みについて（概要）","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"アイシグナルについて、詳しくどのように取り組まれているのか説明を求めました。","respondent":"渋谷指導課長","answer":"書き込んだものが業者を通じてすぐ指導課のほうに来て対応できるというような仕組みです。今年度は生徒手帳に入る大きさのカード型に新たに刷り直したものを全生徒に配付して、少しでも声がかかるようにというふうな工夫をしています。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"意見","question":"実際に子どもたちがどういったことで、こういったときにはこういう対応をというのをしっかりと、現実に沿った指導をぜひやっていただければと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"左下の、目安箱、アイシグナル、専用電話それぞれありますが、傾向を教えてほしいと求めました。６７９件の総数の中で、目安箱とまた専用電話で特色が違えば、それもお知らせください。","respondent":"村尾学校支援担当課長","answer":"２番目に多いのが今度は１１月ぐらい、夏休みが終わって、２学期が始まってちょっとしたらまた子どもたちのほうで目安箱に入れているというものです。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"もう一つ、今主に小学生で目安箱の投書が大半という中で、学年のばらつきというのはあるものなのでしょうか。やはりしっかり意思を伝達というと高学年になるのかなと思いながら、その辺の傾向と、もう一つ男女比率、この辺は把握されているのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"入れたからこちらも対応の仕方を慎重に、慎重にその子に、またはその加害の子どもたちには対応するというところであります。その分、逆に、特に中学生の悩みをどこか出せる場所を十分確保していくということで考えているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、加害等々の子どもにも聞くわけですから、聞かれた子どもは何だとちょっと思うのじゃないかなと思うのですね。それは必要なことだと思うのですけれども、そこがかえって怖いかなとちょっと思うので、その辺についての考え方をひとつ伺いたいなと思います。","respondent":"渋谷指導課長","answer":"今回、目安箱で、先ほど説明があったように、３年生、４年生の取り組みが非常に多いというふうにご説明申し上げました。これを継続していくことによって、今は少ないのですけれども、一つ一つ丁寧に対応していくことで実績が上がっていくのかなと考えているところです。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"個人的ないろいろなＬＩＮＥですからそこまで見られるわけじゃないですから、ちょっと見えていないので質問するのですが、ああ。テーマに挙げたものをどう具体化していくか、教育づくり、どういうふうにしたらいいのかという考え方を区が持っているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"確認","question":"各家庭で対応できることとそうじゃないこととあるけれども、各家庭での対応で終わらせてはいけないというのが私は一番言いたいところなのですね。みんなで決めてみんなで確認していく、確認をする必要があるのではないかなと思うので、そこを強調していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"平成２６年度のテーマが、もし、可能な範疇でそういう人ですよというのをまず教えてほしいと求めました。","respondent":"村尾学校支援担当課長","answer":"この根絶協議会のメンバーの中には、特にその専門の方というのは入っておりません。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"そうしたツールというのは、時代の利便性があるから使わなければいけないわけで、それを活かした取り組みというのがあると思うのですね。その辺、今後協議会はあと２回ある中で、そういった観点もやったらどうかなと思うのですけれども、この辺、いかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"いわゆる研修会、先生であったり子どもたちにどんな研修ができるかということも含めて、少し話を聞いたところです。本当に、その危険性みたいなものを十分把握し、それを対保護者であったり対子どもであったりということについても進めていければと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"話し合いの一つとしてやってもいいのかなと思いますので、そのあたりも含めて、今後検討していく感じかなと思います。雰囲気づくりというのでしょうか、今どういうことをやっているよ、一生懸命心がけているよということを説明を求めました。","respondent":"村尾学校支援担当課長","answer":"目安箱という一つのツールがあるのですが、先生たちが反省するのは、ある意味反省という部分で広がっているのは事実です。とにかくいじめをしてはいけないのだよということを１回だけではなくていろいろな場面で繰り返しながら、各担任のほうに広げているような現状です。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"教育委員会としての先生の支援も含めて、先生一人ひとりがそうした意識を１人でも多く深めていただいたらいいというふうに考えております。先生も児童生徒も善の競争というのでしょうか、ここだけ、もし何かお考えがあれば説明を求めました。","respondent":"田村教育次長","answer":"ですから、自分だけで抱えるのではなく、自分１人で苦しまないでいつでも相談してというのがまさにこの全体の取り組みなのかなと思います。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"２点ほど質問があります。どのようなお考えか、その２点、お願いします。","respondent":"渋谷指導課長","answer":"それは来年度も多分そういった方向で、やりたいところには十二分に活用していただくという方向でいこうというふうに考えているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"全校が積極的になっていただきたいなという私どもの要望、希望を申し上げたいと思います。どうですか、私の気持ちを聞いていただきたいと思うので、何かありましたらお願いいたします。","respondent":"田村教育次長","answer":"要は、一貫校で、逆パターンもあるのですね。そうすると、プラス面と、あとは親御さんとお子さんでそれぞれケース・バイ・ケースの選択をして対応しているというのが実態だと思います。","id":"exchange-013"},{"speaker":"高橋委員","kind":"質問・要望","question":"２点で、１つは、その成果と課題について教えていただければ。ちょっとごめんなさい、ここの中で見えなかったのですが、どういうような形でいじめについて対処しているのか。","respondent":"伊崎子育て支援課長、渋谷指導課長","answer":"必ず学校の方と連携をとって、地域で支えていくという視点に立って、手をとり合って連携して取り組んでいるところです。逆に、こういった子どもにこういったところを少し見ていてほしいというようなご依頼があることもありますので… それから、会場校によって事例検討のやり方が若干形式的になったりだとかということで、昨年度はやり方についてのご意見も幾つか上がってきたです。","id":"exchange-014"},{"speaker":"高橋委員","kind":"確認","question":"どうもありがとうあります。今度、小学校のときにこうだったけれども中学校はどうなのですかというのを実際に先生方でお話をされる機会としては大変有効な機会だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤副委員長","kind":"質問","question":"いわゆる人格向上教育というものをしっかり教えていかないと、ですから、聞かせてください。","respondent":"中島教育長","answer":"今のご質問はまさにそのとおりだと考えております。先行的に取り組んでいる品川の市民課におきましては、この週３時間を使って子どもたちが学ぶ時間を大切にしていきたいと考えているところです。","id":"exchange-016"},{"speaker":"須藤副委員長","kind":"質問","question":"おまえどうなのということをやると、いいんだよと言うと、また周りがそのことを認めてくれるというような方向がグループの中で出てくると思うのです。ですから、こうやってしっかり教育委員会としてもしていますというようなものを考えておかなければいけないと思うのだけれども、いかがか尋ねました。","respondent":"中島教育長","answer":"そういった実学的な、体験的な場面に大人がかかわるにしても、知っていてかかわるのと知らないでかかわるのでは大きく内容が違ってくると思うのです。そういったところで理解を深めながら、市民課をメインに、子どもたちに教えつつも体制もつくっていければなと考えております。","id":"exchange-017"}]},{"id":"topic-02","title":"家庭の日制定４０周年記念事業","agenda":"家庭の日制定４０周年記念事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"募集作品ということで２種類説明があったのですけれども、2)のほうは作品が写真かなと思うのですが、何でもいいということなのですか。絵だとかあるいは工作物だとか、これはつくりたいと思ったご家庭なり子どもさんの出してくれる作品はどれでも受けとめるということなのか尋ねました。","respondent":"福島青少年育成課長","answer":"しながわフォトコンテストで、全て写真を撮って送って、作品をつくってそれを撮ってでもいいですけれども、基本は写真です。","id":"exchange-018"},{"speaker":"南委員","kind":"確認","question":"これは４０周年の記念事業ということで、３種類の事業を明らかにしていただいたわけですが、４０周年の記念に限ってではないということですか。そこの確認と、今まで家庭の日というのは改めて、去年からかしら、位置づけられたのですが、それ以前はどんな事業をやっていたのか。","respondent":"福島青少年育成課長","answer":"ただ、これを継続するかどうかにつきましては、実際にやってみて成果があればというふうに考えてはいます。ですから、３に加えて１、２が行われているというものです。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、家庭の日制定４０周年の記念で、なかなかわかりづらいなと。家族と何が接点なのかなというので非常に疑問に思うのですけれども、その辺のテーマ設定というのはどのようにされているのか尋ねました。","respondent":"福島青少年育成課長","answer":"ただ、これは相当拡大解釈していただいていいというふうに私どもは考えてあります。毎月毎月似たようなものになってしまう、それはそれであまりおもしろくないかなということもありまして、こういうテーマ設定を入れました。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"幼稚園とか保育園とか小、中と、わかりました。ただ、せっかく選んだ作品をもうちょっといろいろなものに載せたらいいのではないかと思うのですけれども、その辺の考えをお伺いします。","respondent":"福島青少年育成課長","answer":"こちらの表彰した作品につきましては、もちろんホームページ等では掲出はします。そこへ持ち込んでということもあって、商店街連合会が運営していますので、その辺の強みは発揮して発表していきたいというふうに考えております。","id":"exchange-021"}]},{"id":"topic-03","title":"「居住実態が把握できない児童」に関する調査","agenda":"「居住実態が把握できない児童」に関する調査","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"調査方法等も示されていますが、一つお伺いしたいのが、例えば不達通知というのですか。そこがどのようになっているのか説明を求めました。","respondent":"伊崎子育て支援課長","answer":"厚生労働省の、全国的に「養育支援を特に必要とする家庭の把握及び支援について」ということで、支援を強化するようにという依頼が来ているものです。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"確認","question":"税務課も戸籍住民課も含めて、さまざまなところとしっかり連携して実態把握をしていただければなというふうに思いますので、よろしくお願いします。これは保護者だけで確認をしたということですか、ちゃんとお子さんも確認なのか、その辺を説明を求めました。","respondent":"野呂瀬学務課長","answer":"これは具体的には５年生なのですけれども、保護者の妹さんに電話確認をとって、その後保護者の連絡先を入手して、子ども共々中国にいるという確認をとったというふうに聞いております。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"未確認は今日現在で９名だということなのですけれども、この９名を今後どういうふうにしていくのか、最後まで確認していく必要があると思うのですね。ですから、その辺のことも教えてほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"調査をかける前に再度家庭訪問をして行う、調査をかけていく予定です。それにつきましては、児童相談所と連携をとりまして、対応は図っていくところです。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"１４から５を引いて９、９人が未確認だということで、教えていただきたいのです。細部の打ち合わせをしながらきちんと確認していくことが大事だというふうに、決意というのかしら、その辺をしっかり伺っておきたいなと思います。","respondent":"伊崎子育て支援課長","answer":"児相との協議会、話し合いをもちまして、対応を進めているところです。庁内の対応としましては、ケースについて、それぞれが役割の中でやれることをきちんとやっていこうです。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"きちんと取り残されることのないようにしていかなければいけないわけですから、改善させていただけるように取り組んでいただきたいなと。改めてしっかりとやって、今後こういうことが社会問題化にならないように取り組んでいただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"今後の思いというか方向性というのを、ぜひ品川区として、子ども未来事業部の金子部長にぜひお伺いしたいなと思います。","respondent":"金子子ども未来事業部長","answer":"さまざまなセクション、教育委員会も含めて、共通認識を持っていこうというために行ったものです。先ほども説明がありましたとおり、児童相談所を含めて、区の機関以外の機関とも連携をしながら追究していきたいというふうに思っています。","id":"exchange-027"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"下に指定校が列挙されていますが、先ほどの希望をとった上で、申請があって選定したと。あるいは、これはオリンピックに向けて来年度以降拡充する方向なのかどうか、その点をあらましを説明を求めました。","respondent":"村尾学校支援担当課長","answer":"申請につきましては、小学校が６校、それから中学校、一貫校の中学校も含めてですけれども、３校ということになっております。都のほうから小学校３校、中学校２校程度という縛りがありますので、この３校と中学校２校を都のほうに上げたです。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"質問","question":"それとまた違った、同じ枠にプラスアルファの部分なのか、講師がつくことによってどんな充実が考えられるのですか。きめ細かく見ることができるのか、あるいは時数自体、そこは特化して増やしていくのかとか、その辺のあらましを説明を求めました。","respondent":"村尾学校支援担当課長","answer":"学校によってはさまざまな体力向上の取り組みをしている中で、器具的なものに予算を使うというのが大きいところかなというふうに思っております。","id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問","question":"その中では、今年指定した学校が継続して希望された場合はそちらを重視するのか、その辺の仕組みのところを教えてください。かなり有名選手からとてもマイナー競技まであって、品川はそういったところはどういうふうに展開されたのか、傾向を説明を求めました。","respondent":"村尾学校支援担当課長","answer":"都としては、１年、１年でどんどんいろいろな学校を指定して広げていくという方向ではないかなというふうに私は考えているところです。特に１学期、２学期以降になるとは思うのですが、もう少しそういう関係筋で当たっているというのが正直なところかなというところです。","id":"exchange-030"},{"speaker":"石田（し）委員","kind":"確認","question":"これは確認ですけれども、これは都の事業なので、なかなか区がどうこうというのは難しいのかもしれませんが、これはオリンピックまでは続けていくというのが都の方針なのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"現実的には、オリンピックが開催されるまでさまざま広げていくというような流れだと思います。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問","question":"例えば部活動とかもうちょっと、例えば運動といっても体育の授業だけではなくて部活動というのが出てくるわけではないですか。品川は、その辺は、部活動と授業という分け方というのはどういうふうになっているのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"講師という部分で週２０時間なので、実際に授業だけではなくて休み時間にもさまざまな活動をする中に入って取り組んでいるという学校もあります。現在この５校については、その学校の全ての子どもたちの体力づくりというのを基礎に、実際に講師を活用しているという現状です。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"３の取組内容の必須以外の中のエについてなのですけれども、地域のスポーツ大会やスポーツイベントなどの運営を支援する取り組みをやった場合にということになると思うのですけれども、これのもう少し具体的な内容とかこういったものですよという例があるのであれば説明を求めました。","respondent":"村尾学校支援担当課長","answer":"さまざまな取り組みとして、いろいろな条件、人を呼んできて走る練習の仕方とかというのをするようなことが実際このエに当たるかなというふうに思います。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"ここの３の取組内容というのは、そういうのが当たるよねという決め方で文字で上がってきているのか、そこだけ説明を求めました。","respondent":"村尾学校支援担当課長","answer":"これは都教委のほうからこの流れがぽんと出てきて、学校はこの中で何ができるかなというので探す方法です。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問","question":"わかりました。では、というと、今、城南第二小学校以外はそういったものは今のところは挙がっていないということか尋ねました。","respondent":"村尾学校支援担当課長","answer":"実際には各学校から上がってきている企画書のほうには出ていないですが、時に地域運動会があったりいろいろなものがあるときには、そこに加味してやっていくということはできますので、そういう流れです。","id":"exchange-035"},{"speaker":"つる委員","kind":"質問","question":"その都度、指定校、手を挙げる学校というのが変わるのですか。それとも、今回の小学校、中学校５校がずっとある程度何年間か続けていくのか、このあたりは。","respondent":"村尾学校支援担当課長","answer":"例えば今出ている指定校ですごく成果が見られる部分については継続させようかとか、またはもっと新しい地域的なものも考えたりしながら継続するものもあるし、もっと違う学校をどんどんやっていくという考え方も一部あります。","id":"exchange-036"}]},{"id":"topic-05","title":"の順番では３の行政視察についてですけれども、先に予定表の４のその他","agenda":"の順番では３の行政視察についてですけれども、先に予定表の４のその他","exchanges":[{"speaker":"南委員","kind":"質問","question":"１１月に国と等々のという説明のところなのですけれども、当然今年の１１月という理解でいいのですよね。もう一回その辺を、国とどことかというのをちょっとメモしそびれてしまったので、すいません、説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そして、今度、区と事業者との間で契約を結びますので、その２つの契約をあわせて１１月中に行います。そのため、開設時期につきましては、６月１日の開設ということで予定しております。","id":"exchange-037"}]},{"id":"topic-06","title":"続きまして、３の行政視察","agenda":"続きまして、３の行政視察","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。食育のところなのですけれども、これは給食とかも関係してくるのかなという、これは給食は食べられるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":41700,"voices":133}},{"id":"h26-20140722-5","meetingId":"h26-cm07","date":"2014年7月22日","dateIso":"2014-07-22","committee":"総務委員会","time":"午後１時００分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"の品川区史の刊行","agenda":"の品川区史の刊行","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"一つだけ。今後の活用と言ったらいいのでしょうか、どういうふうにこれを位置づけて、ご説明いただけますか。","respondent":"江部総務課長","answer":"各５地区で説明会といいますか、そういうところでちょっと説明をすることとか、仕事としても役立てるというような２つの方法で考えているものです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"意見","question":"１,５００部作製して、おそらく５００部は関係者にお配りして、１,０００部は販売という感じかという思いがするのですけど、販売する場所というのは、区政資料コーナー、そこだけなのか、それとも地域センターとか、図書館とかなのか、そこだけ聞かせてくださいとの意見を述べました。","respondent":"江部総務課長","answer":"区役所での販売場所につきましては３カ所ございまして、総務課と区政資料コーナーと、それから品川歴史館の３カ所です。書店商業組合が十数店ありますけれども、そこでご協力いただきまして、この２２日から一斉に発売が始まります。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"文章とかあると思いますが、それについてはどのような考え方でしょうか。著作権とかいろいろあると思いますけど、全て公開という形にしてしまうのか、いかがか尋ねました。","respondent":"江部総務課長","answer":"電子化と申しますのは、全部を電子化して、同じものを職員が見るというのではなくて、仕事に役立つ部分、使う部分を有効活用しようというものです。一般の方につきましては、電子書籍販売といいますか、それは今事業検討しておりますが、無償でということではございません。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これを販売して、何か、中から抜粋したという形をとるとなると、それは例えば区のほうの許可が必要になってくるということでしょうか。その場合に、許可制なのか、それとも自由に引っ張ってきていいのか、その辺はいかがか尋ねました。","respondent":"江部総務課長","answer":"基本的に書籍、ＤＶＤを含めて著作権は品川区が持ちますので、営業目的でほかに転用ということは禁じられているものになると思いますが、小さいグループでコピーして勉強会に使うとか、そういうことはあろうかと思います。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"その場合に、内部の団体といっても、どういう団体なのとか、結局広報的な活動をするときもあると思うのです。そこら辺のある程度の考え方をお聞きしたいと思っているのですが、いかがか尋ねました。","respondent":"江部総務課長","answer":"先ほどの繰り返しですが、やはり著作権は品川区ですので、基本的には書籍のルールにのっとっての運用という形になろうかと思います。","id":"exchange-005"}]},{"id":"topic-02","title":"東品川公園改修工事請負契約","agenda":"東品川公園改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区の強い意向に基づいてつくる工事というのですか、コンセプトについては、契約上はどういう関係になるのかというのを一つ伺いたいと思います。この公園にはどういう位置づけなのか、どういうふうに今考えていらっしゃるのか、あわせて教えていただきたい。","respondent":"立川経理課長","answer":"そういったものでラフというものがその時点ででき上がりましたので、それを参考に添付しまして、実施設計等につなげているです。通常は自転車置き場になっているのですけれども、災害時に災害用トイレとして使えるというような、そういった設計です。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、当初予算が１億８,０００万円だと思うのですね。１億７,３００万円の予定価格を出しているということなので、この部分との整合性というか、まず最初にこのところだけちょっと教えていただきたい。","respondent":"立川経理課長","answer":"当初予算を組んだ時期と実際に発注する時期としましては、当然労務単価であるとか積算単価が変わっておりますので、その辺につきましては、予算におさまるように一部設計変更等を実施して発注しています。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすると、この理解としては、今の答弁ですと、この工事概要を若干下げたという理解、当初の予算で組んだときよりも、工事概要というか、工事の内容が縮小されたという理解でいいのか、そこだけ改めてとの意見を述べました。","respondent":"立川経理課長","answer":"縮小というところまではいかないですけれども、やはり使う部材とか、そういったところを費用対効果というか、その辺については厳選していくということを聞いております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"もちろん入札ですから一番安いところが落札するのはわかるのですけれども、品川区の思いというのが、金額だけではないところもあると思うのですよね。そこはどういう調整をされているのか尋ねました。","respondent":"立川経理課長","answer":"入札を公告しまして、その後事業者のほうは参加するかしないかというところにつきましては、詳細な設計書、それからまた仕様書をご覧いただくということになっておりますので、その中に設計のコンセプトであるとか、そういったものが記載しています。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"結局今回落札したところとほかの２社を比べると、設計図を示して、このとおりにやってくださいということになるのですか。だから、要は金額関係を考えたときに、どの３社に頼んだとしても、同じものが出てくるという理解でいいのか尋ねました。","respondent":"立川経理課長","answer":"同じ工事、やはり各事業者によって方法であるとか、そういったことでいろいろな工夫を重ねて経費を節減しているというふうに聞いております。ですから、同じ出来栄えであっても、かかる経費というのはそれぞれ事業者によって多少違ってくるのかというふうに考えているところです。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"でも落札したほうは落札したので、私たちの中では、約束どおりにしていただくというのが当然のことだろうと思うのですよね。それよりもかなり下げられているということになると、なぜこの計算に違いが出てくるのか、その差についてはどう考えられているのか尋ねました。","respondent":"立川経理課長","answer":"今回の公園改修工事の落札率につきましては、９６.１２％でございまして、例年落札の平均というのを出しておりますが、おおむね９０％台の工事につきましては前半ということですので、通常の範囲内というふうに考えております。","id":"exchange-011"}]},{"id":"topic-03","title":"の東品川公園弓道場改築工事請負契約","agenda":"の東品川公園弓道場改築工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"これは１億８,０００万円で、１億５,０００万円だから、３,０００万円のあい差があるわけですよ。厳選をして３,０００万円分のあい差、当初予算との関係で、どういう見方をしたらいいのかということだけ説明を求めました。","respondent":"小林施設整備課長","answer":"鉄骨だとか、そういう専門業者のほうにヒアリングを行って、金額を出してもらっています。そちらのほうのウエートで、ヒアリングで聞いている単価でやっておりますので、今回はそんなに差がなかったです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"最初の予定価格と当初予算が３,０００万円違うではないですか。３,０００万円というのは結構あると思っていて、そこら辺はどういうふうに整合性をとってやっていらっしゃるのかというところをお聞きしたかった。","respondent":"小林施設整備課長","answer":"これを別途発注しておりますので、そちらのほうの案件は今回この物件には該当しなかったです。失礼いたしました。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"団体なのか、そういうところと調整しながら、要するにどんなふうに調整しながら進めているのか伺いたいと思います。","respondent":"小林施設整備課長","answer":"そちらと一応打ち合わせをしまして、そちらの中に設計の中に入ってくる今言った基準関係、いろいろもろもろあります。ここについては、品川の弓道連盟に入ってもらって、そちらのほうと打ち合わせをしながら、基本設計、実施設計を進めてきたところです。","id":"exchange-014"}]},{"id":"topic-04","title":"東品川一丁目付近下水道管再構築工事その２請負契約","agenda":"東品川一丁目付近下水道管再構築工事その２請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"全体像をご説明いただきたいのと、要するに液状化の心配をよく聞かれるのですけれども、そこを踏まえてどういう工事内容なのか説明ほしいと求めました。","respondent":"立川経理課長","answer":"この東品川一丁目付近ということで、今回その２でございまして、その１につきましては、昨年度実施したところです。この東品川一丁目付近ですが、今後の予定ですが、その３まで予定されてあります。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"ということは、直接液状化の関係ではこれはちょっと工事の目的が違うと、そういうことか尋ねました。","respondent":"立川経理課長","answer":"直接液状化の対策とか、そういったことについては聞いておりません。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何ていうのですか、その辺をちょっと行政としての感覚というのですか、教えてほしいと求めました。","respondent":"立川経理課長","answer":"辞退の理由というのはさまざまですけれども、ある社はやはり配置する技術者が手配できない。いわゆる一次下請け、二次下請けとの関係で、いわゆる予定価格を上回る積算しかできなかったということで辞退というふうに聞いております。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問","question":"予算が合わないというイメージだったのでお伺いしたのですけど、後は地下に埋まってしまうわけですから、お願いしたいと考えています。","respondent":"立川経理課長","answer":"下水道管の工事につきましては、区内でも実際できる事業者というのが４社か５社しかございません。今回の沼田土建に関しましては、これまでも良好な工事に仕上げてもらっておりますので、その辺の心配はないというふうに考えております。","id":"exchange-018"},{"speaker":"塚本副委員長","kind":"質問","question":"すみません、一つだけお伺いさせてください。耐震工事の概要で、大変大事なことだと思いますけど、具体的には何か新しい工法みたいなものをされるのかどうかだけ教えてほしいと求めました。","respondent":"立川経理課長","answer":"実際隣接する部分で台場小学校がございまして、そういった意味で、幹線と支線との関係で緩衝材とかを入れて補強するというふうに聞いております。そこら辺について通常埋め戻すときに、緩衝材を入れるので耐震性が増すと、そういった工法をとるというふうに聞いております。","id":"exchange-019"}]},{"id":"topic-05","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"確認というか、詳しくやったものが品川区史だと思っていますので、既にある程度のものがその中に詰まっているのではないかという思いが非常にします。ぜひそういったリンクができるような形をぜひとっていただきたいと思うのですが、その件について、どう思うか。","respondent":"荒井広報広聴課長","answer":"私どもは今おっしゃったことは重要だというふうに考えております。改めて取り組もうとした考え方の一つに、統一的にといいますか、そういった方向性で進めさせていただきたいというふうに考えているところです。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もう１点、そういうのも含めて各課の連携をとってほしいと求めましたので、よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"この１年間のスケジュールでいろいろつくっていこうというスケジュールはありますけども、そこを伺いたいと思います。おそらく電通に委託しているのかと思いますけども、何を委託しているのか、そこを伺いたいと思います。","respondent":"荒井広報広聴課長","answer":"その段階ごとにそれぞれの、そのときどきの狙い、目的を設定して一つずつ進めていきたいというふうに考えているところです。そのほかのインタビューであるとか、政策課題研修へのフォローであるとか、ここに書かれてある取り組みのそれぞれの案を出してもらっていくです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"確認","question":"なぜかというと、観光客誘致というのは別に目的とか目標ではないということでよかったのか、そこは改めて伺いたいと思います。魅力アンケート調査の中で、どこの結果でそういうことになったのか、そこをご説明いただけますか尋ねました。","respondent":"荒井広報広聴課長","answer":"魅力調査の中で、品川区に訪れてもらうことが一つ大事だろうというふうに考えているところが、観光客誘致という言葉につながっているところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"切りかえというのでしょうかね、そういうことなのか、どういう意味なのか伺いたいと思います。これら一つ一つがよく区の狙っているもの、目標としているものがどうも見えてこないのですけど、いかがか尋ねました。","respondent":"荒井広報広聴課長","answer":"さまざまなご意見をいただいたところです。観光をどのように位置づけていくか、それぞれについてどのように位置づけていくかということの検討を進めさせていただきたいと思います。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったら、そこが目的なのでしょうかと思ったので、この辺を改めて伺いたいと思います。取り組むべきポイントというのがよくわからないのですけど、なぜ今根付かせなければならないのか尋ねました。","respondent":"桑村企画部長","answer":"そういったことを考えながら戦略プランをつくらせていただきたい、その上で、つくっていきたいというものです。所管事務調査ですので、どうぞご意見を言っていただいて、そういう意味での議論をさせていただければというふうに思っているところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"マンションが増えて、そういう要するに地域間競争という意味では、ちょっと違うのではないのかというふうに思いますけど。一つだけ伺いたいのは、地域間競争とはどういうことなのか、そこだけ最後に伺ってもよろしいか尋ねました。","respondent":"桑村企画部長","answer":"私どもは人口を確保できませんし、また逆にそれの相乗効果があって、一定の品川区の施策というのはよくなってくるのだろうと思います。外にＰＲするということだけでなくて、これをきっかけにまた区の施策を考えていくということですので、そうご理解いただければと思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"区が教育に力を入れているのはよく伺いますけど、区民からすれば大事にしたいということではないかと私は思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"区外の回答者、どういう形でこの調査をされたのかと、ちょっとイメージがわかないのでどういう方法をとられたのかをお聞きします。この二つをお願いします。","respondent":"荒井広報広聴課長","answer":"３０代後半の子育て世代を中心に人口が増加したというふうに伺っているところです。２点目の区外在住者へのインターネット調査の件ですが、調査会社が抱えているインターネット・アンケートのシステムを使ってやらせていただきました。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"課題があったら、それも本日でなくていいのですけど、一応お知らせしていただきたいと思っています。インターネット会社に登録をしている方の中から１,０００名抽出して、こういうアンケートをとられたという認識でよろしいのか尋ねました。","respondent":"荒井広報広聴課長","answer":"それから１都３県、この三つのグループの中から１,０００人の方を抽出させていただいてやりとりをした、アンケートをさせていただいたというふうに聞いているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"既に住んでいるわけですから、あとは来訪者という形で品川区に入ってきてほしい、その辺をちょっとどういうふうに捉えているのかということ。ずれというのがあると思いますけど、それはどういうふうに調整していくのかというところがありますが、お考えをお聞きしたいのですが。","respondent":"荒井広報広聴課長","answer":"区外用のアンケートというふうにばらばらに実施しているものですが、それぞれにアンケートというか、項目を設定してやったものがあります。疑問といいますか、そういったことともあわせて精査をして、調査の結果を分析していきたいというふうに考えているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"これはどなたが講師という形でされたのでしょうか、これはキックオフですから、このスケジュールはわかりました。この取り組みのスケジュールはわかっているのですけれども、この辺の調整というのは、今後どういうふうに考えているのか尋ねました。","respondent":"荒井広報広聴課長","answer":"こちらは事業委託をしております電通と、それから今年度の取り組みについては、私のほうから説明させていただいたところです。それから、２点目のさまざまなことの調整についてですが、ご意見をいただく場を設けていこうというふうに考えているところです。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"電通の方にお願いした経緯は何かあるのでしょうか。このシティプロモーションの取り組みで企業とか講座の担当とかいろいろあると思いますけど、電通に関して何か理由があるのか、最後にお聞きします。","respondent":"荒井広報広聴課長","answer":"今年度シティプロモーションを実施する上で、ある部分、一定の先ほどご説明させていただいたものについて委託をすることに決まりました。委託するに当たりまして、プロポーザルを行いまして、電通に決めたです。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に人口減少が続いて、将来消滅する可能性があるのではないかというような新聞報道まで出る状況ですから、必死なところがあると思います。２３区の中の品川区は、その辺の他の自治体のシティプロモーションの取り組みについては、成果はきちんとやはり分析してほしいところだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"目に見える成果ばかりをどうしても求めたくなるけれども、きっかけづくりにしてほしくて、そういう成果に気をとられる必要はないと思っています。それはなぜかというと、いや、そんなに忙しくなくて暇だと言う人も多いわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"塚本副委員長","kind":"質問","question":"長期的に２０２０年みたいな考え方、長期的視点としては２０２０年を一つのゴールとして、要するに考えているというふうに思っていいのか尋ねました。","respondent":"荒井広報広聴課長","answer":"長期的な視点として、ゴールを定めているものではございません。２０２０年が長期的なことではないです。","id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問","question":"その発想の転換というのですかね、区の行政というものを持っていくということが大事になってくるのだろうというふうに私も思っております。最終的なということですから、人の流れが非常にありますけれども、その点はどのようにお考えか尋ねました。","respondent":"荒井広報広聴課長","answer":"先ほど部長の話にもありましたように、２０２０年の東京オリンピック開催というのが一つの、ましてプロモーションに取り組むきっかけになってありますので、そういったところも視野に入れながら進めていきたいというふうに考えているところです。","id":"exchange-036"},{"speaker":"塚本副委員長","kind":"意見","question":"ぜひその辺はよろしくお願いしたいと思います。やはりシティプロモーションの一つの目標として掲げてほしいというか、目指すべき視点、その点をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"このキックオフ講座の資料を見ていると、そこの兼ね合いというのはどういうふうにしていくのか、どういうふうに考えればいいのでしょうか。首長の指示に合わせた形というか、合わせてやっていくのがお仕事だと思いますが、その関係はどうなっていくのか尋ねました。","respondent":"桑村企画部長","answer":"考え方、そういう意味では、私どもは常にやりとりしているわけです。今ここで区長がこういうことを考えていて、これに向かって進むというのは、もう少し積み重ねながら少しつくらせていただきたいというふうに思います。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問","question":"よく今特別区というか、東京都でもいろいろ議論されているけれども、５００ｍメッシュの話というのがあるではないですか。あの地域というふうにすれば、そこには定住人口みたいになってくるわけではないですか、どんどん。","respondent":"渡部委員長","answer":"着実に今流山市のご説明もいただきましたけど、東京圏の通勤を考えて、明確にポジションを持ってやっていると思います。以上により、予定表の２、所管事務調査を終了いたします。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":35715,"voices":102}},{"id":"h26-20140723-14","meetingId":"h26-cm07","date":"2014年7月23日","dateIso":"2014-07-23","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時０８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"１点だけなのですけれども、それぞれの保管金額というのですか、基金額がそれぞれどんな程度に配分するという考え方があるのですか。そういうところがあるのかと素人考えで思うのですけれども、大体どんなふうにこれだけの額がこういうふうに分かれるのかというのを説明を求めました。","respondent":"本城企画財政課長","answer":"例えば先ほどご説明いたしました公共施設整備基金でありますとか、それぞれ施設整備基金でありましたら大体どのぐらいの取り崩しを予定するかによって、そんな資金で考えています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"建設期間そのものも単年度ではないわけですからわかるのですけれども、お休み処の用地取得というのが、平成１９年度にありますよね。そうではないというので、そういう振り分けみたいなところはどういう基本的な考え方があるのかというのをちょっと知りたいと思いました。","respondent":"本城企画財政課長","answer":"当初もいろいろな高齢者のかなり大規模な施設の整備とか、いってみれば応急的なものに比重を持って、財源を充てていくというのが基本です。福祉施設とは全く観点が違いますが、多くの方に使っていただくという意味では公共施設ということで、そちらの財源に充てているです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"４１３万７,０００円とか、１００万円とか、可能なのではないかと思ったのですね。こういうふうにここで使ったほうが効果的とか、利益というのかしら、それはあれば何なのかというのをちょっと教えていただきたいと思うのです。","respondent":"本城企画財政課長","answer":"事業それ自体に即して考えれば、税収がどれぐらい全体として見込まれるとか、そのように考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"そういうふうなご説明はそれはそれでわかったのだけれど、では、そんなふうに理解してしまっていいのかと。そういうことでいいのですねとの意見を述べました。","respondent":"本城企画財政課長","answer":"一般的な説明として、前段でご説明いたしましたが、平成１９年度がことさら厳しくてというような意味ではありませんが。一番初めにご説明しましたように、公共施設整備基金の枠内でまちなみの関係とか、そういう事業のほうを充て込んでいるです。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"２３区のを見てきて、いろいろなことの違いがここで出てくるのだろうと思うので、少し一緒に勉強させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"別に基金に無理やりつぎ込まなくても、自治体としてお金がきちんと残っていれば、それはそれでどう運用しようと、それは勝手なはずですよね。何でそういうふうになるのか、その辺について説明を求めました。","respondent":"桑村企画部長","answer":"５年間を見てみれば減らしてきている、何かこの間ずっとしばらくは財政がよかったみたいなことは少し違うのではないのかというのが私の認識です。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"結局３０億円黒字で、４０億円は一般の人が見て、それは自由に使えるわけだから。それで、その辺について非常に矛盾を感じるのでちょっと今お聞きしたのですが、もう一度わかりやすいように教えていただけますか。","respondent":"桑村企画部長","answer":"委員のご説明では、２５年度決算はこれからですけれども、リーマンショック以降はかなり厳しかったというのが事実であります。その意味では、５年間５０億円、いわゆる企業会計でない公会計でやっている者については必要な制度ではないかというふうに考えているところです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"２００億円繰越金が残っています、どうしても一般の区民にとって、それだけちょっとお話しさせておいてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"幾つか確認したいのですけれど、何年か前に神戸市にお伺いして、震災直後の神戸市の財政状況についてお話を聞いたことがありました。どこからか取り崩しをして、どういうふうに財源手当てをしていくのかという、緊急時の計画はあるのでしょうかということをまずお伺いしたいのです。","respondent":"本城企画財政課長","answer":"今の基金制度のほうの関係で申し上げますれば、現行の基金の体系の中では、財政調整基金がそれを手当てする基金であると理解しております。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"それが品川区の裁量で使えるという判断でいいのでしょうかということが１点と、要は、スムーズに資金調達ができたという話も聞いてきたのです。だから、東京の何ていうのでしょうか、東京都の財政当局に対して品川区がどういう対処をしていくのでしょうかということをあわせて説明を求めました。","respondent":"桑村企画部長","answer":"私も神戸市のこと、見せていただきました。本格的な災害復旧みたいなものにこの基金を使っていては、正直言って、多分品川区の財政としては難しいだろうというふうに思っているところです。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"これ、今伺うと既にそのようになっていて、いつからなったのですか。何か手続が、ある意味、縛りというものがあるのかどうかということを説明を求めました。","respondent":"久保田会計管理者、本城企画財政課長","answer":"１,０００万円でもちょっと危ないのではないかというので、１行当たり１,０００万円、全部にそれぞれ分散して預けているというふうにしているものです。条例廃止という形で議会全体の意思も踏まえて廃止すれば、それ以降はそれに縛られず活用できるという制度の中で、対応は可能であります。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"そのうちの１つが、高額療養費ならびに出産一時金の、これは多分つなぎ資金的な扱いだと思うのですね。基金という形がベストかどうかわかりませんけれども、順々に回っているとか、何かその辺の情報があれば説明を求めました。","respondent":"本城企画財政課長","answer":"品川区も、基金としては設けてありませんが、事業としては同様のものをやっているものです。そのような中での対応で、ご利用者の方の利便の面からいえば、基金活用以外の形で対応しているというお答えです。","id":"exchange-012"},{"speaker":"あべ委員","kind":"提案","question":"考え方の一つなので、この提案をさせていただきました。それだからもうこれ以上言いませんけれども、今後の問題として、基金の性格にぴったり合ったような使い方を心がけてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"だから、例えばこのうちのこのような基金を持っていたほうがいいのではないかというような目標といったらいいのか、計画といったらいいですかね。それに対して、必要な基金をどういうふうに積み立てていくかという計画のようなものがありますか尋ねました。","respondent":"本城企画財政課長、柏原行財政改革担当課長","answer":"では、そういうものに一方でお金の面で備えていくための基金の一番基盤となるものが公共施設の整備の基金だという形で理解しているものです。ちょっと抽象的で申しわけございません。 この５年間でどういったところの施設が老朽化してくるだろうというのをある程度見越した中で長期計画を立てていくか、あと、実施計画ですね。総合実施計画の中での、ある程度計画を立ててやっていく、そういった内容のものです。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"それに対して、今から資金を充て込んでいくといったらいいのか、基金を積み立てていくといったらいいのですかね。財政の観点、もう少しお答えいただければと思うのですが、いかがか尋ねました。","respondent":"桑村企画部長","answer":"実施計画等をローリングする中で、５年なり３年なりのサイクルでどのぐらいを使って、ちょっと今のところないのではないのかというふうに思います。１０月ぐらいに、公共施設の有効活用プランのご説明を申し上げますが、そういうのはご議論させていただければと思っています。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"公共施設の有効活用プランについては１０月ということで。この適正性とか的確性のご説明をいただきたいのと、この辺のそもそものルールというのはどういうふうになっているのか、お聞かせいただきたい。","respondent":"久保田会計管理者","answer":"基金の運用につきましては、一番基本に置いているのは、安全かつ有利な運用です。確実性のある、やはり少なくとも収益のある、そういう債券を購入するということを基本にやっているということで確実性を担保しているという考えです。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"そういうのがわからないと、結果だけ見て、「ああ、そうですか」という委員会とかはないと思うので、何でこういうふうに運用状況がなっているのか。基金額と種別、基金額の欄があって、種別の欄があって、この関係性の、どういうルールになっているのか、お聞きしたいと思います。","respondent":"本城企画財政課長","answer":"ほとんど基本的なところでご説明いたしましたが、そのような自治法に則した基本方針の中で、ちょっとブレークダウンした方針を定め。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"その運用方針というのは、例えばここで、委員会で提出されてご説明いただけるもの、そういう類いのものなのか尋ねました。","respondent":"本城企画財政課長","answer":"一番初めにご説明したところもあったかもしれませんが、そういう判断の結果がここで本日お示ししたような決算の状況になっているというものです。ちょっと一般論的ですが。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"当然こういう専門的な知識、外部の方に、専門家というのですかね。ここら辺についてのいわゆる見直しという、外部機関も活用しながら、そういう考え方というというのは今後あるのか尋ねました。","respondent":"久保田会計管理者","answer":"今までの例ですと、これまでつき合いのあった、満期を迎えた今まで扱っていた証券会社から引き続き買うという形で対応しております。それから、一定程度のそういうわかりやすいルールもありますので、今のところそういう形で対応しているです。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"廃止のというような質問があったのですが、既にそういう基金を２３区で持っておられるという、どういうシステムでつくられていくものなのでしょうか。教えていただきたい。","respondent":"桑村企画部長","answer":"議会側がどういう考え方を今後の施策のところで展開するべきだという主張の中でできてくるものなのだろうと思います。そういう意味では、一定上がるというときには、またそういう違う発想が必要なのだろうと思います。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"基金をつくって裏づけというのもどうなのかという気がしておりますが、それは皆様のご議論の中で、それは創設の余地はあるかと考えています。意見ですとの意見を述べました。","respondent":"中塚委員長","answer":"９月の上旬に予定しております常任委員会の行政視察実施の関係上、８月２６日および９月１７日の両日の委員会に向けてご意見を伺いたいと思います。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"一定程度区がつかんでいるのがあれば出していただきたいということと、視察などと書いてあるので、視察もする予定ですか。視察をするのであれば委員会運営、ちょっと時間配分を含めて考慮していただければということを言いたかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"ちなみに、基金でもし視察に行けたらどことかというお考えはあったのですか。基金で視察というのは、どんなものなのだろう。","respondent":"中塚委員長","answer":"それぞれいろいろ取り組んでいる中で、なかなか決めかねるところが悩みだ、これが正直なところです。理事者との調整の中で、どこが悪いというわけでなく、意見交換を中心にできたら非常にいいと思っていたということです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと質問とずれてしまったので。どこか具体的にイメージしたところがあるのですかと聞いただけなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問","question":"かなりおもしろいものがいっぱいあるのですけれども、委員長がおっしゃったように、どこにしようかと。行ったところで条例の説明で終わってしまうというところで、それよりは意見交換によって議論を深めたほうがいいという結論に達したものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"若林委員","kind":"提案","question":"千代田区の何とか基金を取り出して、一回詳細なご説明だけというのは、これはどうなのでしょうかね。そういう提案の仕方もあるのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"一致できるものがあれば提言していくみたいに、そんなふうになればいいのかと思ったりしているので、とにかく基金に関する議論を一定程度の時間を盛り込んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"若林委員","kind":"意見","question":"私もさせていただきましたけれども、今後の新しい基金のあり方も含めた、そういう議論をしなければいけないというふうに思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":39909,"voices":80}},{"id":"h26-20140724-18","meetingId":"h26-cm07","date":"2014年7月24日","dateIso":"2014-07-24","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後２時１５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"しっかりと都のほうで確認をしていただきたいということで、やはりここは強くお願いをしていきたいところと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"提案","question":"その辺正副の中で、あくまでもオリンピックの競技場としてどう考えていくかという前提に立って提案をつくっていってもらいたいなという感じがします。その辺の気持ちは同じなのですけれども、ちょっと違う雰囲気が感じられるのでとの意見を述べました。","respondent":"渡辺委員長","answer":"そうですね、物事の順番としたらこれからの施設のあり方というのはご指摘のとおりだと思いますので、委員の皆さんもそういう共通認識でお願いします。ほかにいかがでしょうか。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところの方の安全を守るという点では、そこら辺のところも私たちとしては求めていくことも必要なのかなというふうに思っているところです。でも、ちょっと知りたいなというふうな思いがしているところなのですが、そういう状況はあるというのをこの読売新聞で見たところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えばこれを都のほうに要望するなり、どこに要望するにしても、品川でやるなよという委員会ではないでしょう。３年前のときにも影響がなかった点を考えれば、そこにこだわっていたら、では全部品川から出ていってくださいという委員会か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それはオリンピック全体を考えたときには、それが全体としていい方向であれば、そういうこともあり得るかなというふうな思いはしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この委員会でなくて、委員会の場所が違うのではないかな、発想が。今の鈴木ひろ子委員の発言は品川区議会の議員の立場で言う、この委員会の中ではちょっと違うような感じがするのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"つる委員","kind":"意見","question":"当然液状化や津波というところでは３年前の部分においても、それはそれでコンパクトにやるよという視点からすれば、こういうふうには思っております。追加分、提出分も含めて、それ以外のところについてはちょっと改めてまた意見を述べさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"渡辺委員長","kind":"質問","question":"どうぞ忌憚のない見解、現時点でので構いませんので、言っていただいて、まとめに活かしていきたいと思います。私のほうから１点質問よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問","question":"オリンピックが来る前から品川区であるわけですから、そういうものも含めた中の構想というのは必要じゃないかと思ってこれをつくりました。やはり推進委員会ですから、ではその後こうするべきだろう、最初から提出されてあるこの部分に関してはそういう思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"バリアフリーの問題ですとか、委員会としてそれを議論できるような、そういうふうな場というのはどういうふうな形で持てるのかな。そしてまた、それを求めていくということとあわせて確認をしたいという思いがするのですけれども、そこら辺のところについてはどうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ここのところはとても大事なところだと思いますので、東京都のほうにも、区を通じてということになると思うのですけれども、そこら辺のところも確認をとっていただいて、この委員会でも明らかにしていただけるように、ぜひ委員会としても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"それからあと、やや事実関係的にはどうなのかなという疑問を私自身は持っておりますので、ちょっと意見として述べさせてほしいと求めました。これはちょっと確認なのですが、上から５番目ですか、意見として述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"すみません。今の海底の道の話、品川区というか、八潮方面からつながる、今の工事中のスケジュールなり、状況なりをちょっとお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちょっと１点お伺いしたいのですけれども、３点あるのですけれども、それとも公園全体を通年使えるというのですか。このまま要望を出してしまうと、こういうのはまた整理してうまく咀嚼していくような感じなのですかね。","respondent":"渡辺委員長","answer":"２ブロックあるという中で、挙げるだけ、要望ですから要望すると。２段階ということでもないので、皆さんで諮ることになるかと思いますので、ご理解ください。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問","question":"何か以前ＪＲの貨客併用などとあって、要するにＪＲ東海道線というのですか、貨物線のところを走ってそのままお台場のほうに抜けるという……。後でまたやると思いますので、後ほど質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問","question":"それは別にしてちょっと１点お伺いしたいのが、むしろここの輸送に関する検討会１つの中で、どういう方が出ているのかというのをまず１点説明を求めました。","respondent":"中村都市計画課長","answer":"今後具体的な話になったときに必要に応じて各担当に振り分けられるのかなと思いますけれども、それで一義的な、現在の窓口は都市計画課です。交通機関だとか、道路だとかの整備ですね、そういったときにはそれぞれに応じた担当部署に分かれるという形になるかと思います。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何というのですか、１点申し上げたいのが、必ず車両の絶対数というのが増えてくると思うのですよね。それは意見というか、もしそういうのがあれば発言をしていただきたいなと考えています。","respondent":"中村都市計画課長","answer":"この検討会の中でも、東京都としての認識では、やはり専用レーンを設置することによって。委員ご指摘のようにこれからこの検討会、今年度中ですか、また発言の機会がございましたら東京都のほうには申し入れていく所存です。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"１点、その検討会で先ほどいながわ委員の質問の中で、呼ばれていないのか。その関係区市とありますけれども、その他の区市町村等で参加されているところがあるのかどうなのか、その辺をちょっと説明を求めました。","respondent":"中村都市計画課長","answer":"この検討会のほうは、品川区は関係区市ということで参加をしています。都市計画課が対応していますけれども、区としてどこが適切な対応の部署かというのも全くわからない状況ですので、また今後具体的な話が進んだ中では。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えばりんかい線の車庫のところにホームの１つでもつくってくれて、つくろうと思ったらあるところですから、あるのかもしれないですけれども。品川区もせっかくですから、新しい羽田空港からの電車がどうこうと言ったって、もう到底今から動いたって２０２０年なんか間に合わない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"品川区の魅力を最大限に引き出す海上交通というのですかね、今のところこの検討会ではそれを考えていないのか。お答えできる範囲で構いませんので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"多少ずれた質問になってしまうかもしれないですけれども、１つの輸送手段でありますので、ぜひ前向きに発言をしてほしいと求めました。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"「大会関係者」の輸送検討会と、この「観客・会場スタッフ」の輸送検討会と２つ出ておりますけれども、やはり気になるのが道路ですね。ルートが外れるところは出たり出なかったりとか、そういうようなことになっているのか、今の段階でもしわかれば教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"この専用レーンですとか、あるいは観客の経路ですとか、今２３区がその検討会のほうに出るのかなというふうに考えてあります。身体障害者の方の対応のための車両が一部一般道を通ることはあるかと思われます。","id":"exchange-022"},{"speaker":"浅野委員","kind":"提案","question":"２３区含めて全部入るという、このようなお話をいただきました。そういう意味では、また委員会の中でいい案があればこちらからも提案をするという形をとれればと思いますけれども、この点いかがか尋ねました。","respondent":"中村都市計画課長","answer":"この検討会、今後もまた開催されるものにつきましては、参加の機会が得られれば、区としての要望を積極的に発言をしてまいりたいと思います。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"提案","question":"これが一番具体的かなと思うのですけれども、大井町からのピストン輸送を区が提案していくような形も考えておいてもらいたいなと思います。６年間、その辺も検討しながら区として進めてもらいたいなというのが要望にありますが、その辺お考えをちょっと教えてもらえればとの意見を述べました。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック推進担当課長","answer":"ただこれがまた品川区のにぎわいというところから考えた場合には相反するものがあるというふうには感じられます。こういったものをシミュレーションしてみて、いろいろな機会を捉えて… 大会期間中に、いわゆるいろいろなイベントの規制がかかっておりますので、その辺をよくよく研究させていただきたいと思います。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それから交通機関のほうですが、モノレール、たしかあそこのホッケー場、３万人ぐらいでしたよね、客席。〔「１万人」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１万人。アピールしていってもらいたいということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"検討会の中でこういった要望、検討会の中身というのですか、進行しているのか。その辺はちょっと基礎的なことなのですけれども、すごくざっくりでいいのですが、ちょっと説明を求めました。","respondent":"中村都市計画課長","answer":"検討会の中から出るものもありで、例えば大会関係者のほうの検討会では５つの項目というのがありまして、出された意見として次の検討会に引き継ぐべき項目として同時に掲げられて。","id":"exchange-027"},{"speaker":"つる委員","kind":"提案","question":"そうしたことにつながるようなソフト面の遺構というのでしょうかね、こうしたものが残っていくような輸送体制の整備の提案という、未来的な。ソフト面の遺構づくりというのでしょうか、そういう視点、ぜひ盛り込んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれを契機に大きく進むというところでの取り組みにしていただきたいなという思いがとても強くあるのですけれども、その点ではいかがでしょうか。それもあわせて、実際の障害の方々のご意見もお聞きいただきながら、一緒に進めていただきたいと思うのですけれども、いかがでしょう。","respondent":"中村都市計画課長","answer":"このオリンピックの中だけにまず１つ特化しますと、また品川区としては気づいた点についてはいろいろと意見を伝えていくという形になるかと思います。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひホームドアとか、そういうところもあわせてぜひ強力に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/882053?Template=document&Id=6458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":25066,"voices":70}},{"id":"h26-20140730-8","meetingId":"h26-cm07","date":"2014年7月30日","dateIso":"2014-07-30","committee":"建設委員会","time":"午前１１時００分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 初めに、(1)の「大崎駅周辺地域におけるエリアマネジメントの展開","agenda":"」を聴取いたします。 初めに、(1)の「大崎駅周辺地域におけるエリアマネジメントの展開","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"主に３点お伺いしたいのですが、これがどう位置づけられているのか、これについて教えていただきたいのが１点です。７月２４日に正式なものになったとの説明をいただいたのですけれども、かかわってきたのはどういった方なのか、教えてほしいと思います。","respondent":"溝口都市開発課長","answer":"戦略５になっておりますので、それに基づいた取り組みを、継続してこれまで続けてきたという形になります。検討してきて、今回、まとめたものになっているものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"１点目なのですけれども、戦略５というところがよくわからないですが、どこを見たら、こういった中身がわかるのですか。そういうものも地域的に連携をしていくという方向性を持っているのか、どうか、わかっている範囲で説明を求めました。","respondent":"溝口都市開発課長","answer":"ただ、この前、建設委員会でも報告しました五反田駅周辺についても、今後、いろいろまちづくりを考えていかなければいけない。そういったものも、当地域の中に関連づけながら、まちづくりをしていきたいと考えているものです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"１点目なのですが、区のホームページをしっかりと見ますとの意見を述べました。","respondent":"溝口都市開発課長","answer":"平成１６年１１月に都市再生ビジョンというのを定めて、これまでまちづくりを進めてきているものです。当課にも、少し余分を用意しておりますので、そういったところで対応していただければと考えております。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"何かその辺のところで、お考えというか、方針というものがあるのかどうか。五反田と大崎、この辺のことについて、お考えを教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"一つの方針として、前回、大街区化という形のプランを出しています。それぞれの拠点が有機的に連携することによって、連携していくことによって、そういった視点に立ったまちづくりを進めていきたいと考えております。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"民間デベロッパーに伺うと、前よりは大分早くなりそうだというようなお話も聞いたことがあるものですから、それぞれの特性を生かしたまちづくり。歴史を重んじながらも、新しい展開をしていっているところがありますので、その辺についての思いも聞かせていただけたらと思います。","respondent":"溝口都市開発課長","answer":"まず平成２５年２月に策定しました、軸という形で、それぞれの拠点が連携してまちづくりを進めていくという大きな方針を出しております。は活力あるまちづくりを進めていくのか、そういったことを考えながら、まちづくりを進めていきたいと考えているものです。","id":"exchange-005"},{"speaker":"原委員","kind":"質問・要望","question":"今は１５％ではなくて、２割高くらいに建築コストが上がってきていると、私は推測するのです。ちゃんと考えていただきたいということがあるものですから、建築の全体的なコストの問題と、それから権利変換のことをご説明ほしいと求めました。","respondent":"溝口都市開発課長","answer":"ただ、当然、今後、予測が難しいところもありますが、建設コストが高くなったからといって、事業がとまるとは考えておりません。今後も、まちづくりを進めていきたいと考えておりますので、事業がとまらないような形での支援は引き続き行っていきたいと考えております。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"要は一体的に再統合したのであれば、２法人を１法人にするのが当然の流れだと、私は考えるのですけれども、そこはどういうふうに考えているのか。それぞれの地域事情とかがあると思うのですけれども、そこのところを説明を求めました。","respondent":"溝口都市開発課長","answer":"大きな意味でいきますと、名称としては、それぞれ違う形で定めて社団法人を立ち上げたという経緯になっております。統合すべく、今現在、両者で調整しています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"まち運営プランという、将来に向かって継続という意味では、面的にも、時間的にも広くやっていくということなのですけれども、他区で、こういった例がどの程度あるのか、わかっていたら説明を求めました。","respondent":"溝口都市開発課長","answer":"他区でこのような事例というのは、エリアマネージメントは汐留等で展開しているとは聞きますが、ここまで進んでいるのは、多分、２３区の中でも大崎が一番進んでいると自負しております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"区のこの組織とのかかわりというのは、どんな感じでかかわっているのかも、説明を求めました。","respondent":"溝口都市開発課長","answer":"区のかかわりということですが、まち運営プランの１１ページをご覧いただきたいと思います。あくまでも支援、または連携して一緒にまちづくりをやっていく、そういったところのかかわりとなっています。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":9135,"voices":31}},{"id":"h26-20140825-6","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"区民委員会","time":"午後１時００分～午後４時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"品川区民芸術祭２０１４の開催","agenda":"品川区民芸術祭２０１４の開催","exchanges":[{"speaker":"井上委員","kind":"質問","question":"１つ、最後の協賛事業のところでお伺いをしたいのですけれども、パンフレットを持っていくと割引というようなお話があったのですが、具体的にはどういうことなのかと、あとそれをどういうふうに区民の方が知ることができるのか、その辺を説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"これは文化振興事業団と連携しまして、区民のほうには配布してございませんが、そこに持っていって提示すると１００円の割引をするです。そのパンフレットを通じて、それからまた「インフォＣｕｒｉａ」という文化振興事業団のものも通じて行っているところです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"同じになりますが、パンフレットというのはどういったところに箱をつくるのか、パンフレットの存在がどこにあるか知らないとそれもできないのですけれども、どういうふうに配布をしたり、提供するような予定でお考えか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それとまた、区民につきましては、今資料にもあります２枚目の団体・サークルの活動の発表、この人たちも総勢で１,０００人ぐらいいらっしゃいます。その人たちを通じて、ＰＲをして周知をしていただくというように考えています。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"第５回目ということで、記念事業みたいな形で行われるのですけれども、ざっくりでいいのですが、来場者数ですね。こちらのほうを教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"今回５回目ということで実施させていただきました。実績ですけれども、約１万人、全ての企画の中で約１万人の方々が毎年毎年参加していただいて、見に来ていただいているです。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"１万人の方が参加をされるということで、非常に大きなイベントになってきていると思います。５回まで１つの区切りとして、それが第１０回とか、また次の区切りに向けて発展させていっていただければと、要望をしておいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"高齢者の消費者被害防止に向けた地域での見守り","agenda":"高齢者の消費者被害防止に向けた地域での見守り","exchanges":[{"speaker":"井上委員","kind":"質問","question":"その辺はどういうすり合わせをして、この民生委員が見て回る対象の方と合っているかどうかというのは、どのように区では押さえていますか尋ねました。","respondent":"米田商業・観光課長","answer":"１つの方法として民生委員の方々に、実際に消費者センターというのは職員が地域に出向いて、中に来ますご相談等に対しての対応ということになります。消費者被害の防止というような観点から速やかに対応しているものですが、その人、その機会ということで捉えてあります。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"７０歳以上の方は相談の件数ということで被害の件数ではないのですけれども、被害者としてはどういう家族構成なのかというのは、そういう把握はあるのか尋ねました。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"やはり年代としては、東京都の資料によりますと７０代の人が、この特殊詐欺の被害に遭っているケースが多いという資料を持っております。したがいまして、そこを重点的に警察署と連携をして、防犯等の広報活動をしているところでありま… なかなか気づかずに進んでしまうケースが多いというようなこともありますので、その辺のところを中心のターゲットとしてこちらも捉え、取り組んでいるところです。","id":"exchange-006"},{"speaker":"井上委員","kind":"意見","question":"１回調査のときには回って、これをお知らせするときに民生委員さんにもどういう、その辺は少し工夫をしていただけたらなと思っています。","respondent":"米田商業・観光課長","answer":"それで、その場合には高齢者福祉課だったり、社会福祉協議会も関係しながら対応していきたいというものが１点あります。消費者センター、あるいは、もしくは関係機関につなげてほしいというようなことについては継続的に取り組んでいく必要があるだろうと。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"被害の件数というのは、振り込め詐欺と悪質商法、それぞれ何件くらいあるのか。多分警察のほうにも被害届という形で出されているのではないかと思いますけれども、その件数をまずちょっと説明を求めました。","respondent":"米田商業・観光課長、上垣外生活安全担当課長","answer":"数字を持っているわけではありませんけれども、その１件１件についての金額というのは、その相談のときに入ってまいります。自分が絶対に引っかからないという認識を持つというのは大きな誤りですよというような講座もやって… これにつきましては、いわゆるオレオレ詐欺といった特殊詐欺につきましては、平成２６年６月末現在で、品川区内で３６件被害を認知しております。被害額につきましては約６,８００万円あまりという状況であります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その３６件というのは、６月末というのはいつから、今年だけということでしょうか。そこのところ。","respondent":"上垣外生活安全担当課長","answer":"これは平成２６年１月１日から６月末までの数字です。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"警察の取り組みというのは、ちょっとここではないのかもしれないのですけれども、わかったら教えていただきたいなというふうなものが１つ。銀行に２００万円をおろしに行ったときに銀行からも言われたけれども、大丈夫ですと言って２００万円をおろしてきて、その点についてお願いします。","respondent":"上垣外生活安全担当課長","answer":"これは１つの例ですけれども、電話がかかってきたらまずこういうことを確認する、お金の要求があったら必ず息子の前の電話にかけ直すと。こういうような取り組みをしているものもあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそういうところで、ビジネスとしてそういうふうにはびこってしまっているという社会のゆがみでもあると思いますので、その辺のところの摘発、それから高齢者側の啓発というところで、さらにこれが被害をなくす方向で、ぜひ取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"木村委員","kind":"意見","question":"３０代、４０代、そして７０代ということですが、この間の５０代、６０代というのは、なぜこのようにしてほかのものよりは低いのか。わかりますかとの意見を述べました。","respondent":"米田商業・観光課長","answer":"あるいはアパート等をめぐるご相談、こういうようなもの、いわゆる相談としての実態が大きいのだろうと思います。６０代というのは、それにしても３００件規模の相談ですので、こちらとしては認識しています。","id":"exchange-012"},{"speaker":"木村委員","kind":"意見","question":"待っているではない、電話かかってきてどうのこうのではなくて、やはりこちら側も何かそれなりの対策をしなければならない。町会単位で若い方々のそれに対するアドバイスを受けるような、何かすぐ相談ができるような、そういう態勢というのはつくれないのかどうかとの意見を述べました。","respondent":"米田商業・観光課長","answer":"ちょっと先ほどの繰り返しにもなってしまいますけれども、ご自身だけで対応しようとせずに、すぐにとにかく相談につなげてほしい。２人で考えるよりも、継続して行ってまいりたいと、このように考えてあります。","id":"exchange-013"},{"speaker":"木村委員","kind":"質問","question":"そういうふうな方々に対して、実際にそういうことが行われているのかどうか、まだ考えている最中なのかどうか。現在進行中なのかどうかということをお伺いします。","respondent":"米田商業・観光課長","answer":"新たな方法がありましたら、こちらのほうも深めてまいりたいと、このように考えてあります。","id":"exchange-014"},{"speaker":"木村委員","kind":"質問・要望","question":"これは要望であります。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば非通知にしておけば電話がつながらないとか、何かその電話に対する取り組みとか、状況というのはどうなのですか。そういうところまで把握されていたら、その辺のところを教えていただきたいのですけれども。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"警察だとか、私どもの関心事ですので、それにつきましては把握した上で情報共有をして逮捕しているというものであります。警察署のほうでは、こういったものを使って被害の防止に努めているという対策もしているところです。 現況のような警察の取り組みについては、消費者部門にも警察等より情報提供、あるいは生活安全のほうより情報提供があり、そちらの情報については共有しています。","id":"exchange-016"},{"speaker":"本多委員","kind":"意見","question":"何か抜本的なその先の防止につながる、さらに防止になるような発想というものがないものかなと思うのですけれども、まずそれをちょっと聞かせてくださいとの意見を述べました。","respondent":"上垣外生活安全担当課長、米田商業・観光課長","answer":"区としても新たな取り組みといたしまして、その家庭の中で、これから実施していきたいと考えています。こういったきめ細かな対応によって、少しでも犯罪被害に遭いそうな方に対する声かけ… 警察のほうで取り組んでおられる、その録音機能をつけた家に電話をすると、「この電話は振り込め詐欺防止のために電話の会話内容が録音されます。","id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"はちょっと確認なのですけれども、閣議決定で開業率・廃業率が、いわゆる米国・英国レベルの１０％台になっていますが、開業率が１０％台といいますのは高いというのがわかるのですけれども、廃業率も同時に上げていくということというのは、これどういう趣旨なのか、まず教えていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした意味では、国のほうでは開廃の資源の半分で計算をした率で適正な率をキープしていく必要があるだろうというようなことで書かれております。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"そこをちゃんと確認しておかないと、この文章だけ見ると感じてしまったので、まず確認をさせていただいたのが１点です。質問する前に、限りなく１００％に近く金融機関からお金が出る、それで区の権威があるわけですから。","respondent":"山崎ものづくり・経営支援課長","answer":"やはりアドバイスを受けるのは自分の創業モデルを考えている人ですから、それで銀行なりと融資の仕組みというのは流れると思います。さらに区の支援員と同じようなことを言われたということでまた戻ってきたりとかというようなことが、通常の融資よりはそういう意味では率が。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"役所はサービス業ですから、これでは通らないよとか、こういう計画だったらというのをもっともっとちゃんと私は言ってあげるべきだと思うのですよ。そして、通らなかったけれども起業したい、創業したいと思っている方をどうフォローしていくか、その辺についてはいかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"反面、率も高めていくためには、そういうものが数字として出ているなという認識はしています。委員が言われたようなことを含めて、やはり検討してここのところは強化してまいりたいなというふうに、所管としては思うところです。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"せっかく相談員というプロがいるわけですから、ここでは通らないよ、これでは通らないよと。せっかくプロの方が、相談員がいらっしゃるわけだから、そこの創業でもみ込んでいくのをどういうふうにするかというような質問なので。","respondent":"山崎ものづくり・経営支援課長","answer":"創業、さまざまな創業というキーワードで資源を連携させて、よりよい創業につなげていくための支援をしっかりやっていく必要があるなと。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど１２５件相談があって６９件実行だということだったのですが、１年間でどれぐらいの件数があって、そういうのがちょっとわかったら教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした比率から考えると、東京都下の数字４.６％ないしのこの数字と、ちょっと所管課とすれば分析をしています。先ほどの創業支援資金の相談に来られたり、あるいは医療業で、あるいは各種サービス業というようなところが多いかなというふうに思ってあります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８年間いられるという状況になるのかなと思うのですけれども、それぞれありますが、更新して皆様入っているという状況になっているのでしょうか。あくのを待機をされているという、そういう状況があるのか、ここもちょっと利用の状況というのも教えていただきたいです。","respondent":"山崎ものづくり・経営支援課長","answer":"この施設に行って目的に照らした成果の部分というところについてご説明をして、民間の事務所なりを借りて転出される方、それぞれです。詳しくは現地で、今日資料とマネージャーの、そういった部分のお話を用意しておりますので、よろしくお願いしたいなと思います。","id":"exchange-023"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"井上委員","kind":"質問","question":"京都のところで、京都府中小企業応援条例というのが平成１９年につくられているということなのですけれども、品川区で、要綱とか何かでこれと同じようなものというのはあるのか尋ねました。","respondent":"中川原地域振興事業部長","answer":"品川区というところは、条例とか、あまりそういう規定というのはつくらないで、実際的に施策としてやってきたところがあります。うちの特色としてはあまりそういうものをつくってやるということはやってこなかった経緯があります。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36975,"voices":87}},{"id":"h26-20140825-7","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"厚生委員会","time":"午後１時００分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"の平成２６年度高齢者福祉週間行事","agenda":"の平成２６年度高齢者福祉週間行事","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"１００歳だったり、１０１歳だったりというのは、ご家族も一緒におられることだと思うのです。要介護認定を受けた方のご家族、そういった方々から何か声といいますか、こういったものを受け取る際の思いみたいなものは出てくるのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"私からは、お祝い事業の訪問の際に、ご家族の方からの声というご質問をいただきましたので、そちらのほうにお答えします。やはりちょうど節目のお祝いのときに、品川区からこのような商品券をいただきということで、大変感謝と喜びの声を聞いているところです。","id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういった在宅介護者のところなどでは、ここの事業ではないのですけれども、介護する方の交流会みたいなものもやられていると思うのですけれども、ここですね、交流会と書いてありますね、こういう集いの中では、苦労をいろいろ分かち合ったりとか、そういう場になっているということですかね。","respondent":"永尾高齢者福祉課長","answer":"何年も介護されていて、とてもすばらしい介護をしている方に対して、２名程度に体験の発表をしていただいております。在宅介護支援センターのケアマネジャーだとか区の職員なども一緒に入りながら、またご相談なども、非常に好評を得ている内容になっております。","id":"exchange-002"}]},{"id":"topic-02","title":"のサービス付き高齢者住宅ｃａｒｎａ（カルナ）五反田入居者の新規募集","agenda":"のサービス付き高齢者住宅ｃａｒｎａ（カルナ）五反田入居者の新規募集","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"４万円限度の助成は、そういうのが入っているのかどうか、その辺のところを教えていただきたい。そういう必要になったときには、優先的に入れるというようなものがあるのかどうか、その辺を説明を求めました。","respondent":"白鳥高齢者いきがい課長、大串福祉計画課長","answer":"平均の要介護度が２.７か２.８というふうに伺っておりますけれども、要介護者かどうかというところで、その辺の違いが出ているものです。それ以外の併設施設の認知症高齢者グループホーム、小規模多機能型居宅介護につきましては… ４点目の、サービス付き高齢者住宅から併設の施設への入居に関して、私のほうからお答えします。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"併設されているサービスを利用しようと思えば、利用できると、こういうことでいいですか。その確認を２点、すみません、お願いします。","respondent":"白鳥高齢者いきがい課長、大串福祉計画課長","answer":"もちろんこれは、平成２４年６月１日開設ということから、もう２年経過していますが、既にここで要介護認定を受けられた方もいらっしゃいます。そういった区別といいますか、要介護… ２点目のご質問について、私のほうからお答えします。当然、入居者の身体の状況に応じて、併設されているこういった施設についてのご利用も可能という形で対応していきたいと考えています。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"あるのであれば、なぜあえてここに出していないのかと、ちょっと疑問に思ったのですけれども、そのことはどうなのでしょうかということが１点。この金額がどういう算出でされたのかということについて、品川区はどうお考えなのでしょうか、お伺いしたいのです。","respondent":"白鳥高齢者いきがい課長","answer":"２点ご質問があったかと思います。これらのことも当然ながら調査をした結果、このサービス料を含めた中で、このような金額が妥当ではないかということで落ち着いたところです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"おそらく青葉会の考え方がお有りなのでしょうから、やっぱりそういうことについては、入居者の方々に対して説明する必要があると思うのです。税金を投入した金額と、この家賃設定が果たして正しいかどうかというモデルくらいはつくっていくべきと思うのですが、いかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"その後の入居説明会のときに、あるいは説明会の導入部分の中で、入居説明会の中でそれぞれにお伝えをしていただきたいということで。これらを、入居者説明会にお越しいただいた方々に、わかるような形でご説明をしていきたいと考えています。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"すみません、１点だけ質問させてください。なかなか連体保証人がいなくて、金銭的にお金を使って連体保証人になるなどというのもあるのですが、ここはどういう考え方か尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"やはり緊急時の対応の中でも、いわゆるそこの施設の中で対応できないような事態が出てきた場合に、こういうようなものを設けさせていただいたといった考え方です。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、そういう引受人、または保証人のいない人は、ここには当てはまらないと取ってよろしいか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"リーフレットの２．入居申込み資格についての４．になりますが、後見人が必要になりますということで謳わせていただいておりますので、こちらのほうで対応できたらと考えています。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ちょっと幾つか伺いたいのですが、区からどのくらいの割合で入っているのか、わかれば教えていただきたい。大井林町のほうは、厚生年金を受けている方が対象と伺ったと思うのですけれども、ちょっと疑問に感じたので伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"1)生活支援サービスの中での生活相談、緊急対応、大井林町でも行っているところです。考え方にもよりますけれども、青葉会のｃａｒｎａ五反田につきましては、サービス料金が変わってきているというような考え方です。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今後、こういったサービス付き高齢者住宅を、こういう状況なら、この違いを見て、私は本当に区立で建てていただきたいと思いました。今後、建設していく計画、検討、また、民営でも建設しようとしているところがあるとか、そういうものは今のところ、どうか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"そういった法人事業者等がありましたら、これにつきましては開設を支援していくという区の考え方で、これまでも進めてまいりました。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"それで、生活相談、安否確認、要は基本サービスのところ、ここも青葉会ですよね、ここの体制を伺いたいのです。２４時間なので、どう回していくのかは、こちらでわかるのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"生活支援サービス、緊急時の対応等々ですけれども、それから６階のスタッフステーションで対応するということで。それから、緊急時の対応につきましては、各部屋に緊急通報装置を設置しておりますし、また、ごみ出しというのがあります。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"こういった高齢者住宅を求める声もあると思うのですが、本当にちょっと厳しいと感じます、今の高齢者の実態を見ると。ですので、そういったところもしっかりと運営事業者と検討を十分にしてほしいと求めました。","respondent":"白鳥高齢者いきがい課長","answer":"今回の事業者への支援という区の立場からいたしますと、これから多くの事業者が出てきた場合にも対応できるような、見守っていきたいと考えています。","id":"exchange-012"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"ほかによろしいでしょうか。私から確認なんですが、Ａ３版の資料をつくっていただいたのは、こういう場合は選考方法は入れないものなのか。","respondent":"白鳥高齢者いきがい課長","answer":"今回は、入居者の募集のところにつきましては、選考方法については省かせていただいたところです。このような決め方をさせていただき、入居者の待機者を登録ということになりますので、公開抽選という形を取らせていただけたらと考えています。","id":"exchange-013"}]},{"id":"topic-03","title":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","agenda":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","exchanges":[{"speaker":"向委員","kind":"確認","question":"２点確認なのですが、法人寮２戸ということですが、このうちの単身者用と障害者用のトータル１４戸ということでいいですか。ただ本社が大田区になっていたような気がしたのですが、荏原一丁目というのは、どういった住所なのか説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"別に法人のほうとの契約がありますので、全体で、グレースマンションに対しては、１６戸の契約ということです。品川区荏原一丁目での事業が、これまでよりも拡大したことによって、本社機能の部分だけを大田区に移転したと聞いてあります。","id":"exchange-014"},{"speaker":"向委員","kind":"質問","question":"では、法人寮２戸の部分の詳細というか、内訳を教えてください。本社としての会社の情報を書くものではないかと、ちょっと思ったので、そのあたりのお考えをお願いします。","respondent":"永尾高齢者福祉課長、白鳥高齢者いきがい課長","answer":"高齢者福祉課のほうで、区内の社会福祉法人が設置・運営する障害者・高齢者施設に勤務をする常勤職員に対して貸し付けをしています。介護職員の福利厚生という意味で、職員住宅として貸し付けているという内容になっております。これまでのカーマトラストとの契約解除、まずはそちらのほうを踏まえた中で、三ツ星電器との契約になります。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問","question":"たしか第２回定例会の議案でやった中で、そこに住んでいる方の内容は変わらないと思うのですけれども、何かちょっと落ち着かない感じがします。この辺は、その辺は、つかまれていたらもう少し詳しい内容を教えてもらえればと思います。","respondent":"白鳥高齢者いきがい課長","answer":"そのまま高齢者住宅として継続、管理人も変わりませんし、入居者に対して何ら影響が出るものではないとは考えているところです。一つ、事前通知というものを設ける予定で、今進めているところです。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"意見","question":"もう当時者間である程度決まってから、区のほうに連絡が来たということなのでしょうね、おそらく。どうしても不動産などは、その辺をしっかりお願いしたいということで、一言お願いしますとの意見を述べました。","respondent":"白鳥高齢者いきがい課長","answer":"これから進めるにあたりましては、十分にその辺のところは注意しながら、これから進めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、どういう精算をされたかということについては、まだ品川区がタッチしないのですよね。こういう場合の家賃の取り扱いなり、品川区の介入の仕方、対応についてどうされてきたのかということを確認したいのです。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして、今回の８月までの分のカーマトラストに対する家賃につきましては、７月に８月分の家賃相当額をお支払いしているという状況です。８月分、９月分合わせまして、９月２０日ごろまでに２カ月分をお支払いするといった形で会計処理をさせていただこうと考えています。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の内部規約なり、それから、品川区としての一定の方向性はあるのですか。それとも、これから検討していくのでしょうか、説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"これまで長年２０年間という契約期間を経過し、これまで３棟につきましては、１０年間延伸ということで再契約をさせていただいたです。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、皆さんからいろいろ質問がありましたけれども、住まれている方、居住者全員、こういう状況はもう知られているのでしょうか。居住者の方からの声などは、何か出ているものはないか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"貸主が変更になったということにつきましては、お困り事の相談ということにつきましては管理人にということで、掲示はしています。ただ、貸主の所有者が変更になったということにつきましては、特段お知らせはしているものではございません。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"貸主が変わっていく、では次はどうなってしまうのかと、住んでいると不安にもなっていくかなとも思うのです。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"そういうデータみたいなものは、やられている方については、一応指定管理者のほうで把握されているのかどうか。そういうものを一つの成果としてＰＲしていくようなことはやられているのかどうか、説明を求めました。","respondent":"川島健康課長","answer":"現状を知り、トレーニングをしばらくやってから効果測定をするという使い方をしている方がほとんどになるようなところです。４,８５３件という説明をさせていただきましたが、それぞれのトレーニングの効果を確認しているような使い方をされているということになります。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"意見","question":"２,００７人の方が複数回利用されて、例えば３カ月後とか、自分ではわかっていらっしゃると思うのです。それをどうＰＲするかは、それを活用するようなことは何か考えているのか、もしくはやっているのかということなのですとの意見を述べました。","respondent":"川島健康課長","answer":"今のお答えの前に、簡易な健康機器になってしまうという説明が漏れました、申し訳ございませんでした。何か個人を特定するとかという話ではなしに、この機器の有効性ですとか、少し指定管理者のほうにも働きかけていきたいと考えています。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"意見","question":"いろいろな介護予防までいくかどうか、これだけの結果が出ているということは、当然検証していかないといけない。そういうご報告をいただければ、それは自信を持ってこれからも進めていけるのではないかと思うので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"自ずとこの表現の仕方、写真の使い方も変えていく必要があるのではないかと思ったのですが、その考え方はいかがでしょうか。もっと運動をしてほしいような年齢の方々、企画検討していくべきと思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"１点、働き盛りの４０歳、５０歳代の方についてどうしていくのかということ。少し検討させていただきたいということで、何をしていくかということが示せるように、今検討しています。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"区民の方々はそういう制度のお世話になる可能性が低くなるわけですから、健やかな一生を送ってほしいという願いがあるとするならば、それから。もう一言だけお願いします。","respondent":"榎本健康福祉事業部長","answer":"確かに健康センターだけで考えると、もしくは国民健康保険のお世話にならないでなるべく健康でいくということが大変重要なことになってきております。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"一つは、延べ利用件数ですけれども、具体的に年間５,４９４件云々とありますけれども、大体年代別の数がわかれば教えてほしいと思います。健康を改善するための健康センターにつなげられるような、そういうことは考えたことはお有りなのかどうか、その辺りを教えてほしいと求めました。","respondent":"川島健康課長","answer":"それから、企業との連携というお話ですね。ＰＲになるということで、例えば健康センターと何か組めないかとか、そういったことはきっちり検討して進めていきたいと考えております。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"健康センターの取り組みについて伺いましたけれども、そうではない、どういうふうに呼びかけていくのか。今、参加できていない方々に対してのアプローチは、どう考えていらっしゃるのか尋ねました。","respondent":"川島健康課長","answer":"先ほどお話ししましたが、いろいろな使い方ができるということがありますので、もっと周知の仕方を工夫してやっていきたいと考えております。もう１カ所スポーツジムにある、だから２台あるだけという現状だそうですので、もっともっと工夫して周知していきたいと考えています。","id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それがモチベーションにもつながっていくので、Ｂｏｃａも、自分の上下のバランスとか、左右のバランス、私も今見ていて、へえっと思ったのです。健康センターでもこういうことをやっているというのは、ほかの事業の場で、健康センターのＰＲなどはされたりしていないのか尋ねました。","respondent":"川島健康課長","answer":"もう少し工夫して、こういったいいものがあるのだということを、今まで以上に伝えていけるように工夫していきたいと考えています。","id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、１枚目の裏のところの運動指導士というのはどういう資格ですか。管理栄養士は国家資格ですけれども、運動指導士というのはあまり聞いたことがない資格なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"区内、都内でも何人か熱中症でお亡くなりになったという中で、品川区でも１名という報道があったのです。今、東京都から情報が来るということなのですけれども、亡くなられたとか、そういう情報もつかんでいらっしゃるということか尋ねました。","respondent":"高山品川区保健所生活衛生課長","answer":"先ほどご報告申し上げました８０名という数字の中で、直後の初診時で死亡というものは、この中には一切ございませんでした。軽症でそのままお帰りになった方が４３名、５３％くらいということで、そういった形で把握させていただいているところです。","id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どういう点が非常に、理事者のほうはお考えなのか、ちょっとお聞きしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"実際にどういう形態なのか、中身がどういうことがいいのか、そういうものの参考にということで。〔「縦横連携ということか」と呼ぶ者あり〕 さらにその後どういうふうにつながっていくのかというのは、品川区でも課題になっていますので、その辺も含めてご視察いただければと思います。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問・要望","question":"行政がどれくらいこれに対しての距離感というのですか、まだそこまでは、ということなのか。それに対して行政がどう関わって、バックアップしていくのかというようなところを中心にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ケアマネジャーと、訪問看護の看護師と、全体が集まって顔を見せてお互いにいろいろ意見を出し合いましょうというような会議を始めたみたいです。私は小児科なので、出ていないのでわからないのですけれども、最近、時々といいますか、定期的にやるような動きがあるのですよねとの意見を述べました。","respondent":"榎本健康福祉事業部長","answer":"もう少し小さいグループ化したもので検討をして、その部会のほうに上げていこうかということで、今検討を進めているところです。そういう連携名簿みたいなものをつくったりとか、情報をどういうふうに共有しようかというところも検討していかなければいけないところです。","id":"exchange-034"},{"speaker":"向委員","kind":"意見","question":"酪農の人だったり、職業的な違いとか、傾向がどんなふうにあるのかというのが気になっています。この資料の３ページに、もうやっぱり救急搬送にすごく時間がかかる傾向があるのかどうか、もし可能であればとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363412?Template=document&Id=3394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":46360,"voices":118}},{"id":"h26-20140825-8","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"建設委員会","time":"午後１時００分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、区民住宅（あき家）入居予定者登録募集","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"大体年間にあく部屋がどのぐらいあるのか教えていただきたいのと、この９月に登録募集をして、登録された方がどういう手続をするのか説明を求めました。","respondent":"矢木住宅担当課長","answer":"出られたり入られたりするので難しいところなんですが、直近で押さえている数字といたしましては、８月２１日現在で１５戸ほどとなっています。ですので、退去されて出る方もいるので、毎年この募集段階は大体この程度の戸数というふうにお考えいただければと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"品川区空き家等実態調査中間報告","agenda":"品川区空き家等実態調査中間報告","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"拝見させていただいて、幾つかお尋ねしたいところがあります。品川区における空き家数の推移とありますけれども、世間一般にいろいろな理由が言われていますけれども、ここのところの分析を説明を求めました。","respondent":"矢木住宅担当課長","answer":"なかなか、少なくとも国の法案に沿って居住その他の使用がなされていないことが常態である建築物は、広く空き家と考えて調査をしていく趣旨です。こういう現状が、現在いろいろなご相談をいただくんですが、多いようです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"条例案のほうのスケジュールのことについても伺いたいんですが、７月に２回、ごみ屋敷について触れている部分が少ないように見えるんです。そういった調査はこの中でやっているのか、あえてこの中にはまだ載せていないのか、そこを説明を求めました。","respondent":"矢木住宅担当課長","answer":"通称と言わせていただきます、いわゆるごみ屋敷と言われているものにつきましては、情報としてデータ化はしております。そういうものを固めた中で、いわゆるごみ屋敷については今後、調査をしてまいる方向です。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"以前にもお伺いしたかと思うんですけれども、ここはちょっと気になるところですので今後推移を見守っていきたいと思います。例えば町会からの要望の中に、この辺について、どこと今調整をされているのか説明を求めました。","respondent":"矢木住宅担当課長","answer":"私どもという、おおよそ空き家対策およびいわゆるごみ屋敷の両方に今後関係してくると想定されるところは、全て入ってあります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"確認ですが、もしくは都市計画課全体の中で提案をして、いわゆるそのやり方について教えてほしいと求めました。","respondent":"矢木住宅担当課長","answer":"そこを含めて大きな枠で検討した後に、まことに申しわけありません、柔軟に加えさせていただいて問題解決をしていきたいと思っています。実際上どのぐらい利活用できて、その方策についてはまたＰＴなどを組んで庁内全体で情報を共有しつつ、検討していきたいと思っています。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"高齢者福祉課が庶務担当課であるということで、福祉の視点はもちろん入っているということは理解いたしました。この法案に先行させて条例案を上程していくという考えなのか、それともその対応をどういうふうに見られているのか、最後にお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"品川区といたしましては、前回答弁申し上げたように法案の成立を注視しながら、さりとて法案がいつできるかというのが確実視できない中では、慎重に時期等を見きわめながら成立に向けて準備をしています。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"非常に難しい、多分各自治体が悩ましいところであると思いますので、よろしくお願いいたします。今回、行政視察もありますけれども、しっかり我々も勉強して、いろいろ情報交換をしながら、よいものをつくっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"すぐに対処すべき問題だとこれは思うんですけれども、そこのところはどういうふうに、これはあまり時間に余裕を持ってやる調査とか事業ではないと思うんですけれどとの意見を述べました。","respondent":"矢木住宅担当課長","answer":"その件につきましては、条例の成立以外に現段階で現行法上取り組むことは、先ほど申し上げた各課から構成されたチームで実際に動いてあります。ということで、ご理解いただければと思います。","id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"あくまでも私有の財産なのでいじりづらいことはわかるんですけれども、そこのところどういうふうに役所では、迅速に対応するにはどのような体制をとったらいいと思っていますかとの意見を述べました。","respondent":"藤田都市環境事業部長","answer":"そういう意味で今、既に地域の力支援チームということで、先ほど申した各課が連携しながら、問題解決のための話をしている形になっております。そこにお住まいの方々をいろいろな形でケアすることが最終的な解決になるというふうに考えてありますので、今、対応しています。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"来春ですか、どのようにすべきビジョンを持たれているのか、教えてほしいと求めました。","respondent":"藤田都市環境事業部長","answer":"ただ、地域の方々で何か活用してくれないかということであれば、利用をするというような形の検討も一つあるかと思ってあります。この撤去等については、木密１０年プロジェクトの不燃化特区といったような枠組みの中では、トータル的に解決を図っていければと考えています。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"関連部署の話をお聞きしたんですけれども、町会というのは、実際に所有権とかになってくると意外と把握していない方もいらっしゃる。ですから区の行政としてどこまで、今の段階で結構なのでどこまでをというふうにお考えになっているか、まずお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"私ども内部だけではなく、例えば宅建協会であるとかその他外部の方と連携をとりながら、当然のことながらつくっていく方向性ではあると考えています。という余地はあると思います。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"ところがお金というのは、誰が払っても向こうは受け取りますので、実際の所有者かどうかわからないと。もう一回確認させていただきたいんですけれども、税務的な面からの検討もされていらっしゃるのかどうかという、お考えをほしいと求めました。","respondent":"矢木住宅担当課長、藤田都市環境事業部長","answer":"直接どうこうという検討ではございませんが、当然のことながらできる協力はするということで、都税事務所のほうの所管の課長とも話をしております。ただし… 税の優遇的な措置をやめてしまうことを検討しているというようなことも聞いてありますので、その辺の策と合わせながら、空き家対策を進めていくのがよろしいのかなと考えています。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"ぜひ頑張っていただきたいのですけれども、行政がいろいろなデータとか情報を、まちから声をいただくと。民間のものもあるようなこともちらほらとお聞きしますので、その辺についての思いを、最後にお聞かせほしいと求めました。","respondent":"矢木住宅担当課長","answer":"入り口も多々ある中で、ただ、どこが聞かれても同じように対応ができるようにという横断的な組織をつくりつつあるところです。最後に亡くなった方が１０年、２０年経過してしまいますと、実情ではあります。","id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"早い時期に条例化を進めていただきたいというお願いと、本当に全部一つずつ違っていると思いますので、その辺をお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なことをお伺いしたいんですが、１ページ目のところの「品川区においては住宅総数」、ここの理解を教えていただきたいのがまず１点です。「居住世帯なし」と「空き家」の違いをどう捉えたらいいのか、ちょっとここがよくわからないので説明を求めました。","respondent":"矢木住宅担当課長","answer":"こちらはゾーンがございまして、例えば２０万から４０万の世帯は何％というふうに割合がございまして、その割合に応じて抽出したものです。一時、要するに事実的に人がいるようなものを抜かしたのが、空き家という形になっております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"一戸建ての空き家が５.７％で１６位、全体で１２位となっているところにおいて、それぞれの推移を見て両方とも同じように増えているのか。その辺の分析があったら、推移的に一戸建ても増えているのかどうかというところがわかったら説明を求めました。","respondent":"矢木住宅担当課長","answer":"空き家数の推移ですが、共同住宅のほうもやはり空き家率は、全体からいきますと微増しているのかなという感じなんですが、一軒家のほうが大幅に空き家が増えていると、そういう状況です。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５ページのところでカーネル関数というので図が出ていまして、まだ出ていなくてやっていないところが、そういうことなのかどうか教えていただきたい。先ほどから早くしてほしいという声もあったんですが、そういう意見を持っているんですけれども、いかがか尋ねました。","respondent":"矢木住宅担当課長","answer":"やらないということではございませんで、地域についても品川区内全域調査というお約束になっておりますので、調査はしてまいる予定です。ご要望を反映して制度全体を、条例のみならず規則等でつくってまいりたいと思いますので、よろしくお願いいたします。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このスケジュールだと第３回定例会に上程と書かれていますよね、十分意見を聞いて慎重にやっていただきたいということは、意見として述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"の東品川四丁目地区のまちづくり","agenda":"の東品川四丁目地区のまちづくり","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"確認なんですけれど、現状ってここはサッカー場みたいなものができているところだったと思うんですが、これを運営しているのが、今の事業者がそれまではそういう形にして、この案件とは直接関係ないかもしれませんが、そういう認識でよろしいか尋ねました。","respondent":"溝口都市開発課長","answer":"現在、Ｃ街区につきましてはサッカー場と時間貸しの駐車場になっていると思います。こちらにつきましてはあくまでも暫定利用ということで、事業者３社が共同で実施しているです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にこの報告をしたのがいつだったのかということと、あと、まだ残っているところがＤ地区で幾つか残っているのですか。ここは共同住宅で８２０戸となっていますけれども、ここの地域全体で住宅がどのぐらい増えたのか、増えるのかを説明を求めました。","respondent":"溝口都市開発課長","answer":"続きまして残っているところになりますけれども、実はＤ３－４街区もまだ現在、地区計画変更はしましたが建築物は建っていない状況になっています。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住宅等はＵＲのその賃貸の２棟と、今回の８２０戸、ちょっとその辺の全体がどういう地域なのかを教えてほしいと求めました。そういった規制緩和的なものの変更があったのかどうか、当初どうだったのか、説明を求めました。","respondent":"溝口都市開発課長","answer":"基本的には業務、商業、住宅、そういったものをバランス、配置を考えて、これまでまちづくりを進めてきたというのが経緯です。今後説明会等で詳しく説明するようになりますが、５９０％まで容積率を上げる形で、検討しています。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育所が入っていますよね、これはどういう保育所かちょっとわからないですけれど、この辺で補助金が入っているということでしょうか。ここで高さ９７メートルですよね、１００メートルを大きく超えたところはないんですけれども、この辺の高さはどう考えたらいいのかも説明を求めました。","respondent":"溝口都市開発課長","answer":"保育施設につきましては、そういったものがどういう形になるかというのは、今後詳細を検討していく中で決まっていくものと聞いてあります。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"航空制限で１００メートルぐらいなんですか。６０メートル以上を高層建築物と言っていますけれども、どのぐらいもつのかというのと、将来的なことをどう考えているのかもあわせて説明を求めました。","respondent":"溝口都市開発課長","answer":"ただ単に緩和しているわけではありませんので、また公園につきましては計画的なまちづくりを進めておりまして、容積率の緩和をしているものです。冒頭説明したとおり品川シーサイド駅の開業に合わせて、これまで進められてきた地区、ご報告するものです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会の開催ということですけれども、(3)対象区域で、２倍の範囲というのはいつもそうなんですが、「および地区計画区域内」の対象というのはどこなのか教えていただきたいのと、この説明会の周知は既にどういうふうにされていたのか、説明を求めました。","respondent":"溝口都市開発課長","answer":"これまでまちづくりを進めてきたという経緯がありますので、その地区内についてもしっかり周知を図るということで、今回最終的に定めたところです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと聞き漏らしてしまいましたが、地区計画区域内というのは、この地図で言うとどこなんですか。Ａ街区の真ん中ぐらいまでと言っていましたが。","respondent":"溝口都市開発課長","answer":"本来であれば２Ｈの範囲外になるんですが、地区計画の区域は全て説明会の対象ということで定めて周知をして、今回の説明会を開催するというものです。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ説明会での地域の方々の意見をよく聞いていただきたいと思うのと、ここのところ本当に、本当に行政以外に調節するところはないんですよね。その大きなところでの捉え方でぜひ研究していっていただきたいんですけれども、いかがか尋ねました。","respondent":"藤田都市環境事業部長","answer":"ＣＯ２で考えると、次に今頑張っていろいろまちづくりを進めているような国が６割ぐらいのＣＯ２の排出をするというふうに。省資源の建物等も今できておりますので、そういった施策を合わせながら、進める開発等をしっかり誘導していきたいと考えています。","id":"exchange-026"}]},{"id":"topic-04","title":"の中延駅放置禁止区域の変更","agenda":"の中延駅放置禁止区域の変更","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"あれは通勤ですかね、どういう方が置いていらしたかわからないですが、これは禁止区域を広げていくことで解決するのでしょうか。そういった指導もあわせてやっていかなければいけないのではないかと思っていますが、いかがか尋ねました。","respondent":"田口交通安全担当課長","answer":"指導啓発事業ということで警備員を平成２４年まで配置していたという実態がありますが、そちらのほうに展開しております。この辺も、ＴＳＵＴＡＹＡ等と連絡を図りながら、啓発活動を行っていきたいと考えております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"駐輪場の利用台数が８割ということで、ソフト面でやれるところもしっかりやっていただきたいし、東急の責任も大きいと思うんですね。ぜひ早急にそういった面でも改善をされますように、ぜひ声を強力にかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"の品川区災害対策基本条例概要版","agenda":"の品川区災害対策基本条例概要版","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"備蓄の問題とか全然、これから建つマンションに対して、防災の備えとかこういう配布物をどういうふうに周知していくのか教えてください。２点です。","respondent":"鈴木防災課長","answer":"ただし区民の皆さんに取り組んでいただける対策というのは、この挨拶文では減少のほうの説明をさせていただいているものです。そこの管理組合の方に建物全体での取り組み等のお知らせをしたりする中で、新しいところにもしっかり配っていきたいと考えております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"今の配布の状況からすると、全体でどのぐらいつくるんですか。私、何となくこちらと一緒かなと思っていたので、その規模かなと思ったんですけれど、何部つくるのか説明を求めました。","respondent":"鈴木防災課長","answer":"こちらのほうは、昨年度つくった時点で５,０００部作成しております。今回２万部ほど増刷を検討中ですので、数についてはまたこの後変動があるかもしれませんが、一応それぐらいのことを予定しております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"せっかく条例ですから、品川区も幾つか危険箇所があるんですけれども、この辺というのはそこの地域の方には十分伝わっているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさい、広げちゃったら目に入ってしまったものですから。","respondent":"鈴木防災課長","answer":"基本になりますのは東京都のほうでつくったハザードマップに、区のほうで新しい情報を追加してこの１枚の地図にしたというものです。その新しい情報が加わったこと、本体の地図のほうの見やすさの改善等も含めて、新しくなったものを今回全戸配布したです。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自分の住んでいるところ、新しい情報ということで伝わっていると思うんですが、いろいろな機会で周知をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけです。もうちょっと激しい感じのデザインであれば、かなり優しい感じのデザインになっている、このコンセプトをちょっと教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"もしくは大きな災害に対して立ち向かうということで、かたいイメージ、強いイメージの案も当初はございました。その中でただ怖がるのではなくて、この安定した連携とそれぞれの力を合わせるというイメージで、このようなデザインにしたものです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"一定の理解はしますが、この葉っぱは何をイメージしたんか尋ねました。","respondent":"鈴木防災課長","answer":"これは、ご覧いただきますように若い色の葉っぱですので、これから成長したり、命の象徴というイメージというところでございまして、特別な意味を持ったものではございません。","id":"exchange-035"}]},{"id":"topic-06","title":"の平成２６年度地区総合防災訓練","agenda":"の平成２６年度地区総合防災訓練","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この児童センターだけなんでしょうか。よその地域は、結構あちこちで外国人の方は増えていらっしゃるんですけれども、その辺はどうなっているのか説明を求めました。","respondent":"加藤防災安全担当課長","answer":"広い範囲での訓練に参加を呼びかける取り組みの一つで、そこの児童センターに来る子どもたちを呼んで、それで一緒に参加をするという取り組みです。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"協議会の中での話し合いで決まったと、この児童センターは全地域ですか。特に各地域で共通した問題点とか出たとき、上がってきたご意見をどう具体化されていくのか、その点を説明を求めました。","respondent":"加藤防災安全担当課長","answer":"児童センターは、児童センターが基本的に子どもたちに声をかけるという取り組みです。あるいはまた各地区の協力が必要であれば、またその動きの中で対応していくというような状況です。","id":"exchange-037"}]},{"id":"topic-07","title":"では、行政視察","agenda":"では、行政視察","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"品川区ではいわゆるごみ屋敷も条例案の中に含んでいくというようなお考えがあるということなので、そこの考え方をどういうふうにされたのかというところを、その辺についても聞ければと思いますとの意見を述べました。","respondent":"松代防災まちづくり事業部長","answer":"以前、職員の政策課題研修等で、やはり少し課題が出されました。このようなことで質問にお答えいただければというようなことも、効率的な説明になるのかなと思うんですが、いかがでしょうか。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":37279,"voices":112}},{"id":"h26-20140825-9","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"文教委員会","time":"午後１時００分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"の平成２７年度品川区立小・中学校使用教科用図書の採択","agenda":"の平成２７年度品川区立小・中学校使用教科用図書の採択","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"複数の学校の教諭が校長の指示で覆されたと、そういう記事があったのですけれども、こういう状況についての教育委員会の見解というのはどういうことか教えていただきたいと思っています。","respondent":"渋谷指導課長","answer":"他県の状況はよく把握しておりませんけれども、品川区の採択の状況、今ご説明しました方法では、そういった形の恣意的なことは関与する余地はございませんので、全くそれについてはコメントを差し控えさせていただきたいと思います。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そういうベースを大事にしていただきたいと思っているのですけれども、それについての見解を伺っているのですが、いろいろ教育委員会としての考え方を聞きたいと考えています。","respondent":"田村教育次長","answer":"その基礎資料をそれぞれの検討の会議で客観的に判断したものを資料として教育委員会のほうに上げて、うちの区についてはそういう可能性は全くないというふうにご理解いただきたい、そういうふうに思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そして、そこを言いたいのですけれども、そういうことをよしとしない姿勢を毅然として保っていただきたいということをお願いしておきたいと思います。この件については、それ以上触れない、答弁がないからあれですけれども、触れないで終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。先ほど、地域の方も含めたところでいろいろ検討されるというお話があったのですが、その人選は基本的にどういう流れで行われるものなのか尋ねました。","respondent":"渋谷指導課長","answer":"ＰＴＡ等地域の方については、ＰＴＡ連合会の会長であるとか、そういった方をお願いしていると。ただ、細かい中身については、８月末まで時限秘ですので、そちらについてはご説明は差し控えております。","id":"exchange-004"},{"speaker":"高橋委員","kind":"質問","question":"お尋ねしたいのですけれども、それについてお尋ねしたいのですけれども、長らく教科書を使っていたものを今回変わると思うのです。の委員のほうからの質問とか、そこでの変わることについての議論というか、もしこの段階でお話しすることができるならば伺いたいと思います。","respondent":"渋谷指導課長","answer":"今ご説明申し上げたとおり、教育委員会、採択に関しては８月末まで時限秘になっておりますので、審議の内容等々につきましては、９月になってから教育委員会のホームページのほうでアップロードしますので、そちらをご確認いただければと思います。","id":"exchange-005"}]},{"id":"topic-02","title":"の全国学力・学習状況調査の結果の取り扱い","agenda":"の全国学力・学習状況調査の結果の取り扱い","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。中学２年生が行われているのですが、この辺は、その辺の考えというのは教育委員会としてどういうふうに思っているのか説明を求めました。","respondent":"渋谷指導課長","answer":"さまざま検討を進めてきているところでありますが、特に４技能、書くをバランスよく評価することが大きな課題になっております。読む、書くの４技能全てを見ることができる調査、ＧＴＥＣというものを導入して実施するという形で取り組むような形をとらせていただきます。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"７年生の結果を受けてですから、５年生と６年生の時期に何をどういうふうにすれば身につくかという、そういうことは言えるのですかということが１つ。４年生の学力定着度調査の結果について、４年生を設定しているというところの意味、そこをまず伺いたいということが２つ目です。","respondent":"渋谷指導課長","answer":"説明が十分でなかったようですが、２月末に実施した調査については、５月に４年生部分の分析をして。改めて７年生部分については８月、品川の学校は４年生と７年生、二段階で改善策の態度表明を行っているです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"平成１５年からですから９年ぐらい続いているわけですけれども、私たちも指摘をしていたのですけれども、それが目的ですから。なかなかそういうふうになり切れていない原因の１つがこういうテスト対策にあるのかなと思うので、そのあたりの見解を伺いたいと思います。","respondent":"渋谷指導課長","answer":"４年生という実施時期についてですが、その次は６年生で実施をして、７年生の実施というふうな変遷をしてきております。その本来業務についてしっかりと責任を果たしていくということは、私たちのしっかりやるべき仕事であるというふうに考えるところです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"もっと現状をしっかり見ていただきたいと。そこのところはしっかりと大事にしていただきたいということをお願いにとどめておきたいと思いますけれども、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺は地域性というものは教育委員会がどう考慮していたり、考えているのかをまず１点伺いたいと思います。伸びしろの部分というのですか、１人当たりの児童、あるいは１人当たりのクラスがどう伸びていったかという。","respondent":"渋谷指導課長","answer":"そもそもこの学力調査は、それぞれの地域、その実態に応じてきちんと学力の定着状況に応じた対応をしていくということが大事ですので。ただ、まだまだ課題の多いところで、私どもも今後しっかりと研究をしていきたいというふうに考えているところです。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"現状どうなっているのか、今後これを生かす余地があるかどうか、ちょっと関心があるので伺えればと思いました。いかがか尋ねました。","respondent":"渋谷指導課長","answer":"平成１４年、今、委員のほうからご指摘になった個人内評価をしっかりやっていこうというふうな形に学校はどんどん変わってきております。成就感をしっかりと確認して、次の学習の学びの意欲につなげていこう、そういう姿勢で今の取り組みが進んでいるというふうに思っております。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"そういったガイドライン的なものがあるのかどうか、個別の特色ある学校づくりにおける学力というものをどういうふうに各学校と連携をされているのか。ここまでは打ち出していい、ここまでは控えたほうがいいとか、表現の仕方も含めて、その辺、現状どうなっているのか説明を求めました。","respondent":"渋谷指導課長","answer":"最低基準という考え方ですので、子どもたちの負担だったりとか、そういったことを考えながら十分に配慮しながら進めてくださいということが一定のラインです。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問","question":"現状そういう傾向だとか、あるいは、具体的にそれを発信している学校はあるのかどうか。それに対して教育委員会は推奨する立場なのかどうか、その辺を伺おうと思いました。","respondent":"渋谷指導課長","answer":"例えば、日野学園は、勉強合宿等々に取り組んで、特色ある学校づくりとして学力の充実に取り組んでいます。この部分を特色として打ち出したいとかということについては、基本的にプラン２１の予算等々で教育委員会としては応援していくです。","id":"exchange-013"}]},{"id":"topic-03","title":"のビーチバレー体験ワークショップの実施","agenda":"のビーチバレー体験ワークショップの実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この小学生１００組なのですが、何年生でもいいのかどうかも含めて教えていただきたいのと、ちょっとそれはいいです。それから最後に、予算額がもしわかれば教えてほしいと求めました。","respondent":"伊崎子育て支援課長","answer":"こちらが小さいコートを８面ほど張る予定ですので、そのコートに何人か、２０名から３０名来ていただけるとうれしいなと思っているところです。詳細を持ち合わせていないのですが、報償費と一般需用費で３０万円程度というところで考えております。","id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問","question":"説明の中で中学生のボランティアをバレーボールの経験者というようなお話があったのですが、バレーボールを経験しないと、このボランティアは参加できないのかということを１点、まず説明を求めました。","respondent":"伊崎子育て支援課長","answer":"こちらは中学生の方のボランティアとしましては、小学生のバレーボールの補助とか、あと、審判ということで考えていますので、中学生の方はバレーボール経験者がこちらとしては望ましいということでお願いをしています。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"やはりある程度参加したいという希望を持った子どもたちもぜひ参加をできる枠組みをとってもらいたいなというふうに思うのです。できる限り参加したいという子がいればできるような仕組みにしてもらいたいのですが、その点、どのように考えるか説明を求めました。","respondent":"伊崎子育て支援課長","answer":"学校の関係の中体連を通してお願いしていただきたいということで、今、手配をしていただいているところです。そういう方からのボランティアの希望がございましたら、それは役割を限定することにはなりますが、対応していきたいと考えております。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"今後続くのかどうかわかりませんけれども、今回間に合うかどうかは別にして、そうしたところはもう少し工夫が必要なのではないかなと思います。その辺はどうか尋ねました。","respondent":"伊崎子育て支援課長","answer":"当体験ワークショップを検討するに当たりましては、砂の上で、砂場で行うということが１つの要素であるというふうには考えました。２０２０年に向けましては、今、委員ご指摘のございましたことも含めまして、より啓発に力を入れていければと考えているところです。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"先ほどの質問に学年が明記されていない中で、１年生から６年生まで気軽さという点ではいいのですが、まるっきり感じ方が違うと思うのです。ボールはどういうふうなことを、当日、区分があるのかどうか説明を求めました。","respondent":"伊崎子育て支援課長","answer":"私、子育て支援という視点での捉え方からお答えをするというところで、十分スポーツ連盟との関係にはお答えできないかと考えております。持ってきていただくことができれば、ビーチバレー用のバレーボール、こちらのほうでできればと考えているところです。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"意見","question":"うまいね」という褒め言葉１つで、何々小学校のチームだけれども、ぜひやったらいいよとかいう大きなきっかけになるのかなという思いがありました。","respondent":"伊崎子育て支援課長、金子子ども未来事業部長","answer":"これを実施の結果を見まして、スポーツ担当の主幹課のほうには報告をし、今後に向けて取り組みと教育ができれば進めていきたいと考えております。 啓発していくかというような観点から、今回、ワークショップを実施していくものです。これからどういうことに取り組んでいけば、さらに盛り上がり、これからも研究しながら取り組んでいきたいというふうに考えてあります。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"いろいろ質疑を伺っていたら、足元が小学生ですから危ないから砂を用いないで人工芝上を靴を履いてということなのかなと思ったのですが、思うのです。子どもに夢をなどなるのかなと、根本的なところがちょっと違うのではないかと思ったのですけれども、その辺はコンセプトとしてどうなのか尋ねました。","respondent":"伊崎子育て支援課長","answer":"先ほどもご説明をいたしましたが、ビーチバレーボールの選手の動きを見てワークショップを体験してもらうというところからスタートしていきたいと考えて、今回の企画をしたものです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう点で、今の説明を伺っても、そうですか、わかりましたというふうには私はなりません。〔「思いますよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"文教委員会としての総意だということで区に求めたらいいのではないでしょうか。〔「異議なし、そうだ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"そういう感じをこのビーチバレーの企画を伺って実感したのですけれども、それでやっていますよみたいな、そういうことを感じるのです。３０万円の予算しかつかない中でやるということになってしまうし、プロ選手をお呼びする上でも、私はそういうふうな印象を持ちました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須藤副委員長","kind":"質問","question":"この担当のメンバーはやったと思うのだけれども、そういう言葉を表に使えないのだという話を聞いたのだけれども、そのあたりはどうなのですか。ＩＯＣが許さないのだという話をちょっと聞いているので、いかがか尋ねました。","respondent":"伊崎子育て支援課長","answer":"今ご指摘のとおり、著作権の問題がありまして、それを事業名に冠としては使ってはならないというお話がございました。品川区の事業としては、そこは許可できないというご指摘をいただきまして、このような形での開催となっております。","id":"exchange-024"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"お話があったように、東京都と共催という形であれば、冠も使ってやるという方向性がある程度できると思う。どうせやるなら、１つ私も勉強になった、東京オリンピックにいい形ができるような方向性をつくってほしいと求めました。","respondent":"こんの委員長、今井制度改革・待機児童対策担当課長","answer":"ご発言がないようですので、これで本件を終了いたします。 子ども・子育て支援新制度は、平成２７年４月から本格施行予定で準備を進めているところです。２の説明内容ですが、子ども・子育て支援新制度の概要、２回目とも同じ内容で説明をしていきたいというふうに考えております。","id":"exchange-025"}]},{"id":"topic-04","title":"の子ども・子育て支援新制度「区民説明会」の開催","agenda":"の子ども・子育て支援新制度「区民説明会」の開催","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"区民と言ってもいろいろいるわけですから、来年度以降どういうふうに変化するのか、そういうあたりが非常に心配だと思うのです。利用手続についてということしか書いていないので、具体的によくわからないから、教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そろそろ私立幼稚園が説明会の準備を進めていらっしゃるなど、実際にはいつ、ここの部分をまずご説明したいというふうに考えております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方たちを対象にしているということなのかをもう１回確認したいのと、もう一度、やるのであれば教えてほしいと求めました。個々の説明会でもそういったことも大いに質問としては出てくるのだろうと思うのですけれども、改めてここでも私も伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"幼稚園における説明ですが、こちらのほうの説明会の内容について詰めておりますので、幼稚園でご説明していただけるように予定しておりますので。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問","question":"ここには掲載されていないのですが、周知されるときに定員数というのはしっかりと記載をしておいていただければなと思います。お子さんと一緒だと、託児の施設を設置するのかどうかも含めて、その辺をどのように考えているか説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"実際にこれまでこういうふうな説明会の開催を見ていますと、落ち着いていらっしゃる場合は、あえてベビーバギーもお入りになれるように。１５０名から２００名ぐらいの定員で、椅子を出して、その場でなるべく多めに対応できるように工夫したいと思います。","id":"exchange-028"}]},{"id":"topic-05","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"指導時間数なのですけれども、武道とダンス、２時間から６時間、ちょっと開きがある。５時間から１０時間、開きがあるのですけれども、もう少し詳しいところを教えていただきたいのですが、どうなっているのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"これについては、特に何時間以上するとかということの規定はございません。さまざまな講師の対応で、６時間は、実際の学校の現状です。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"その辺のところも、中学校は体育科の教師の先生だけであるのですけれども、小学校みたいにほかの先生、外部の方が入ることはないのですか。その辺をお聞きしたいと思います。","respondent":"村尾学校支援担当課長","answer":"武道の中の柔道とか剣道も含めてなのですが、今後こちらのほうでもまだ学校のほうに伝えて確認していきたいというふうに思っております。２点目、それぞれ外部講師の人に来ていただくか、そこの体育の先生が一緒に教えてくれるというような学習の方法をとっておるところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺、やはり子どもたちが同じように指導を受けて、また同じような経験ができるような体制をとっていってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは１校で２つをやっているという認識の資料か、ここだけ１６校になってしまうので、そこを教えてほしいと求めました。","respondent":"村尾学校支援担当課長","answer":"最後、３点目です。姿勢、授業中の規律も含めて、声かけをしていければというふうに思っております。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"地域を巻き込めるのだったら、僕は巻き込んでやっていけたらなというふうに思うので、その辺をぜひよろしくお願いしたいというふうに思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"授業を受ける、そういう場所はどのくらい整備されているのか、そのあたりをこれが出てきたときに伺いたいなということが１つです。だから、では、どうなっているのかなと、その辺を説明を求めました。","respondent":"村尾学校支援担当課長、田村教育次長","answer":"２番目ですね。柔道とダンスについては必修になっておりますので、必ずこの授業を受けるとなっております。 新しく改築したりした学校は、武道場がきちんと設置基準の中で必要なので、武道が必修化になりますから設けています。ですから、小学校はそのためのスペースがなければ、近隣の中学校を利用してやっている、そういう事情です。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"では、一緒に対戦ということはないのかもしれないけれども、同時に受けてやっているという、必修だからやるようになったということなのですか。その学校との授業との関係で、やりくりが大変かなと思ったりするのですが、そのあたりの現状というのはどうなっているのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"実際に連携している中学校ですので、１年間の予定を見た上で、無理がない日を設定して入れている。特にそんなに大変で調整が難しいというようなことはあまりないかというふうに……。","id":"exchange-035"},{"speaker":"南委員","kind":"意見","question":"環境も含めて知りたいと思っているので、今でなくていいのですけれども、この委員会でぜひご報告をしていただけるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問・要望","question":"校長先生なり学校が頼みやすい予算どりがあるのかどうか、これをまず武道のところで伺いたいのと、ダンスのところも同じです。今、教員だけでいいものなのか、導入から２年目に入って、どういうものが現場から声として改善点で要望も含めてあるのかどうか説明を求めました。","respondent":"村尾学校支援担当課長","answer":"２点目、謝礼のほうは各校そこから支出をしているというのが現状で、一律大体同じような形になっているというふうに思っております。３点目、ほかの人から、外部のものを入れようというような声を聞いたということはあまりないかなと思っています。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そこに単に任意のボランティア、善意も大事ですが、せっかくの武道、ダンスという必要性、その意味合いとして質を求めてもいいのではないかと。品川区全体としたらどういう方向性に持っていきたいのか、私の質疑から考えられること、今後どうしていくかという点をお聞きできればと思います。","respondent":"村尾学校支援担当課長","answer":"区としては、子どもたちにとってやっぱりいいものを見せるとか、いいものに触れるということはすごく大事なことだと私も考えております。","id":"exchange-038"},{"speaker":"つる委員","kind":"意見","question":"参考までに今のダンスのところで、現代的なリズムのダンスについてのところなのですが、把握している範疇でいいのですが、どういう曲を使っているかというのは押さえていますかとの意見を述べました。","respondent":"村尾学校支援担当課長","answer":"具体的な曲までは、ちょっと今ここではわかりません。","id":"exchange-039"},{"speaker":"つる委員","kind":"確認","question":"今後そういったところとか、全部が全部は難しいとは思うのですけれども、ジャンルだけでもある程度押さえておく必要があるのかなと思います。表現の仕方もいろいろ出てくると思うので、その辺をきちんと確認しておいたほうがいいのではないかと思いますけれども、この辺はどうか尋ねました。","respondent":"村尾学校支援担当課長","answer":"私のほうも、もう１回学校のほうを確認して、それぞれどのような曲を使って、またどのような目的を持ってやっているかということを確認させていただきたいと思います。","id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"社会に対してどうだとか、それはそれで１つの文化だし、そういう内容の曲の中で踊っていたのねということはあるのかと思います。そうしたところも若干確認をしながら、その中で自由な表現方法としてある部分というところでやっていく必要性がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高橋委員","kind":"質問・要望","question":"武道のほうで１つお尋ねしたいのは、まずそこの確認と、確認です。それからあと、区のほうの体育部会でしょうか、そちらのほうでダンスの指導についての議論というのはどうなのか尋ねました。","respondent":"村尾学校支援担当課長、野呂瀬学務課長","answer":"２つ目のダンスにつきましては、区のほうでダンスを特に研修をしているということは、現在ございません。ただ、中学校の体育の先生同士でダンスについていろいろ情報交換をしているということは日ごろからありますので… 柔道ですと７,３００円、剣道ですと５万円を限度額として、その学校でどこでどのぐらいまでということが決まっている。","id":"exchange-042"},{"speaker":"高橋委員","kind":"質問・要望","question":"武道のほうの用具については、柔道についてはわかったのですけれども、剣道は、これもやっぱり学校で貸与という形になるのでしょうか。そこも確認です。","respondent":"村尾学校支援担当課長","answer":"剣道につきましては、学校が購入して生徒に貸与しているという形です。２点目の研修につきましては、外部人材を含めて本当に検討を進めていきたいというふうに思っております。","id":"exchange-043"},{"speaker":"須藤副委員長","kind":"質問","question":"この２時間、６時間の時間でそれだけ得られるかと思うのと、「伝統的な行動の仕方を守ろうとする態度の育成」とは何だろうと。そのあたりがどういうふうになっているのかということが１点と、中学校１０校で、説明を求めました。","respondent":"村尾学校支援担当課長","answer":"２点のご質問です。２点目、この取り組んでいる学校に伺ったときとかは、この取り組みは何らかの形で今後も広げていければいいかなというふうに思っております。","id":"exchange-044"},{"speaker":"須藤副委員長","kind":"質問","question":"スタートしたときに投げられて、あるいは、竹刀でたたかれて痛いよという思いだと嫌いになってしまう。多少費用がかかっても、正しい武道なりダンスなりを教えてもらうという仕組みが品川には必要だろうと思うので、その辺はいかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"委員おっしゃるとおり、やはり指導者の姿勢というのは、子どもたちの教育上とても大切だと思います。先ほど来、申し上げたとおり、教育委員会としても進めていこうというふうに考えているところです。","id":"exchange-045"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"ですから、学力についてはすばらしいよと言われてきているけれども、同じようにそのこと自体も本物を取り入れているよという仕組みをぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":48245,"voices":124}},{"id":"h26-20140825-5","meetingId":"h26-cm08","date":"2014年8月25日","dateIso":"2014-08-25","committee":"総務委員会","time":"午後１時００分～午後５時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"の都区財政調整制度の概要及び平成２６年度財政調整交付金当初算定結果","agenda":"の都区財政調整制度の概要及び平成２６年度財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"これはどういうことなのか、品川で言うと具体的にどういうことを言っているのか、ちょっとよくわからなかったので伺いたいと思います。資料１の６ページになりますけども、いわゆる大きい単位というのですか、よくわからなかったのでご説明ほしいと求めました。","respondent":"本城企画財政課長","answer":"９ページ、１０ページの一覧で申し上げますと、今回新規算定としては全部で８項目あります。２３区で道路面積が品川区、標準区が先ほど２３２万２,０００m2ということですが、品川区は２０７万３,０００m2です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"それから、今、どういう方向にいるのか、その特徴を伺いたいと思います。結局財調部分が基金の積立にまわすと、そういう関係になっているのか、そこを伺いたいと思います。","respondent":"本城企画財政課長","answer":"先ほどの８ページのところで、財調協議の流れということでご説明させていただきましたが、冒頭７月から９月で対応方針というところで。これも含めて使ったとか使わなかったとか、そういう評価の対象となるものではないということで、あわせてご説明します。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"２階に上げてはしごをとるようなものだという例え話を言ったのですけども、都にも求めていくし、具体的に伺いたいと思います。そこについてはどうお考えなのか、疑問を突きつつ説明を伺いたいと、ご説明ほしいと求めました。","respondent":"本城企画財政課長","answer":"実際具現性ということで、２３区の中で共通的にやっているものでないと、こうしなければいけないという関係ではございません。仮に外れたとしても、改めて共通な事業として各区で実施されるような関係になれば、そういう関係というふうに理解しているものです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、それによって、いっぱいもらえる、もらえないということになるのでしょうか。だから、こういうふうにばらばらな財調の金額になるのか尋ねました。","respondent":"本城企画財政課長","answer":"繰り返しになってしまうかもしれませんが、今基準財政需要額を説明しましたので、一方では基準財政収入額との差です。一番初めの説明でもちょっと触れさせていただきましたが、客観的な行政だとか、そういう性格のものです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"だったら、それで５５％ということで、こちらの政策をきちんとできるような一般財源は来ないのかというようなところをすごく感じてしまったのですね。大変だと思ったのですけど、今僕が言っているのは違っていますかとの意見を述べました。","respondent":"本城企画財政課長","answer":"先ほどの８ページの流れの中でご説明させていただきましたが、具体的に証明して、何区でこれだけのものをやっているとか。あれが一番公平と考えられているのと同じようなことで、細かいけれども、そういうふうな形の制度だと理解しています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２２９億円というのは、３６０億円になるのかは別として、冒頭から２２９億円という数字をどう捉えられているのかというのを教えていただきたい。そういう区側から見た４５％は取り過ぎだろうというような、一切見なくなったような気がするのだけど、そこら辺はどう捉えられているのか。","respondent":"本城企画財政課長","answer":"それから４５％、５５％のものですが、それはお互いに吟味しながらやるという仕切りだけは毎年度協議の場で確認し合っているという事実はあります。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう議論というのは、１年に１回でもそういうことを財調協議の中で持てないのですかというのを聞きたいのです。４５％に対するチェックを入れるという協議ができるのかどうかというのを教えてほしい。","respondent":"本城企画財政課長","answer":"大きい需要を見込んだり、そのもろもろの結果、再算定の残は基本的にはなくなるような形で全額交付されるような形になっているものです。各年度の協議の中で、本当に大きな改正があったかとか、少なくともきちんと議論していくことは必要なのではないかと考えているものです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"５５対４５は見直せよと、ある程度の意識をしっかり持っていないと、都側がそういう主張をしてくるのは見えているような気がしてならない。ちょっとそこら辺の区の考え方をちょっと教えてほしい。","respondent":"桑村企画部長","answer":"これも平成１８年に決着がついたと言っているわけですが、今の１５％以上に、はるかにやっているわけであります。これは毎年主張しているわけですが、余り４５％云々というのについては、得策ではないというのが今のところの考えではないかというふうに思います。","id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認をさせてください。この見直しという事業の項目というのは、これはどういう意味で見直しを図ってということでされているのか、その点だけ確認したいと思います。","respondent":"本城企画財政課長","answer":"ここは充実に対する見直し的な形で、額を下げている部分もあるという意味合いでこういう形でなっております。事業費の見直しなどのときには額を少なくする方向での見直し、結果として額が少なくなっているものを集めたものが１７項目あるというものです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"本来は特別区がやりたいのだけれども、国の流れで縮小せざるを得ないというようなものは、この中に入ってきているのですか。２３区の考え方というか、国との絡みがどういう形でこの見直しに入ってきてしまうのか、その辺はいかがか尋ねました。","respondent":"本城企画財政課長","answer":"計画は１７項目が挙がっていますが、既存のものをもっと縮小するとか、そういうものではないという形で表記しているものです。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"そうすると、実際は算定の、実際とずれが生じたので見直しを図ったものというのがこの１７項目という理解でよろしいのでしょうか。縮小という意味ではなくて、実際の算定、実績に合わせた形で見直しを図るという１７項目でよろしいのか尋ねました。","respondent":"本城企画財政課長","answer":"基本的にはそのような形で表記しているものです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"実際はこの右側のほうに自転車をとめている利用者が多いですから工夫の範囲というのはいろいろ必要なのかとは思いますけども、配置とか形とか。その辺を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今のご質問にお答えします。については、ほぼ今委員がおっしゃったとおり、内装改修の仕上げの改修なものですから、配置等については変更ございません。","id":"exchange-012"}]},{"id":"topic-02","title":"北品川三丁目外下水道管再構築および老朽化対策工事請負契約","agenda":"北品川三丁目外下水道管再構築および老朽化対策工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"辞退というのが３社ありますが、この経過はどういうことか尋ねました。","respondent":"立川経理課長","answer":"こちらはいわゆる申し込みをいただいた後に内部で検討した結果、また区で示した予定価格と事業者の見積もり金額が異なる、そういったことで辞退となったものです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"辞退というのは、会社側から取り下げるという意味でしょうか、その経緯をお願いします。","respondent":"立川経理課長","answer":"一度お申し込みいただいて、その後に工事設計書等を入手してもらいまして、そこで初めて工事内容について精査してもらうということになります。そういった意味で実際の札は入れなかったです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のにもかかわるのですけど、４社が申し込んで、３社が辞退だと、残り１社が落札となると、競争はどう働くのかという単純な疑問が湧くのですね。４社が申し込んで、３社が辞退だと競争にならないのではないかと疑問に思いますので、ご説明をいただきたい。","respondent":"立川経理課長","answer":"開札があるまでは公表されない内容ですので、実際開札した結果１社だけが入札していたということなので、いわゆる適正な競争入札が行われたです。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"確認","question":"一つ確認したいのは、次も１社だけど、不調を招く可能性が出てくる。今後もしこういうのが不調になったときにどうするのかというのを、これで見るとほとんど１００％だから、そこら辺のところを改めて説明を求めました。","respondent":"立川経理課長","answer":"１点目の予定価格の算出です。予算的にいわゆる調整がきくようでしたら、実際の入札予定価格を上げて再入札にする、そういったことをやっているところです。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこで、予算があるではないですか。１.２ぐらいにしてくれないとだめだみたいな話を聞くと、その１.２にするときに、どういうふうにされているのかというのを教えてほしい。","respondent":"本城企画財政課長","answer":"財源の確保の関係では、当初予算の執行状況を見て、財源として確保できるものがあれば、時期的なものを含めて流用として対応できるかどうか、それも検討した上で円滑な執行を目指していくというのが基本的な考えです。","id":"exchange-017"}]},{"id":"topic-03","title":"東品川三丁目付近下水道管耐震化工事請負契約","agenda":"東品川三丁目付近下水道管耐震化工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"東京都からの受託ということですけど、こういう下水道の工事を区が受託するというのは、どういう関係にあるのか。そこの仕組みを伺いたいというのと、あとは１６ページにイメージ図がありますけど、そこをご説明ほしいと求めました。","respondent":"立川経理課長","answer":"２点ご質問いただきました。２のいわゆる被害想定ですけれども、こちらにつきましては、いわゆる東京都のほうの被害想定で耐え得る工事内容というふうに聞いているところです。","id":"exchange-018"}]},{"id":"topic-04","title":"の順番では行政視察についてでありますが、本件では９月の上旬に予定しております視察のための事前の勉強会を行うことから…","agenda":"の順番では行政視察についてでありますが、本件では９月の上旬に予定しております視察のための事前の勉強会を行うことから…","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"もしわかれば教えてほしいのですけど、高知とかは誰からお話を聞くのですか、先方は。〔「高知は県庁で」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":41337,"voices":68}},{"id":"h26-20140826-14","meetingId":"h26-cm08","date":"2014年8月26日","dateIso":"2014-08-26","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時３２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"９月３０日までなのであと１月ちょっとぐらいしかない中で、福祉的な施設は、可能な施設というのはどういうものがあるのか。区の職員の住宅だけではなくて、情報が来て１月ぐらいたっているわけですから、ちょっとそのあたりのことを教えていただきたいというのが一つです。","respondent":"柏原行財政改革担当課長","answer":"それから、果たして公として何か使える建物があるのかどうかというのはなかなかちょっと検討段階では難しい部分があるのかと考えています。先ほどのインフラの活用検討チームが出した中では、出るか出ないかも含めて今検討していると聞いてありますので、その中で。","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"この品川第二寮のところのちょっと確認ですけれども、今までは宿舎として使っていたから、住宅として使っていっていた。ちょっとどういうふうに整理したらいいかちょっとわからないので、その辺、ちょっと。","respondent":"柏原行財政改革担当課長","answer":"すみません、ちょっと説明が粗かったようですけれども。容積率とかいろいろ考えながら建替えということになってくると思いますが、そういったものが関わってくるということで申し上げているところです。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"そういったところと地権者の協力を得てみたいな働きかけというのは今はどうなっているのでしょうか。これ、都営アパート、都と一体の敷地にしてしまうとかそういう話も全くないのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"一体で考えたというようなことも検討の俎上にはのせていますので、そこの部分にどう時間をかけられるかかけられないかというところがあります。ちょっと、まだ検討の最中ですので、いろいろな角度から検討をしているといった状況です。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"限られた時間ではありますけれども、ぜひここの可能性というのも探ってほしいと求めましたので、お考えを教えてください。幾らぐらいの見通しなのかというのがもし今の段階でわかれば教えていただきたいのと、それはぜひ避けなければいけないという意味で。","respondent":"柏原行財政改革担当課長","answer":"どういった手法がいいのかも含めて検討はさせていただきたいと思いますが、状況としてはかなり厳しいというのはちょっとあるというものです。その辺も踏まえながら検討といったところで、今見送る形でちょっとできないかというのがありますけれども、そういう状況です。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"区ではそこら辺の仕分けといいますか、精査は今後していかれるということなのでしょうか。ここに出ていないものもあるということだったと思いますが、それがどこどこかというのをもう一度説明を求めました。","respondent":"桑村企画部長、柏原行財政改革担当課長","answer":"１点は、私のほうから国有地のことだけご説明申し上げたいと思います。４ｍのあれで、例えば何かうまい手法がないかとかそういうことを少し検討させていただいて、また次回の委員会でご報告させていただければと思います。先ほどの東京都のこちらの検討チームのほうが出しているものが、場合によるとこういった物件から、そういったところも含みおきながらというものです。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"どういう話になっているかこの機会にちょっと伺っておきたいのと、ちょっとその辺のくくりがわからなかったので教えてほしいと求めました。２３区のほかの自治体も含めてこういうことを言っていくということもあるのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"だからこれ、所在地欄には「外１８筆」というふうに書いておりますけれども。東品川作業所というふうに東京都の名称的にはそう出てくるのでちょっと混乱しますが、事情を調べるとそういう状況というものです。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"先ほどの部長の話と３の「品川第二寮」の活用にもありますけれども、決して使い勝手のいい土地をどうぞということではないのが見えてくるのですよ。ですから、そのランニングコストも含めて、そんなことまで含めて土地の購入なり遊休地の活用を考えていかないといけないと思うのだけれども。","respondent":"桑村企画部長","answer":"一点あるのは、こういう先ほどから２,３００平米という土地を区内で求めるときになかなか民間と勝負できないというのも一方であるわけであります。ただ、先ほどの土地は、もう少し検討させていただきたいというのが今のところであります。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"冒頭、行革担当課長にこの資料が来るのが遅れたという話もあったではないですか。そのことはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"今まで各委員からの質問があって、事業を行うときに基本に返ると、費用対効果という問題が一番重要なキーワードになるのですけれども。質問をした部分を引き継いだ上で、費用と効果についてどのようにお考えになっているのか、端的に説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"費用の部分と、それからその物が建つかどうかというところを考えた場合には、それにかなう部分がどうかというのはかなり厳しい判断をするです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"民間同士、企業ならば隣の品川税経会館ですか、またどこかいいところに入れればということは当然頭の中にも入っているだろうし考えていると思う。別に質問ではなくて、それだけ伝えたかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"改めて２３区の状況を見る中で、これってどういう背景、理由があったのかちょっと確認させてというか教えてほしいと求めました。とりあえず、その２点をお願いします。","respondent":"立川経理課長","answer":"あくまでも平均ですので、当然９０％以上の案件ということもあります。仮に８０％という数字を最低とした場合に、これについては１年かけて慎重に検討していく必要があると考えて、本日に至っているところです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"とはいえ、会派の中でもちょっとその話が出ておりましたが、それも今後の課題としてこれまでの動きを見ながら検討してほしいと求めました。これ、改めてみると１,０００万円以上となっているのはごく少数派のようで、この数字についてはどのように区としては考えるのか尋ねました。","respondent":"立川経理課長","answer":"そうすると、予定価格を公表して、実際に該当するかどうかというのを見てもらっています。予定価格を公表することによって、予定価格の公表ということが、この１,０００万円以上というところにしています。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"１３０万円という数字が一つの例になってきていると思うので、そのあたりもこれから考えに入れて対応すべきでないかという思いがあります。約１年試行してもらっていい状況であるならば、そのあたりのお考えはいかがか尋ねました。","respondent":"立川経理課長","answer":"昨年試行という形で、建築土木に限って実施してきたところであります。その２点において、そういった各区の状況、国の動向等を勘案しながら適切に対応していきたいと考えている状況です。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今言ったように、１３０万円という一つの数字というものが目安になると思います。早い時期にそういった方針を立ててもらって、今でも１年ちょっとテストしてきたので、そのあたりをぜひ研究をしてみてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"もし出遅れているというふうに私もあえて指摘をさせていただきながら、早急に、前向きに取り組んでいただきたいと。電気部門の導入、それとこの低入札価格制度という、そこら辺の効率的な考え方を一言お願いできれば。","respondent":"立川経理課長","answer":"提出するほうも、また審査するほうも結構事務負担があるというところで、品川区ではこの制度についてはこれまで実施していなかったのですけれども。今後は、やはり併用している自治体も多いということなので、十分研究していくというような考えでいるところです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。メリット、引き続きといいますか早急に設定事業者の見直しと、あと他の２部門についての導入も見直しと早期に進めていただきたいと希望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"確認","question":"今、各会派からもいろいろありました。一点だけまず最初に確認したいのですけれども、そういうことをやっているのは２３区中品川区だけということでよろしいのか尋ねました。","respondent":"立川経理課長","answer":"そういった工事ですと、実際、その６掛けとか５掛けとかで入ってしまったりとかいうことがあるのですね。その辺のバランスを考えながら、案件によっては最低制限価格を適用しないという運用をしている自治体も幾つかあります。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"その中で品確法の改正の中で第２２条ですか、発注者の共通した指針をつくろうということが、これが法律の中に定められています。品川区は意見を上げられるのか、またそういう依頼が来ているのかどうか、確認させてください。","respondent":"立川経理課長","answer":"国は地方公共団体、学識経験者、民間事業者その他の関係者の意見を聞いて運用指針を定めるというふうに規定されております。道路課のほうに国交省の通知が来まして、そういったことで経理課としましても、実際に運用指針をつくる上で意見というのを国のほうに出しています。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"そういったものも定めていくというような考えも入っていると思いますので、ぜひそういったところは積極的に意見を言ってほしいと求めました。低価格調査ですか、そこの関係についてどのように区は考えられているのか、そこだけをお伺いしたいと思います。","respondent":"立川経理課長","answer":"それで今回品確法等でも最低制限価格の適切な運用というような様子で法律の中でうたっているところです。総合評価方式についても最低制限価格の運用についてどう絡めていくかというようなことは今後検討していきたいと考えているところであります。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"技術、評価点のところで余り差がつかないというところになった場合に、やはり価格というところが非常に大きなものになってくると思います。何度も言っていますけれども、効果的な総合評価方式の実施に向けて調査も、この研究もぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そこに仕事を回したら、作業員はどこから来るのですか、群馬から来ます、栃木から来ます、埼玉から来ます。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけれども、ここは今の委員会の趣旨からすると、委員間で議論をするという意味ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"改めてこれを品川区が今持っているものと、それから２つの基金、どれぐらいの運用益があったのかということについての確認。そうです」「そういうことです」「質問がありましたら、今要点だけ聞きましたけど、わかりますか。","respondent":"本城企画財政課長","answer":"水道、同じく一括して基金から支出することによって効率的に事務を進めていくという、設置趣旨としてはそのようなもので持っているものです。それに基本的には比例する形で６０万円と、片や決算で言うと１,１００万円という、そのような差が生じているものです。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"私たち自民党としてお伺いしたかったのは、例えば地球環境基金から見れば３０億円かな、３０億円です。それをどういうふうに品川区は運用する目的で公益を積んでいるのですかということをお伺いしたいと思って、そのことをぜひ答弁をお願いします。","respondent":"本城企画財政課長","answer":"それと、運用益がそれほど大きな額ではありませんが１４万６千円余ということで、そのような運用益という形で生じるものもあるというものです。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"このお金をどういうふうに、その目的はなんなのですかということです。その目的は何ですかということについて確認したいというのが私たちの求める答えなので、わかる範囲で結構ですから、答弁をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"私たちの意見の中では、それが行政目的にどう合致していくかということについても勉強すべきでないかということで質問させていただきましたけれども。同じように、これが奨学金はわかるけれども、ほかの基金についてもどうなのかということについて、この委員会で勉強していければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"そういうものをつくったらどうですかというようなお話もさせてもらっているので、これは前からこの委員会の中で整理をしたらどうですかと。にはこういう支援ができますよとか、私自身は今３つの基金をつくって、区の方針として出してもらったらどうだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"１０年単位のものを考えていっても、行政の中で目指したいものというのが少しずつ変わっていくと思いますので、ちょっと地球環境はどうだろう。ちょっと最後のところだけ、区の考え方をお伺いしたいのですけれども、いかがか尋ねました。","respondent":"本城企画財政課長","answer":"基本的な予定額を積みながら、最終的にどの程度税収とかもろもろの財源が出てきた、あるいは不用額がどれぐらい出てきたらという余力的なもので。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"逆にこの委員会のほかの委員の方々というのは、この点についてはどういう感覚をお持ちなのかと、逆に伺ってみたいところであります。もちろん、テーマを私が決めるわけではないのですが、お任せしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"目的を遂行するための目的達成のためのあらわれとして基金というものは出てくるわけですから、多い少ないというのは、余り議論の中心の論点としているのは私はいかがなものかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"あべ委員","kind":"意見","question":"だから、大切なものを全部基金にしてたら１００個でも２００個でも大切なものが区の中にたくさん出てくるので、どうしても増えると思うのです。多いほうが積極的に見えていいやというのもあるし、いや、数だといろいろあっていいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"南委員","kind":"提案","question":"お金の出どころが一般会計からか全部果実でやっているのかはちょっとそこを教えていただきたいと思っているのですが、今、何ていうのでしょうか。何ていうのでしょうか、そこはしっかり確認をしておきたいと思っていますけれども、ちょっとそこの点だけ見解を伺いたいと思いますとの意見を述べました。","respondent":"本城企画財政課長","answer":"どれだけ福祉とかもろもろのところに基金を役立てているかという、そのことを資料の上で改めてご確認いただければと思います。これからもいろいろな形で充実させていかなければいけないと考えています。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"必要な公共施設の建設に使うというところはそれはそれで受け止めてきているので、引き続きそういうことで大事に見守っていきたいと思っています。区民のために使うというところは、くどいですけれども、私たちもそういう立場で基金問題を捉えていく必要があるかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"名称でもいいから１つにして、いちいち使い道をどうのこうのではなくて、やはりそういう考え方が私は必要ではないかというふうに考えております。そういうことのほうが、本来私は品川区、地方自治体の基金のあり方としては最善ではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須藤委員","kind":"意見","question":"そんな基金、何もしないで一本化してしまってといったら、基金の意味も何もない。今の発言の中では、意見ですというけれども、それに対しては私は否という発言をしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"運用でそれはそれで利息だけ、果実だけ得るというのであったら、本来基金の考え方は私は逆におかしいのではないかと。だから、その辺をもっと総合的に考えて、基金のあり方を私はきちんと議論していく、皆さんで考えていくことは大事だと思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"松澤委員","kind":"提案","question":"せっかくこう自由討議をしてやりましょうというのですから、私たちの提案をこの場で議論していただいて、まだ半年以上ありますから。それぐらい議論していきたいと思うので、一つそういう議論の活性化と委員会運営、委員長の考え方をちょっとできたら話を聞かせていただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけど、この７２９億円だけ見るととても大きな金額だけれども、わずかな誤差でしかない。こういう見方も一部あるということも、４,５８２万円という評価は品川区はどう見ているのですかということ、これだけお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"確かに、２０年さかのぼったものと比較して、基金から生じる運用益としての収益が相対的に少なくなっている現実はあると思います。運用益の生ずる経済状況だとかを一方で見ながら、基金のあり方について改めて時代の変化とともに整理していく必要があると感じているところです。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これだけの原資が今あるわけですから、大きなこの行革のテーマだと私は思うので、それをぜひこれからの中で検討課題にしていっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"若林委員","kind":"提案","question":"有効活用するというのか、地域包括ケアなりの高齢化社会に対応した品川区らしい基金のあり方というのは提案をさせていただきたいと考えています。減価償却が進んで、そうするとだから公共施設の、これは質問ではなくて見方として言わせてほしいと求めました。","respondent":"本城企画財政課長","answer":"こちらの基金については、今委員ご指摘のように、果実運用型として設置されたところです。ちょっと先ほどとも関連しますが、そういう奨学金制度の変革の中でちょっと特殊な形のものに今なってしまっているというようなことです。","id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"それができないとなると、奨学金基金だけの話だけというのは独立してなかなかやりにくいと思っているのですけれども。即答されなくても構わないのですけれども、ちょっとそれについて正副にお任せしますのでとの意見を述べました。","respondent":"中塚委員長","answer":"よく検討させていただきたい。","id":"exchange-041"},{"speaker":"南委員","kind":"提案","question":"自民党から、議会としてこれから正副でこの問題をどういうふうに扱うかの提案があるのだろうと思いますけれども、しないのかも含めて。そういうことで取り扱っていただきたいというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":46845,"voices":94}},{"id":"h26-20140827-18","meetingId":"h26-cm08","date":"2014年8月27日","dateIso":"2014-08-27","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"ここの場において、オリンピック・パラリンピック推進特別委員会設置後、さまざまな議論があった。それが、私どもとしましては、もうこの原案のとおりでよろしいかと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これの受け取り方なんですが、この障害者スポーツというのはそういう方も含めたという解釈でよろしいかどうか、そこだけちょっと確認を。比較的重度の難聴者というのですか、障害者の位置づけというのを、確認も含めて明確にしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"最低でも現在と同じ規模、同じ面数を設置されたいということで強い要望が出されているということも聞いていますので、「ご尽力」というよりは。バリアフリー化を進めてほしいという要望・意見を出させていただいたんですが、この下のところに、ぜひそれを入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、１万２,０００人の方々をどこにどう収容できるのかというところは、明らかにされていないと思うんです。それとも安全対策はとるということがもう明らかになっているという認識なのか、そこら辺のところをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はやはり会場や会場周辺の津波や液状化などの安全対策というのは、項目としてもぜひ入れてほしいと求めました。そこのところが一体どうなっていたのということにならないためにも、私はこれは求めておくことがとても大事なことなのではないかと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"同じような形というか、向こうは実際に行うほうですから、そこの中で議論がちょうどされている部分というのもありますよね。進めていこうという時なので、今何で、この競技場の安全にかかわることを抜かすのかというのが私は理解できないんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう安全対策というのは、全ての会場で東京都がもちろんやらなければいけないことだろうという前提であるために、ここには個別の問題ということでは入れなかったんだという解釈ということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、この対策がどういう対策をとられるのかということを、東京都のほうにきちんと明らかにさせていく。そしてまたそこの時点で、それが十分でないということであれば、改めてこの委員会としても要望を出していくということで捉えてよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"必要であれば要望していくということであれば、私はここの前文のところには「安全で」という文言を、要望させてほしいと求めました。各競技でもということだったんですが、ここはたしか野球場６面がなくなるということなんですが、ほかの競技もなくなるものはあるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確保されるようにというところを議会として要望していくことにしたほうがいいのではないかと思うんですけれども、ということが１つです。４番の「潮風公園については」ということで、どういうことを要望されようとしているのかという中身について、ちょっと教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ議論もしてほしいといったことで要望してきましたので、私たちが要望しているのは、私は二本柱にしていただきたいという思いでずっと要望をしていたものなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"２番のところで、既存の施設、球技・競技の施設の代替施設の確保という意味だと思うんですね。私個人的にはこの文書をいただいて読んだときに感じたんですが、その辺の意味の確認を、この場で委員長のほうから教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"研修会について質問なんですけれども、例えばちょっとお話をしていただけるような機会があったらどうなのかなと思うんですけれども、その辺はいかがなものか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"その中身を聞いて、自分たちが指導する場面を想定して勉強していきたいというお話し合いのもとに、これが企画されたところなんです。もう話の中身では、私もそこには参加していましたけれども、そういうメダリストだとかアスリートを呼んでというお話もあったことはありました。","id":"exchange-013","title":"議員研修会の内容と所要時間"},{"speaker":"吉田委員","kind":"質問・要望","question":"どんなのかなとちょっと思ったものですから、金メダリスト等の方がお話ししてみたら、ちょっとそういうお話をさせていただきました。広げていただけるようなことがあれば、呼んでいただけたらどうかなと思いますので、その辺は要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば小学校３年生からというところが、どうしても習わせたいという方々もいらっしゃると思うんです。もしお答えできるのであれば、小学校３年生というのが何でこの学年で切ったのかというのを教えていただきたい。","respondent":"安藤文化スポーツ振興課長","answer":"第１・第３土曜日に学校があったりとか、ここに４５名と書いてありますけれども、実際には子どもたちが非常に少ないというのが今の現状です。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"あまり質問しすぎると個別案件に入っていってしまいますのでここでとどめておきますけれども、ぜひ幅広い年齢層の中でいろいろな取組みをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問といいますか要望になるんですけれども、ああ、そういうものなんだというようなことがありました。これから設けていくお考え、そのような形で、パラリンピックへの関心を持たせるような活動というのは何かとれないでしょうかというところです。","respondent":"安藤文化スポーツ振興課長","answer":"今、私も実際に平成２５年６月半ばだったと思いますけれども、平塚学園で講演会を地域の少年野球の方々がやっていただいたと。そういうものも、実際にこれから２０２０年までの間に、そういうお話を区民の方に聞かせるような機会を設けていきたいと考えています。","id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"これは定員というわけではなくて、参加したい方が全員参加できる状況なのか、そのあたりを説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"この中で、１番の障害者水泳だとか、２番の障害者スポーツ教室については、定員制を設けさせていただいています。必ず障害者７団体の代表の方、会長にはお話をさせていただいて、来ていただくようにご紹介しています。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"できるだけ多くの方が、こういったところの参加人数をさらに増やしていくということも、これから進めていく必要があるのではないかと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"障害者の方からこういう意見や要望を聞いて、そういう要望や何かを聞く方法は、具体的にもうちょっとお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で取り組まれたのが、実際には旗の台でスポレクの皆さんと地域で協力してつくり上げていったのが、この旗の台のものでもあるということです。ここら辺のところでいろいろ調査をしたり、７団体の方にもご協力をいただいた事実はあります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"いろいろな方の協力を求める体制は、障害者福祉課などとの連携もあるかもしれませんけれども、どのような形でとられているのか。文化スポーツ振興課だけで、今、やられているような現状なのか、その辺のことをちょっとお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、ここの３番、それから４番等で実際に指導していただいている人もスポーツ推進委員です。ここにボランティアと書いてありますけれども、これはスポーツ推進委員ではなくて、そうやって口コミで広まってきた団体です。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。支援体制、実施の手厚い体制というのを今後とも充実させていただけるように要望させていただいて、以上で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆に、品川区の中にある程度チームとしてやっているようなところというのは、何か区とつながりがあるんですか。そういうチームが逆に品川区に登録がされているのかどうか、その辺もちょっと教えてもらいたい。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、日立ソリューションズみたいな本当に頂点を極めているアスリートは別として、普段のものは私の耳には今のところ入ってございません。個々には、今、言ったグラウンドゴルフですとか、ボッチャも種目ですので、個人的にやっている人はいるということは確信しますけれども。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それから、今、見ていて気づいたんですけれども、知的障害者スポーツ教室というのは、これはスペシャルオリンピックス関係という感じなんですか。知的障害者のスポーツというのは。","respondent":"安藤文化スポーツ振興課長","answer":"ただ、３年ほど前ですけれども、品川区の総合体育館で、都のスペシャルオリンピックスをやった経緯はあると。そこにたまたま品川区の水泳教室にいた方が参加したという事実はあります。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何年か前、七、八年前かな、長野で１回冬のスケートなんかをやったのがあったんですね。何か品川区としてもその辺つながりがとれればそういうこともやっていってほしいと、その辺もつないでもらいたいと思いますが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そうですね。今後あらゆるチャンネルを我々も持ちまして、障害者スポーツの普及・啓発に努めていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これをもっと回数を増やしてほしいだとか、そういう要望はどうなのかをお聞かせいただきたいです。抽選に漏れるということもあるともお聞きしたんですけれども、その実態について、まずお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"それと、あと抽選の話なんですけれども、平成２６年度ですと、学生コースが８名落選、それから成人コースが３名落選しています。それから非常に指導体制を強固にして安全確保をしていくためには、やはりきちんと定員を守ってやっていこうというスタイルでやっているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区として、そういう民間での障害者の水泳教室も含めた障害者スポーツの民間の取組みといったところで把握しているものがあったら、ちょっと説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"水泳に限っても、民間のほうで障害者を対象に水泳教室をやっているだとか、どの程度本数があるかというのはつかんでございません。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ障害者のスポーツの全体を今後どういうふうに取り組んでいくかというところからすれば、ぜひ区としてもつかんでいただきたいと思っています。実は平成７年にということで、そして具体化をしていくというところも求められているかなと思うんですが、そこのところではいかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"今で言えば地域の総合型スポーツクラブですけれども、それが当時はスポレクと言って、これをずっと継続して設置して発展してきました。まず区が水泳教室をやるにしても、やっと今、１７回で非常にいい形で定着をしていっているところです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せっかくこのスポーツ振興ビジョンという形でつくられているわけですから、今の時点で、方針・ビジョンを掲げてぜひ取り組んでいただきたい。これは要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"意見","question":"何が言いたいかというと、逆に紹介しないでいいよと言いたい。出席していただいた方に、これだけ長い時間紹介したってしようがないと自分はそう思っているもので、その辺よく考えておいてもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えば福祉施設だとか何かのオープニングがあっても、そんなにこだわっていないというと変だけれども、行くのは行きます。だけど、統一していない意見なので、ちょっとそこら辺だけ頭に入れておいていただきたいと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/882053?Template=document&Id=6460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28574,"voices":75}},{"id":"h26-20140916-6","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"区民委員会","time":"午後１時００分～午後４時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2867,"voices":11}},{"id":"h26-20140916-7","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"厚生委員会","time":"午後１時００分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"の品川児童学園の改築","agenda":"の品川児童学園の改築","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"もしくは、ワンストップで最後まで対応していく体制をつくるべきと思うのですが、いかがでしょうかということが１点。行政はどう対応していくのかということが、立派なものをつくっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"それから２点目の、ダウン症の特性を理解した支援というところでは、この間いただいております。そういった専門相談を活用しながら、一人ひとりの子どもの特性に合わせた成長を支える支援の仕組みを、ここでつくっていきたいと考えています。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"いろいろなケースに応じて具体的な対応をしていくべきと思うのですが、いかがでしょうか、ということがまず一つ。障害児に限って言えば、その子どもの将来にとってはプラスになると思うのですけれども、お考えはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"その計画相談と支援ノート、保護者のご了解をいただきながら、個人情報を継続していくかということも一つ大きな課題ではあります。療育支援ネットワークは、このまま継続して行っていきますので、いただいた北海道千歳市のモデルなども参考にさせていただきたいと考えています。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"だけれども、それを行政がどうサポート、バックアップしていくのか。いろいろな観点で物事を見つめていっていただいて、中身は充実したものをつくっていただきますようにお願いします、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"何点か伺いたいと思います。これで２階のところの就労継続支援Ａとあるので、いわゆる就労継続のＡ型と捉えていいのかどうか、それを説明を求めました。","respondent":"中山障害者福祉課長","answer":"それから、(2)の高齢化・重度化に対応した支援というところでの年齢、逆に１８歳以上の方であればどなたでもということになってまいります。就労継続支援のＡ型というのはかなり難しくなってきますので、Ａでも、Ｂでもと考えていく予定です。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あらゆる対象となっているものは２のほうの相談支援センター・訪問系サービス、それからショートステイはどうなのか、もう１回教えていただきたい。それから、ショートステイを利用した体験型グループホームとありますけれども、どんな感じのイメージか教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"いろいろな講座への参加ということが難しいようであれば、やはりたいむのほうの機能で行っていくことがいい支援につながるのかと考えております。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"非常にいいことだと思います。どうしてもここと切り離されてしまうような形になると思うので、またその辺は動きがありましたら、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"４．運営方法のところで、直営に戻してほしいという声を、今伺っています。それを知ったうえでどうお考えか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"なかなか現実的に難しいところもありますし、支援の中身というところで、法人の人材の活用ということも必要になってくると考えています。福祉職場として、今回のこの施設につきましては、指定管理者制度によって運営をしていきたいと考えているところです。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"これは要望です。計画支援員をつける仕組みはないような話に聞こえたのですけれども、子どもには、計画を策定する支援員はいないのか尋ねました。","respondent":"中山障害者福祉課長","answer":"近隣のところで、セルフプランということで、保護者が自分の子どものためにつくっているプランを計画相談に位置づけているケースが多いのが現状です。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"全国的にあると思うのですけれども、先ほどもほかの委員からありましたけれども、追いついていかないのではないかと思うのです。そこに合わせて支援員をさらに増やしていくためには、どう考えているのか、もう一度お聞きしたいです。","respondent":"中山障害者福祉課長","answer":"戸越ルームの運営を進める中で、相談が１カ月半から２カ月待ちというところまで、何とかきたところです。研修なども行いながら、支援力を高めて、その計画相談に着手できるような準備を進めてまいりたいと考えております。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"子どももそうですし、大人の部分も、今まだ足りないという状況なので、本当に足りないと思っているので、ここをスピードアップさせて、一人ひとりに本当にその人に合った計画がしっかり立てられるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"とても大きな建物ができ上がるので、かなり皆さん期待をしているのではないかと思うのですが、その辺を教えていただきたいということ。その三つを説明を求めました。","respondent":"中山障害者福祉課長","answer":"例えば週５日生活介護に通うという生活に頼らないで、そういったことも合わせてやっていかないと、やはり緊急時の対応は難しいと考えております。","id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"こみゅにてぃぷらざに関しては、単独ではない分だけ、本当にいろいろなご苦労があるかと思いますけれども、その辺は上手にやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"２点ほどお願いしたいのですが、あそこが足りないときに、ここは使えるのかどうかということが一つ。障害者サービスよりも介護保険のほうを優先させるということは変わらないのかどうか、どういうことがあるのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"そうではなく、例えば胃ろうの子どもなどについて対応していただきたいとは思っているところなのですが、ここはやはり支援力と関わってきますので。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、新しく平成２６年度に生まれた子どもに、そういうことが引き継がれていない。より有効的に活用されて、障害をお持ちの子どもを抱えるご家庭にもプラスになっていくと思うのですけれども、お考えはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"こちらから発信しているつもりでも、実は当事者の皆さんには情報が十分に伝わっていない状況だったということを反省しています。どういった形で障害児をお持ちの親御さんへの情報提供をしていくかというところについては、今後の課題とさせていただければと考えています。","id":"exchange-014"}]},{"id":"topic-02","title":"の水痘、高齢者肺炎球菌ワクチンの定期予防接種化","agenda":"の水痘、高齢者肺炎球菌ワクチンの定期予防接種化","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"今までの品川区で行っていた助成３,０００円というのがありますが、そういう対象になるのかどうかということを、教えていただきたい。１月から３月の対象外の方云々とおっしゃっていましたが、一応６５歳の人と見なして、自己負担４,０００円で受けられるということなのか尋ねました。","respondent":"佐藤保健予防課長","answer":"最後の、１月から３月の方ですが、これは本当に今回特出しということで、従来のご説明で待っていただいた方がありますので、特別な対応としています。任意予防接種と定期予防接種の違いは、金額のこともありますが、副反応における対応の仕方も違ってまいります。","id":"exchange-015"},{"speaker":"山元委員","kind":"質問","question":"一応２３区統一というお話がありました。自己負担４,０００円で受けるということで、これもやはり２３区統一というか、各区もそういう対応をしているのか尋ねました。","respondent":"佐藤保健予防課長","answer":"実際には、まだ１０月の制度なので、はっきりは聞いておりませんが、一部任意予防接種を残すという話も、区の課長会の中では聞いておりますが、多くの区は、定期予防接種になりますので、国の制度で５年ずつ接種するというような形で実施されると聞いております。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この間、いろいろ医師会の人などからお話を伺うと、やはり５年くらいワクチンの効果があると。国は定期接種なので１回となっていますけれども、どういうお答えをしていくのかと思うのですけれども、その点を説明を求めました。","respondent":"佐藤保健予防課長","answer":"それから流通の状況などを見ながら、その後の任意予防接種につきましては、情報収集しながら研究していくような課題かと認識しております。この５年間をかけて、２回目接種についても、私どもも研究をしてまいりたいと考えております。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今回始まるというところでは、６６歳とか、これから打ちたいと思っている方は、希望者は接種できるようにしたらいいのではないかと思いました。この間、平成２５年度でもいいのですけれども、接種を受けた方というのは、どれくらいいらっしゃるかわかりますかとの意見を述べました。","respondent":"佐藤保健予防課長","answer":"５歳刻みに関しましては、本当に薬剤が足りなくなってしまうこともあろうと思いますので、このような形をとられたのかと考えています。実施ですけれども、平成２５年度２,２３８件というのが、１年間の実績です。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"流通量とか、ワクチンには量があるからということも、そうなのでしょうけれども、定期にしたところで、どれくらい増えるかというところはあると思うのですけれども、そんなに足りないもののですか、ワクチンというのは。","respondent":"佐藤保健予防課長","answer":"全体の流通量と生産量については、私どもも詳しくは聞いておりません。５年間分だけ、また生産ラインを下げることになりますと、なかなか一気に全員の方が打つような生産量を確保するのは難しいのではないかと考えます。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これはニューモバックスという２３価のワクチンで、１回もやっていない人に、インフルエンザとの同時接種のお勧めはされるのでしょうか。それから第４点目として、プレベナー１３という１３価の肺炎球菌ワクチンが、それの位置づけはどうなっているのか尋ねました。","respondent":"佐藤保健予防課長","answer":"その中で特別、５歳に近い方につきましては、任意予防接種の方もご通知しながら、個別にお知らせをする予定にしております。４番目、今回、適用になっているワクチンはニューモバックスのみということになっております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それから３番目ですけれども、こういうこともできますよというお知らせはするのですか、ということを聞いているのです。１３価のプレベナー１３が承認はされたわけですから、今後、ストラテジーの中でどうやって位置づけていくかということを聞いているのです。","respondent":"佐藤保健予防課長","answer":"同時接種につきましては、特段こちらとしてお知らせを配るというような予定はございません。定期予防接種に準ずるものと考えておりますので、今回につきましては、医師会にもニューモバックスでお願いしたいと考えております。","id":"exchange-021"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"2)以降は、わざわざ2)まで点線で囲っているのをどう見たらいいのか、もしわかれば。どうしても少し保険料が上がってくるようなイメージが、どうしても先行してしまうのですけれども、もう少し具体的に教えていただけばと思います。","respondent":"永尾高齢者福祉課長","answer":"申し訳ありません、説明しなかったのですけれども、この点線は、区のほうで振った点線です。この地域支援事業の費用をどのくらいにするかというところをにらみながら、今、第６期に向けて検証しています。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問","question":"いろいろなボランティアみたいな支え手を、そちらのほうにシフトしていくようなイメージの中で、その辺は軽減を図るというイメージでいいのか。平成２７年４月に向けてこれをやっていく中で、いつくらいをスケジュール的には目指していらっしゃるのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"９月以降に、訪問介護事業所連絡会、通所介護事業所連絡会、居宅支援事業所連絡会と、９月から１０月にかけて行っていく予定になっています。１０月３０日には、介護保険の事業計画の策定委員会が予定されております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"確認","question":"国が介護保険制度という基盤の中で、その制度の中で何か考えなさいということがあったと思うのですけれども、その確認。そうなれば、これから新しいサービスを提供しているわけですから、財源の手当は何かつくのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"急増する高齢者に対応するということですけれども、今回、この改正が出てきているところです。今のままのサービスを継続していくと、大体５％から６％自然増加が予測されております。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"事業数が増えていくわけですから、保険料をどう反映していくのかということについては、非常に関心があります。Ｃと、それから生活支援サービスの内容を、かいつまんでで結構ですから教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"こちらは、要支援者と非該当者を対象にして、基本チェックリストで基本チェックを実施したうえで、訪問介護を行っております。ただ、地域支援員がまだ充足されていないということもありますので、もう少し工夫をしながらつなげていったらどうかという見込みを立てています。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"確認","question":"品川区が罰を受けるわけでも何でもないでしょうから、そういう方向で考えていくべきではないかと思うのですが、いかがでしょうか。そうすれば、いわゆる介護保険料の改正も少なくて済む可能性があると思うのですが、いかがでしょうか、答えるよう求めました。","respondent":"永尾高齢者福祉課長","answer":"私も、実は委員と同じように考えておりまして、赤い点線のところは、やはり平成２７年度から変えていこうかと思っています。そのあたりを、来年度調整をしながら、国の方針に合うような形にもっていきたいと考えているところです。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから、一時的にずっと高齢者が増えていくわけですから、サービスの提供自体は増加する一方である。どうしてもやはり地域に人材を求めていかないと、全ての福祉施策が支え切れない時代が必ず来ると、私たちは思っているのです。","respondent":"永尾高齢者福祉課長","answer":"信用金庫の見守りというところで、研修等も開きながら、地域での見守りという意識改革に取り組んでいるところです。この制度への対応をしていき、最終的にはやはり区民の方々が安心して住めるところを目標としていきたいと思いますので、よろしくお願いいたします。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"平成２７年度に移行させていくというのは、先ほどほかの委員からもありましたけれども、なかなか大変なことですよね、大きく変えていく問題ですから。それに踏み出す自治体というのは、２３区で見て、どれくらいあるのか、わかりますか。","respondent":"永尾高齢者福祉課長","answer":"ただ、検討しているところは２区くらいあるように聞いているところです。今また調査がきているところですので、この後どういうふうになるかというのは、今のところわからない状況です。","id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川区のみと、それで検討されている区が２区と、何でなかなかほかの区は移行していかないのか。そして、何で品川区は、たった１区ですけれども、移行していこうと思ったのか、お伺いしたい。","respondent":"永尾高齢者福祉課長","answer":"在宅介護支援センターの仕組みが、先ほど少しお話ししました生活機能向上支援事業というのも、平成２４年度から始めているというところ。実際にこれを１年早くやれば、それによって、逆に介護保険料のほうは多少安くなると見込んでおります。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、品川区の介護保険の中に、全く同じ名前の介護予防・日常生活支援総合事業の利用の流れというのはもう書いてあるのですけれども、ではここにほとんど入ってくる、ここの以外の新たなものというのは、この表でいうとどこになるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、確実に考えているのは、予防給付の訪問介護と通所介護を全部地域支援事業に移すということは、確実にやろうと考えています。生活機能向上支援訪問事業は、生活機能向上支援訪問事業でも大丈夫な方は、こちらの事業のほうに流すというような形をとろうと思っているところです。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"前もって、右側の１．既存の介護保険指定事業所が現在の利用者に対しサービスが継続されるよう調整する、ＮＰＯなりになるかという状況になるのか。それとも、今までどおり、専門家によるサービスになっていくのかは、どうか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"1)訪問介護、2)訪問型サービスＡ、両方とも、一応資格を持っている方が対象になると思います。今はまだ事業者とも検討している最中ですので、まだ確定したことは言えませんけれども、そういう方針でいこうかと考えています。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、区としては、どういったものがボランティアなり、ＮＰＯなりになっていくものかと見立てていらっしゃるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ただ、住民主体による支援というのを、この後、検討していくのですけれども、これにつきましては、ボランティアという形になるかと思います。利用料とか時間数とか、ご利用者が自分の望みとして、どういうものを望むのかという選択ができるような形をとれたらと考えています。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"運営していけるかどうか、やはり介護保険給付の中でやられている訪問介護と通所介護から見ると、とても安いのですよね。事業者は、本当にやっていけないという不安の声がもう今から出ているのですけれども、そういったところにはどのように応えていくのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ここで要支援のときに対応している事業者と利用者の関係は、事業者のほうも、そういうお話をしておりました。そのあたりは、不安にならないように、区のほうとしても、説明をきちんとしていかなければいけないと思っています。","id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"どうしても、仕組み上、あるのではないかと思うのです。そこら辺があっても、対応していけるというものがあるのでしょうか、品川区独自で。","respondent":"永尾高齢者福祉課長","answer":"事業所がヘルパーという貴重な人材を使っているわけですので、今度それを介護給付のほうに振り向けるような事業所内での努力も必要かと思っています。約３％ということであれば、現在の事業者自体は、お客様がいなくなるということはないのかと思います。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この間、各施設を回っていろいろ実態も聞いてきたのですけれども、どこもやはり人材確保が本当に難しいと。高齢者は増えていくわけですから、国に求めていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"人材確保は、非常に重要な問題として、国のほうも検討はしているところであるかと思います。各社会福祉法人の職場環境の部分についても、区のほうで、いろいろな助言指導等をやっていきたいと考えているところです。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういうほうに流れてくるにあたって、同じ予算内でやるのか、もちろん上がっていくのでしょうか。それがどれくらいで、進めていこうとしているのか。","respondent":"永尾高齢者福祉課長","answer":"手元ですぐに出たのが古くなってしまっているのですけれども、平成２４年度の決算額が１,３６７万８,２２７円になっています。検討している段階で、予算要求等はこれからという段階ですので、この制度改正のこともにらみながら考えていきたいと考えています。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ本当に、専門職のサービスを低下させない方向で、利用者が安心して受けられるようにしていただきたい。これを、本当にこういった不安にもしっかり応えていっていただきたいですし、しっかりとした説明をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１日で下がる人と、３日から４日くらい高熱がつづく人がいるのですが、デング熱ではないでしょうかという質問がたびたびあるのです。今、血小板が３日目から４日目に減るとかという報告があるのですけれども、保健予防課としてはどのようにしたらいいとお考えなのか尋ねました。","respondent":"佐藤保健予防課長","answer":"区も東京都と連携をして対応をとっておりまして、現在の対応ですが、地域のほうは設定されております。かなり疑わしい症例であった場合には、代々木公園周辺に限らず、東京都のほうは検査を受けることにしております。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、血小板が少ないという症状を疑うような出血斑だとか何かがあった場合は、保健所へ連絡すればいいということなのですか。例えば、具体的に熱が何日間か続いて、患者からデング熱が心配だと言われた場合は、保健所としてはどのように対応したらいいとお考えなのか尋ねました。","respondent":"佐藤保健予防課長","answer":"したがいまして、全ての患者がデング熱であるかないかということを、簡単な症状だけで診断することはできないかと考えています。３６度８分ですとか、個別の症例で個別の対応をしますが、デング熱であるかどうかも診断できないままに終わってしまうかと思います。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363412?Template=document&Id=3396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":43060,"voices":107}},{"id":"h26-20140916-8","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"建設委員会","time":"午後１時００分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"の２「報告事項」を聴取いたします。 初めに、(1)の広町一丁目周辺地区地区計画","agenda":"の２「報告事項」を聴取いたします。 初めに、(1)の広町一丁目周辺地区地区計画","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"広町一丁目周辺地区地区計画区域、１７.２haとなっていますけれども、今回の提案はＣ地区のことですね。変化をしているところがどういうところなのか教えていただきたいのと、あと、自分たちの地域ではなくて第一三共のところのＡ地区の話ではないかとの意見を述べました。","respondent":"溝口都市開発課長","answer":"これまでの周知の関係ですが、Ｃ地区につきましてはこれまで説明会をするときも当然、地区外権利者には郵送で。まちづくり説明会、または都市計画法に基づく説明会をやっていきますので、また戸別訪問する際にもただポスティングするだけではなく。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"ポスティングだけではなくて対話もということですけれども、あまりはっきり中身が伝わっていないのがお話の中でうかがえたのです。権利者の数とか別々に教えてほしいのですけれども、その辺の割合ですか、用途の割合がわかったら説明を求めました。","respondent":"溝口都市開発課長","answer":"土地建物所有者が３９名、建物所有者が１名ですから、あくまでも都市計画法上権利者と言われるのは４０名の方がおります。そのうち、それ以外は戸建て住宅としては住宅で使っているのが１２軒、集合住宅としては１軒あるような形の土地利用になっているものです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"この図からなかなかわかりにくいのですけれども、ここはほとんど日本ペイントの工場、建物と考えていいのですか。共同住宅とかがあるのか、ないのか。","respondent":"溝口都市開発課長","answer":"この図でいきますと２枚目のＡ３の「地区現況」という図を見ていただければ一番わかると思うのですが、こちらに１本、目黒川を渡る通りがあります。そこまでは区域に挟んでいませんので、あくまでも日本ペイントの工場の敷地を対象に今回、地区計画を定めるものです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"確認","question":"ということは、Ｃ地区のところだけ広い部分の中に先ほどあった住宅７とか、戸建て住宅１２軒とか、集合が１軒ということで理解はよろしいですね。そこを確認したいのと、新しい地区の整備計画の中でどう変わっていくのか、どう守られていくのかというあたりを具体的に説明を求めました。","respondent":"溝口都市開発課長","answer":"事前に、地区計画をかけるに当たってこれは不適格になりますので、今後同じようなものができないような形になります。今後建て替える際には寄宿舎ではなく別の用途として、今回の地区計画の用途に合った形での土地用途転換を図るということでお話を聞いているものです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"前にも伺ったかもしれないですが、５月５日にも説明会がありましたけれども、ここでどのような意見が出されていたのかお知らせください。","respondent":"溝口都市開発課長","answer":"都市計画原案の説明会につきましては、合計１０名の方が参加しておりまして、Ｃ地区に対する質疑というのはありませんでした。この間、いずれの回につきましても、全て今回お配りした資料と同様なものを使いまして説明をし、内容についてはご理解いただいていると考えています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会３回をやったので終了ということではなく、これから公告、きちんとお伝えする方法を考えていただきたいのですけれどもいかがでしょうか。来ない人には伝わらないというのでは困ると思うのですけれども。","respondent":"溝口都市開発課長","answer":"これまでもまちづくり説明会または１６条の説明会、いずれも戸別にうちの職員が訪問して、改めて説明していくというつもりはありません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど土地、建物３９名地権者の方、建物１名で４０軒ということですが、では、４０軒の方、全てにきちんと伝わっているという理解でよろしいのか尋ねました。","respondent":"溝口都市開発課長","answer":"地区外に住まわれている方もいますのでその人たちには説明会の資料を事前に郵送して、地区内に住まわれている方については全てお会いしてご説明しておりますので、しっかりご理解いただけていると理解しております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"事実そう、そういう方が私はないとは言い切れないと思うのですが、今後の予定の中で不十分さを補っていく手だてがあるのかどうか。公告、縦覧と、あと広報があると思うのですけれども、どのようにされていくのか説明を求めました。","respondent":"溝口都市開発課長","answer":"今後行われます９月１９日からの公告、縦覧につきましては広報紙に掲載しております。改めて、これまで十分、改めて説明会等の開催というのとは考えておりません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にします。広報紙、９月１９日に公告、縦覧が始まるのですが、いつの広報か教えていただきたいのと、記事の大きさがどの程度か説明を求めました。","respondent":"溝口都市開発課長","answer":"都市計画のほうで一括でやって、たしか９月１１日か１日の広報には、事前には必ず周知しております。広報記事については、当然紙面の関係もありますし、お知らせ記事なのでそんなに大きくはとっていないとは思いますが、１日に載せていると思います。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見をきちんと聞くという姿勢をいつでも、どこでも持っていただきたいのです。ぜひそういうところも今後に活かしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"制限を希望するというのは区ということなのですか、工場というか企業の皆さんからそういう要望があったのか、そういうことなのか。都市計画はそういうものだよということなのかもしれませんけれども、そこら辺をご説明ほしいと求めました。","respondent":"溝口都市開発課長","answer":"そういった考えを持って地元の意見を聞く中で、住宅、品川区と地元の方が一体となって今回の定めという形になっております。工場を操業していくことへの影響を防ぐという観点から、二つの理由があって、この地区計画を定めたというのが現状です。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"Ｃ地区に関しては４０軒の権利を持っている方たちがいて、共同住宅化へのアプローチ的なものが何か話としてあったのかどうか、その辺について教えていただけますか尋ねました。","respondent":"溝口都市開発課長","answer":"ただ、１番は、ＪＲの敷地が線路沿いに広くあります。その辺が売られるのではないかといった話が危惧されて、実情としては特にそういった動きが目立ってあったというわけではありません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特に具体的な動きがあって、都市計画という話ではないということはわかりました。地権者の方は権利が制限されることになると思いますので、そこのところの説明についてはまたしっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の大崎駅西口地区および周辺地域におけるまちづくり","agenda":"の大崎駅西口地区および周辺地域におけるまちづくり","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"都市再生緊急整備地域のエリアの面積をお知らせいただきたいのと、大崎三丁目地区と大崎西口駅前地区の進捗状況、今どういう状態にあるのか。もう少し詳しく教えていただきたいのと、新たに広がっている地域の地権者、組合員数を改めてそれぞれの地域で説明を求めました。","respondent":"溝口都市開発課長","answer":"そういったものを協議していく中、今回、８月末になりますが市街地再開発準備組合が設立されているという状況です。ですから、大体７割ぐらいの建物の方たちが準備組合の取り組みに賛同されて、組合に参加しているという状況です。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"Ａ３判の一方通行ですが、前伺ったときは十分、その辺はどう返していくのかなというところが一つ。百反歩道橋のかけかえのところで一つわからないのが、「ＪＲ東日本への委託」と書いてあるのですが、これはどういうことなのか説明を求めました。","respondent":"稲田道路課長、溝口都市開発課長","answer":"私から百反ずい道の豪雨対策ですけれども、あそこにポンプの設備を設置しておりまして、水がたまってくればそこで強制的に排水をしていくです。冠水の警報装置等もついておりますので… ただ、歩行者の安全性とか、そういったものを確保していくのだというご説明をして、ご理解いただいているものだと感じているものです。","id":"exchange-015"},{"speaker":"原委員","kind":"意見","question":"少し鈍っているというような話が入ってくるのですけれども、もう一回詳しく、全体的な動きで結構なのでご説明ほしいと求めました。","respondent":"溝口都市開発課長","answer":"大崎西口駅前地区につきましては、大崎ビルは昭和３３年に建設されて、それ以来ずっと今まで来ている。地域の方たちが今まさに今後それに向けて地区内の方含めていろいろ協議しながら進めていくものと考えているところです。","id":"exchange-016"},{"speaker":"原委員","kind":"意見","question":"大崎三丁目地区は８９％ということですけれども、組合が立ち上がったばかりですので今後どうなるかわからないけれども、この辺に対する対応。具体的に出ていなければそれでいいのですけれども、お教えほしいと求めました。","respondent":"溝口都市開発課長","answer":"ですから、今後、都市計画を経て組合設立、経年変化といった中で順次加入率というか、合意率は上がってくるものだと考えているものです。今後マンション、今は１棟一つで考えていますが、その中を十分説明しながら今後進めていきたいと準備組合からは聞いているものです。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"展開をしている形があるものですから、その辺のところも十分に配慮をお願いしたいなということで、これはお願い事項にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これをどう捉えたらいいのかというところにおいては、その辺を、どこまで拡大するのかというのは地域の住民の方からしたら大変な脅威なわけです。その辺の考え方をひとつ教えていただきたいのと、電気を使う場合の停電の対策とかはきちんととられているのかどうか、その辺も聞かせてください。","respondent":"溝口都市開発課長、稲田道路課長","answer":"大崎駅周辺都市再生緊急整備地域に基づいてこれまで進めてきていると。やみくもに広げていくという考えはありませんが、今回、まちづくりについてはしっかり考えていきたいと考えているものです。 要するに警報装置の部分におきましては停電になりましても約１０分間無停電装置が働きまして、ＬＥＤの警報表示や回転灯が作動、それから放送案内灯が使えるように二重の手当てをしております。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"突っ込んでしまった場合はどうにもならないということですか。そういうさらなる開発はやめてほしいという声はどうしたらいいのか尋ねました。","respondent":"溝口都市開発課長、稲田道路課長","answer":"ただ、そういったところまでを再開発事業を使ってまちづくりを行っていくという考えはございません。あくまでも一つは、そういった拠点を中心に、市街地再開発事業を使ったまちづくりを進めていくと考えているものです。警報等が鳴りますと４階の災害対策危機室、それから夜間休日等においては２階の夜間警備室に電気信号で届くようになっております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"開発によって地域を追われる方がいるというのは事実なので、ぜひその辺も十分考えて、地域を決めたのだったら勝手に広げないでいただきたい。言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"の中央新幹線（東京都・名古屋市間）環境影響評価書の縦覧・閲覧","agenda":"の中央新幹線（東京都・名古屋市間）環境影響評価書の縦覧・閲覧","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明いただいたのですけれども、環境影響評価書のあらましについての品川区の見解というのはあるのでしょうか。あったらお聞かせいただきたいです。","respondent":"三ツ橋環境課長","answer":"環境影響評価のあらましについての品川区の意見ですが、この全体の準備書について意見を出しております。したがいまして、あらましについての意見集約というのは特に法律上規定がございませんので、そちらについては評価書が出されたです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"準備書に対する区の意見を聞かせていただきたいのと、見直しを求めている声が相次いで、テレビでも取り上げられている。いけないと思うのですが、すみません、前段の準備書についての意見を改めてお聞きしたいと思います。","respondent":"三ツ橋環境課長","answer":"東京都に回答を送りました意見の中では、微気圧波等々、全般にわたって区長意見として出しております。しかしながら、東京都がまとめた意見を準備書に対しては出しておりますので、区としては東京都に回答しております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"こういった指摘をもちろんご存じだと思うのですが、品川区はこの点をどう受けとめていらっしゃるのでしょうか。もう一点は、品川に与える影響をどう考えているのか、説明を求めました。","respondent":"三ツ橋環境課長","answer":"リニアについては電力消費はあると思いますけれども、自動車を使うＣＯ２の削減と比較しますと大分ＣＯ２は削減されていると考えております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後の異論はありませんというところで、一緒に進めていくということですけれども、品川区は北品川のところに非常口ができますね。東京ドームの５０杯分もあると言われている残土がどこになるのかとか、４０ｍ地下を、その点を教えていただきたいのですけれども。","respondent":"三ツ橋環境課長","answer":"「なお、「調査および影響検討内容を変更する場合があります」と書かれていますので、そちらと考えています。関係自治体および地域住民の方へ公表していくということですので、そちらに関しても対応してまいります。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"活断層のところは、私はこういった計画は中止すべきだし、自治体としても自治体の立場で物が言える自治体になっていただきたいと思っています。区議会もそうですけれども、意見を述べないままに進んでいくことに対して懸念を感じているのですが、この点に関してはいかがか尋ねました。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"意見については準備書の段階で申し上げておりますので、その段階では区長または東京都の意見というものは述べております。先ほど環境課長から冒頭でも説明させていただきましたとおり、国土交通大臣がＪＲ東海に営業主体および建設主体を指名するという形の制度です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"終わりますけれども、自治体からも異論ややり直しを求めるような声が出ているところもあるので、ぜひ、今後のことも、工事の問題とか具体的になっていくことでさまざま問題が出てくると思うので、しっかりと物が言える自治体であってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"の区独自環境マネジメントシステムの概要と試行運用の開始","agenda":"の区独自環境マネジメントシステムの概要と試行運用の開始","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"そのときは委員ではなかったので、もしかしたらそのときに質問が出ているかもしれませんがお聞かせください。そのことについてお伺いしたいのですが、ＩＳＯを返上することについて伺いたいのですが、そこのところを説明を求めました。","respondent":"三ツ橋環境課長","answer":"今までＩＳＯ運用を実施していた大もと、昔に認証を取得して今現在のところＩＳＯ１４００１を継続しているところは３区しか残っておりません。そのほかは全て返上したという状況です。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"事務的な手続の事務料というのですか、ＩＳＯを保持していることの意義についてというところでそこが論点になっていたものですから、それを説明を求めました。","respondent":"三ツ橋環境課長","answer":"引き続き、事務の煩雑さという部分で、変更点の２番目にありますＥＭＳにかかる事務手続のスリム化。大分事務がスリム化されているです。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"意見","question":"今の点については妥当だとは思いますけれども、ここに書かれているとおり後退しているというような印象にならないように、また今後拡充に向けてしっかり庁内の調整をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"原委員","kind":"意見","question":"節約というか節税というか、どのぐらいを想定しているのか、その辺について。今も数値の問題が出たのですけれども、もう一回お考えをほしいと求めました。","respondent":"三ツ橋環境課長","answer":"節税の部分に関しては、外部審査の部分が大きいと考えておりまして、３年ごとの更新の１３０万円については、外部審査を受けないということで、その部分は節税になっております。","id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"非常に明快なご答弁ありがとうあります。ですから、広報だけではなくて啓蒙とかもお願いしたいので、その辺のアイデアがもしあれば動いてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"Ａ３の資料の赤枠の中の「ＥＭＳ運用状況の情報開示」ということで、区民への説明のあり方となっていて、赤文字のところで内部監査の報告書を原文でホームページ公開するということと、省エネ等の実績値を広報等へ掲載するということを考えております。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問・要望","question":"ＩＳＯ自体を返上して新しい取り組みをするわけですけれども、ＩＳＯ認証を取得したということ自体も知らない区民の方が多いと思うのです。それに関してどういうふうに考えて、どういうふうに取り組まれて、これを大々的に花火を上げていかれるおつもりなのか教えていただきたい。","respondent":"三ツ橋環境課長","answer":"ＩＳＯの取り組みを区民の皆様自体がご存じないということでは、例えばホームページ上でＩＳＯの取り組みを今までこのように続けてまいりましたと。それから、区独自のＥＭＳへと変更してまいりますということをホームページ上で開示してまいります。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"知らないんですよ。より区民の方にそれを知ってもらうためにはどのようにすべきであって、どのようにしたいと考えているのか教えていただきたい。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"ＩＳＯを返上するに当たって、職員の意識や区民の皆様への意識が後退されないような形で、ホームページ上で公表していきたいと考えています。環境対策というのは目に見えるようで目に見えないような部分がありますので、非常に難しいところかなと考えています。","id":"exchange-034"},{"speaker":"大沢委員","kind":"質問・要望","question":"今回も学校にも広げ、いろいろなところで広げたというところなので、わかるような形で。ロゴもやめるのであれば、新しいロゴも表現の仕方もあろうかと思うので、そこら辺ご一考いただきたいなと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"実際どうなったのかというところがかなりあったと思うのですけれども、明らかになっていくことが第一だと思うのですが、その辺はどのように考えていらっしゃるのか説明を求めました。","respondent":"三ツ橋環境課長","answer":"１０月１日から試行運用を始めますけれども、制度説明会を実施しておりまして、具体的なものをあらわしております。ですので、一人ひとりの職員に対してはきめ細かく対応できるような形をとっていきたいと考えています。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、ぜひ区民の方も一緒になって環境負荷を減らしていくところに広がっていきますように、わかりやすい伝え方を工夫してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"の区職員の消防団入団","agenda":"の区職員の消防団入団","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは数字的なところを伺いたいと思います。入団予定の方の内訳を教えていただける範囲で教えていただきたいのですが、あと大体の年齢、そこのところを教えてほしいと求めました。","respondent":"加藤防災安全担当課長","answer":"それから、男性が３名、女性が２名。男性は５０代と３０代が２名、それから女性は２０代が２名の計５名です。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"２０代の女性が２名ということで心強いなと思います。最後に伺いたいのは、様子を見るという方向性なのか、そこを説明を求めました。","respondent":"加藤防災安全担当課長","answer":"募集につきましては恒常的に募集をしていくと考えておりまして、消防団と連絡をとって入団していくと考えています。ただ、入団をずっと継続して募集していますよと言ってもなかなか印象に残りませんので、まとまった募集ということを考えていきたいと思っています。","id":"exchange-039"},{"speaker":"大沢委員","kind":"質問・要望","question":"非常時のときにどちらが、消防団活動が優先されるのか、あるいは区の職員としての行動が、どちらが優先されるのかだけ確認させてほしいと求めました。","respondent":"加藤防災安全担当課長","answer":"資料３の入団予定の最後に、募集の際、「水防第１次配備態勢時に参集する職員を除く」という形で今回募集しました。そういった上で入団を許していただくということでこの取り組みを進めたわけですので、基本的には震災のときは区の仕事を優先したいと考えています。","id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"私も大沢委員と似たような、関連したことかもわかりませんけれども、一番下の「区の組織運営に支障がある場合を除き」という、これがほかの法律、今回決まった法律でなくてもほかの、今までにあった形のところで想定があるのかないのか、その辺も含めて教えてほしいと求めました。","respondent":"加藤防災安全担当課長","answer":"震災対応に一義的に対応する職員だとか、そういった者が消防団の事務につくと運営上困ってしまうでしょうという認識で例を挙げて言っております。ただ、その人間の個人的な時間の配分だとか、そういった解釈を考えて支障のない範囲で対応していきたいと考えています。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":29167,"voices":118}},{"id":"h26-20140916-9","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"文教委員会","time":"午後１時００分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"あのときの質問では３０万円ということだったはずなんですけれども、６７万円余が増えたその中身というのは、講師が３０万円で、あとは大ざっぱでいいですから構成を。","respondent":"伊崎子育て支援課長","answer":"大体６７万５,０００円のうち、３０万円弱がボランティア謝礼でございまして、その他は記念品を含む消耗品の購入です。","id":"exchange-001"}]},{"id":"topic-02","title":"の品川図書館 秋の講演会","agenda":"の品川図書館 秋の講演会","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"この内容的にどうなのかわからないですけれども、私の理解不足なのかもしれないですけれども、ほかに何かお電話ででも大丈夫なんですか。ちょっと確認させていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"それと対象の年齢が、読書と脳トレということで、高齢者なのか。若いお母さんだったら、例えば育児、要するにお預かりのシステムがあるのかというのを１点お願いしたいと思いますとの意見を述べました。","respondent":"中元品川図書館長","answer":"特に今までのこの図書館の秋の講演会では、育児の託児等は設けてございません。この対象のお話が、単独でお見えになったりということが多いので、今までのところではそういう準備はしてございません。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"２５０人の席、ちょっとあえてその辺、どうして事前にということになさるのか。そういう状況でされるというのはどうしてかなと、ちょっとしつこいですけれども、説明を求めました。","respondent":"中元品川図書館長","answer":"２５０人までですので、もちろんそれより下回っている場合は、受付で柔軟な対応はすることはできます。やはりある程度きちんと席をご用意してさしあげないといけないと考えていますので、あまり柔軟過ぎてもいけないのかなと思っているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"川島隆太教授がどういう方かというのは、自分自身の問題でもあるという点では、こういう講演会への期待というのは高いというふうに私は思うんですね。私も時間がとれれば伺いたいかなと思って見ていたんですけれども、どうなのかという気がするので、何かもしあればと思います。","respondent":"中元品川図書館長","answer":"今日は１０席ぐらいあいているという状況であれば、ちょっとやはり事前申し込みというところは維持していかせていただきたいと思っているところです。お電話でのお申し込みについては、皆さん、お電話で今まで特に問題なくお受けをしています。","id":"exchange-005"},{"speaker":"須藤副委員長","kind":"質問","question":"ですから、きちんとやっぱりその辺は整理しなければいけない。ですから、「よろしくお伝えください」とお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-03","title":"の品川区臨時給付金の支給状況","agenda":"の品川区臨時給付金の支給状況","exchanges":[{"speaker":"南委員","kind":"質問","question":"これは生活保護を受けている方が当然対象者ですから、児童１人当たり１万円見当で、生活保護費から差し引かれるようになるんか尋ねました。","respondent":"福島臨時給付金担当課長","answer":"ただし、途中で１月１日に生活保護を受給していなくて、途中から生活保護を受けたという方につきましては対象になります。その場合は、その分が所得として計算されるというものです。","id":"exchange-007"},{"speaker":"南委員","kind":"確認","question":"私ここを逆にとっていて、だいぶ前にほかの臨時給付金の関係でそんなようなご意見をいただいたことがあったので、確認したかったのです。秋口以降みたいなところが結構あるみたいなので、ちょっとそのあたりでどうなのかなというのが気になったので、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ。１０月１０日に送付されて、その前の申し込み書発送開始が６月１６日からとなっているので、教えてほしいと求めました。","respondent":"福島臨時給付金担当課長","answer":"今現在、未達で戻ってきた数まで、手元には資料がございませんで、ただ何件かはありますが、それは戻ってきた場合、原因を調べてまた再発送するという事務手続をとってあります。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。その辺はぜひ丁寧に対応してほしいと求めましたので、要望で終わりますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"要望させていただいていた部分がありますので、１番手というのは非常にありがたいなと思いますので、今後も引き続きお願いします。平均して件数が多いとなかなかという部分はあると思うんですが、大体どのくらいで振り込みがされるものなのかを説明を求めました。","respondent":"福島臨時給付金担当課長","answer":"ただ、また６月当初、あるいは７月ぐらいにはかなり申し込みが殺到しましたので、事務手続上おくれて、２カ月近くかかったということもあります。ただ、現在はそういったおくれも解消し、届きましたら、速やかに処理をしている段階です。","id":"exchange-011"}]},{"id":"topic-04","title":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","agenda":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、スムーズに移行ができるのかどうか、そこだけちょっと説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"本来ならば御殿山幼稚園に進んでいただくというご説明でお入りいただいたのですけれども、５歳児枠に残りたいという方につきましては、そちらのほうにも進んでいただけるように優先枠をつくる予定でおります。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"１園、何歳児が何人ぐらい増えるのかというのを確認したいと思いますので、教えていただきたいというのが１点です。ちょっとその辺が前回も１年前に質問をしたんですけれども、もう一回確認したいというのと、そのあたりを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"０から３歳児のところが以前は５１人でしたけれども、これが５４名になりますので、ここで３名の定員拡大を予定しております。現在考えておりますのが、御殿山幼稚園につきましても、４歳児につきましては新規入園児を４月から募集いたします。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"年度途中開園ということですから、４月に新しい子どもさんが入って進級していく中で、もう一度教えてほしいと求めました。新園として１園分、１０３名分が新しくできるわけですから、そのあたりはどういうふうに考えているのか説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これは移転ですので、例えば人数が加配になるとか、そういうことは考えておりません。保育士につきましては、この新設の部分につきまして、保育士の確保を来年度の４月に予定しております。","id":"exchange-014"}]},{"id":"topic-05","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"どこまでどういうふうに質問したか、確認のために質問させていただきたいんですけれども、７校が武道場がないわけですよね。現実的にどういうふうな環境設定をして武道の授業をしているのかということを質問したいのですけれども、ちょっとごめんなさい、そのあたり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"だから最初に言ったように、ちょっと覚えていなかったので、もう一回確認したいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":13973,"voices":63}},{"id":"h26-20140916-5","meetingId":"h26-cm09","date":"2014年9月16日","dateIso":"2014-09-16","committee":"総務委員会","time":"午後１時００分～午後２時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"のしながわ区民公園クラブハウス改修工事請負契約","agenda":"のしながわ区民公園クラブハウス改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"クラブハウスの改修工事ということですけれども、ここを利用されている方や今回バリアフリー対応ということも含めて、障害がある人を含めて、利用者の意見とか利便性というのはどのように反映されていらっしゃるのか、その仕組みを伺いたいと思います。","respondent":"立川経理課長","answer":"こちらの更衣室のほうを面積的には約２倍にいたしまして、また、有料の温水シャワーを設置するです。主なものは以上です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと細かい話になるので、障害がある方のご意見を伺いながら進めていただけると、よりよいものができるのかと思います。ぜひそういう障害者がある方の意見を聞いて、反映していただきたいと思うのですけれども、現状を伺いたいと思います。","respondent":"立川経理課長","answer":"既に図面とともに発注も終わり、契約も済んでいるところです。ただ、今、委員ご指摘の部分というのは軽微な修正ですので、こういった意向についてはそういうふうに伝えていきたいと思います。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"それと、この図を見ると設計変更は難しいと思うのですが、テニス更衣室側のほうにはトイレはないのでしょうか。というような状況もあると思うのですが、それはいかがか尋ねました。","respondent":"立川経理課長","answer":"３社辞退ということで、また予定価格と事業者のほうの積算が合わない、そういったことで辞退というふうに聞いておるところです。それから、こちらにつきましては温水で利用できるということですので、利用される方については有料ということで考えているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"この３社についてはできませんということなのだろうと思うのですが、区が提示する金額がかなり無理があったのかどうかというところですね。その方針にもっと理解を求めていくことになると思いますが、どのぐらいの負担を皆様に強いていくのか、その辺も説明を求めました。","respondent":"立川経理課長","answer":"３社辞退ということで、事業者と予定価格積算に乖離があるということで辞退になってあります。世の中の情勢としては厳しいところですけれども、何とか落札者が出たということで、予定価格については適正であったと思っているところです。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"まだまだ落差があるからほかのところの３社が辞退されたと考えるわけで、本当にそれは大丈夫でしょうかと確認をしたいと思います。それはどういうふうに説明していくのでしょうかという質問です。","respondent":"立川経理課長","answer":"これまで一般競争入札については予定価格を公表しておりますので、そういった意味で事前に積算が合う、合わないということで辞退するかしないかです。予定価格を公表していなければ、いわゆる予定価格より高い札で入札していくということになります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"そういうことからすると、きっちりと理論立てて利用料を設定していかなければならないのではないかと思いますが、その考え方はいかがでしょうか。最後にお聞きします。","respondent":"立川経理課長","answer":"事業の内容につきましては所管が異なりますので、明確なお答えはできないわけですけれども、こういった意見が当委員会においてあったということは所管のほうに伝えていきたいと考えております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"では放っておくというのではなくて、思い切って一時的に入札の制限がかかっているのですが、これを解除してもいいのではないですか。その辺何かもっと一時的にでも解除して、品川区の業者に入札を開放するということも必要だと思いますが、どう思われますか。","respondent":"立川経理課長","answer":"ただいま委員からもお話がありましたとおり、最近、辞退が増えているというのは事実です。そういった中で、また事業者のほうから見積もりを徴したりしまして予定価格のほうを適切に設定し直すということをやっておりますので。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"品川区は一生懸命、都単価も、国のほうも単価を上げて積算しているではないですか。だったらもっと門戸を広げて、制限を１回緩めて、ましてやこれは平屋ですから。","respondent":"立川経理課長","answer":"この条件につきましては、当面緩和するということは考えてございませんが、案件によっては区内事業者だけではできないという部分もあります。その辺は案件ごとに見きわめてやっていく必要があるというふうに考えているところです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"区で決めた予定価格を、今年はこれで間違いないと思うので、そんなに安いとも思わないし。私は区の威信にもかけて、制限を少し緩和してもっと区内業者を使うように努力して、もっと入札者が増えるように頑張ってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問は、結局プールの改修は屋外ということですから冬場はプール利用がないわけですね。そういうときは、半分から右側の施設というのは一体どういう利用になるのか尋ねました。","respondent":"立川経理課長","answer":"プールは夏場だけということで、更衣室のスペースについてはそのまま使われないというのはこれまでの状況でございました。今後、プール利用期間以外でも利用者の利便に供するような仕組みにしていきたいと考えているということは所管のほうから聞いているところです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"補足的にもう少しご説明いただきたいと思うのですけれども、工事品質の確保と適正価格の契約の推進のために、どうして電気と機械に拡大をしたのか、その中身をもう少し詳しくご説明ほしいと求めました。","respondent":"立川経理課長","answer":"機械・電気の設備工事と比べて、年度により若干違いますけれども大体１割程度、１０％ぐらいの違いがありました。その結果、区・事業者とも問題は発生していませんので、試行拡大ということで設備工事のほうまで広げるです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"意見","question":"後半のほうのところ、問題がないので拡大するということですけれども、要するにどういうことで拡大したのか、そこをご説明いただけますか。今回のポイントなのでとの意見を述べました。","respondent":"立川経理課長","answer":"国の試算ですが、また東京オリンピック・パラリンピックの開催決定による関連工事の増加見込みであるとか、それから今年の６月なのですけれども。発注者の責務として、より適切な予定価格の設定、これまで実施しておりませんでした設備工事にも対象を広げるです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、そこで言うなら、何となくそれはそれでいいのかと。だから、そこら辺のところは気をつけてほしいという意見だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"そこら辺は、そうすると今後は、最低価格は１０分の７から１０分の９の範囲で落札したところがすべてという形になってしまうということですか。まだ違うところもあるのか尋ねました。","respondent":"立川経理課長","answer":"市販のものを使えるというようなことになりますと、事業者によっては安くその部材を仕入れることができたりということはあります。こちらの資料にも案件ごとに定めるということになっておりますので、その辺については案件ごとに見きわめるというふうには考えてあります。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"１点お聞きします。「国モデルに準拠し」という「国モデル」はそもそもどういう基準をつくられているのか、細かく国モデルというのは決められているものなのか尋ねました。","respondent":"立川経理課長","answer":"国モデルの説明をします。そういった計算式をもとに品川区でも実施する。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"人口であるとか例えば労務費も都市部と地方とでは違いますよね。そういうずれとか違いを補正した上で、品川区はこれで計算するよという形になっているのか尋ねました。","respondent":"立川経理課長","answer":"品川区につきましても、国の単価または都の単価、それからまた品川区の単価というのも持っております。その辺を総合的に条件に加えまして、実際の最終価格を決めていくです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"そうすると品川区の単価というのになると、品川区の単価というのはどこから来る単価なのでしょうか。どういう調整をして品川区としての基準をつくっていくのか尋ねました。","respondent":"中山総務部長","answer":"そのもとになる単価というのは地域によって差がありますので、全国一律のもので決めていくものではないという、その割合の算定式を中央公契連モデルを準用しているです。","id":"exchange-017"},{"speaker":"塚本副委員長","kind":"質問","question":"今回もともと１０分の８から３分の２だったのが、１０分の９から１０分の７、少し上がったわけですね。これはなぜかというと、今までは沿っていなかったのかというふうに今思ってしまったのですが、そこら辺の説明をお願いします。","respondent":"立川経理課長","answer":"品川区は１０分の８上限でやっておりましたけれども、他区の状況を見ますとやはりまだ３分の１ぐらいは１０分の８という設定をしたりしております。１０分の８を使ってきたですけれども、国モデルに引き上げる必要があるかというふうに考えて、今回改定をしたところです。","id":"exchange-018"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"今この場でまた質問するのもと思いつつ、８番の主な課題というか、むしろこれを見るとデメリット的な方向にしか見えません。そういうのは、そのメリットはどういう部分なのかということをわかれば、課長の考え方でもいいのでお願いします。","respondent":"黒田税務課長","answer":"資料２ページの項番３の(1)にあります、ここが利用される方としては大きなメリットではないかというふうに考えられます。ただ、現状では経費がかなりかかるというところが、自治体側としてはちょっと考えどころかというふうに考えているものです。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"どのみち払うべきものですからあれですけれども、カード決済というのは非常に楽で、パソコンがあればいつでもできるという部分があります。それについてどうお考えかという部分と、もちろんこれは今触れているのは公金システムですから税の部分だと思いますが、ちょっと逸れますけれども。","respondent":"黒田税務課長","answer":"今委員からご指摘いただいたような課題について、地方公共団体の財務制度の見直しおよび制度化について勉強会を開いて検討していると伺っております。この中でもそういった電子マネーによる納付方法の制度化の検討などさまざまな検討を進めているというふうに伺っておりますして。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいといっても今、区はやっていないので、知っているところがあればご説明をいただきたいと思うのが一つです。率直な意見になってしまいますが、今の区の現状や考えがあれば、ぜひ伺いたいと思います。","respondent":"黒田税務課長","answer":"利用枠があるかないかということを、当然カードローンで与信枠がない方については利用できないという仕組みになっていると伺っております。現状では、改修費用等々を考えますと、即座の導入はなかなか難しいのではないかというのが私の考えるところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"確認","question":"やはり生活状況が急変することもあり得るわけですから、そこを伺えたらと思います。伺いたいのは、この人はこのカードでどういう商品を扱っているか、どの情報に限定してのやりとりになるのか。","respondent":"黒田税務課長","answer":"先の説明の中で申し上げましたが、区として歳入欠損があるような事業者は指定しないということをまず大前提で選ぶということになります。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"残高ゼロになったときには、カードは便利だけれども、その中にあるリスクや将来的なリスクも十分見きわめていかなければいけないと思います。個人情報の取り扱いも厳格にしていく必要があると、税情報というのは所得だったり世帯だったりいろいろな個人情報が詰まっているものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それからもう１点は、安全なところなんか、今の世の中ではないのではないですか。そう考えると、便利さを求めるのならクレジットもありなのかと思っているので、そこら辺の考え方を教えていただきたいです。","respondent":"黒田税務課長","answer":"手数料が収納金額の１％ですと、低額の税でありませんと、ちょっと課題があると考えております。その会社から納入が見込めないということなので、安全なところというのは国のほうから通知が出ているものでもあります。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"意見","question":"１,８００自治体、まさにこういうものについては品川区が先にやってもいいような気がするというのが私の感覚です。今、トップでやったって私はいいのではないかと思うぐらいの感覚なのだけれども、そこら辺の考え方はどうかと思うのですけれどもとの意見を述べました。","respondent":"中山総務部長","answer":"そういうものを行いながら、他の自治体の動向、なかなか先ほどの説明の中でも納付率への寄与という部分が明確に出ない部分はあります。いて区民の方にも喜ばれる、こういうものを常に研究してまいりたい、そういうスタンスでやってまいりたいと思ってあります。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"要望だけ。どうぞ品川区に住んでいただいて、どうぞ使ってください」というのが私はいいと思っているので、これはお願いだけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"年齢からいうと若い方か、そこら辺がわかったら教えてほしいのですけれども、その辺の分析はどのぐらいできているのでしょうかということが一つ。情報があれば教えてほしいと求めました。","respondent":"黒田税務課長","answer":"１点目のコンビニ収納の利用の年代はどうかというご質問ですが、明確な統計をとったことはありませんが、幅広く使われていると認識しています。がこのクレジット納付の中では一番大手と申しましょうか、契約件数が多いというふうに認識しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、インターネット上でのセキュリティを考えると、そこら辺はちょっとキャッチしていただきたいと思っています。これは意見としておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28484,"voices":66}},{"id":"h26-20140917-14","meetingId":"h26-cm09","date":"2014年9月17日","dateIso":"2014-09-17","committee":"行財政改革特別委員会","time":"午後１時００分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"その前に、いいですか。そのあたりを説明を求めました。","respondent":"中塚委員長","answer":"この後、説明しようかと思ったのですけれども、前回の議論の中で、基金についてのあり方や見直し、基金についての創設の議論がありました。議論を深めるに当たって、他自治体の状況を調査・研究したいと、そういう旨です。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"違った基金というのは、いろいろな、この間も２３区でもやっていたわけだ。世田谷区になぜ聞きに行きますよという話になったのか、委員会の中で聞いていないと思うのだけれども、この点ではいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"２３区がいろいろやっているのは、なぜ世田谷区だけにしたのか、そのスタートの経緯というのはみんな違うわけだ。そういうような話でいきなり帰りが５時過ぎかもしれないと言われたら、なぜ、もう少し配慮してもらいたいと思うとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"は正副に一任させていただいていいですかというふうに委員長がおっしゃったときに、「はい」という言葉も含めて了解したわけです。時間がないときに、そのことで時間をとりたくないという気持ちはありますので、そういうふうに理解するべきではないかと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"なぜ世田谷区を選んだのですかというお話です。「世田谷区がおもしろいこういうものがあるのでどうですか」という話になってきて、長時間になるような話だから、もう少し今までの委員会の中で。","respondent":"中塚委員長","answer":"介護給付についての基金などを具体的にやっておりましたので、その中で他自治体との日程を調整する中で、世田谷区が受けていただけるということになりまして進めさせていただいたということです。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。今のお話を伺っていると、前回も伺いましたが、もしおわかりでしたら説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"現段階では、東京都は、この後ろの国有地については取得する意思はないというふうに聞いています。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問","question":"１つだけ、素人考えで、前面の４ｍ幅だから１５ｍ以下、そこが引っかかる。道路が連続するのですが、ここだけ４ｍ幅ではなくて、６ｍとか８ｍとか、そういうふうにしたら、ほかに何とかできるのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"４ｍ道路にはもう１つの細い接道しかしてありませんので、建物としては１５ｍ以上の高さというのは、それは可能です。ただ、道路として認定がされるかどうかはまた別の話になると思います。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"いつまでも住まわせるわけにはいかないわけですから、建替えなり、住宅を何らかの形で保障していかなくてはいけないわけですよね。改めて、公共住宅４２戸は確保しようという、そういう気持ちは品川区としては持っているということで確認させていただいていいか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"都営住宅の部分についての考え方というのでしょうか、ここを都営住宅から買い取りから何なりということでやるということで建替えするということになれば、これに基づいて４２戸は確保しなくてはいけないという考え方でいるです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"そうすると、逆に品川区が土地を一体的に使うということで購入しなければ、４２戸の確保はできないという、そういうことになるということなのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"東京都がどのように考えているかというのはよくわからない部分はあるのですけれども、現戸数を確保するために何らかの方策をとっていくのだろうというふうには思います。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"区有施設が小さくても、それは土地の状況から見てやむを得ないわけですから、住宅の確保というのはしていくべきだというふうに思うのです。私は、そういう立場で捉えていくべきだというふうに思っているのですけれども、改めてその点についての見解を伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"我々検討する中で、区の行政目的のためにどのようなものができるかという視点で検討を行ってきたわけです。その検討する中で、もちろん費用の面というのは大きな１つの視点として考えたところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"最後に要望だけ。そういう点で、再確認していただけるいいチャンスでもあると思いますので、そのことは強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"提案","question":"品川区の公有地有効活用プランというのは、これ、あるのですけれども、この委員会で資料をいただいてはいないと思っているのですけれども、そういうものも含めていただけないかというふうには、今、委員長の提案があったので、ちょっと思いついたと言うと失礼ですけれどもよろしいか尋ねました。","respondent":"中塚委員長","answer":"７月２日の委員会で概要版をもらっており、そこで一度議論をしたところですけれども、深めていきたいとのご意見を受けて、次回また進めていきたいというふうに思っています。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"提案","question":"毎回毎回このたびごとに次はどうしますかということではなくて、既に議論をされている内容があるわけですから、当然本日だって。だけれども、むしろ正副委員長のほうからこうしましょうということを提案していただいて進めていったほうがいいのではないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"最低制限価格制度の試行運用の拡大","agenda":"最低制限価格制度の試行運用の拡大","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"これからまた見ながらということなのですけれども、この試行運用という位置づけというのは、大体どのくらいの期間を見ていらっしゃいますか。ちょっと確認させてください。","respondent":"立川経理課長","answer":"ものによるという言葉ですけれども、おおむね１年ぐらいは状況を確認して、それでまた次のステップとか、そういったことを考えているところです。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"これについてはいろいろと制度を少しずつお声を聞きながら、今、動かしている最中ということで、また今回のようなスピーディな対応を今後もいろいろな動きに対応して動くというものを期待しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"提案","question":"私どもでいろいろな設計図をかきながら皆様にご提案させていただければと、そのとおりだと思いますので、このように考えております。本日も長時間になってしまって申しわけありませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"私は正副の２人が委員会運営をどうしようかというのでいろいろご苦労されて、次回、今までの経験からも私はそういうふうに受けとめています。したがって、一生懸命正副委員長の交通整理に従って、しっかりと議論できるような委員会運営に一委員としても努力をしていきたいと考えています。","respondent":"中塚委員長","answer":"なければ、本件を終了いたします。以上により、予定表３のその他を終了いたします。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15335,"voices":50}},{"id":"h26-20140918-18","meetingId":"h26-cm09","date":"2014年9月18日","dateIso":"2014-09-18","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後４時３７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/882053?Template=document&Id=6462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2229,"voices":10}},{"id":"h26-20141024-4","meetingId":"h26-c-settlement","date":"2014年10月24日","dateIso":"2014-10-24","committee":"決算特別委員会","time":"午後 ３時３９分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"ただいま皆様のご推挙によりまして、決算特別委員会の副委員長の大任を拝命いたしました。円滑かつ、また実りある委員会としていきたいと思いますので、どうかご協力のほどよろしくお願いを申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/168739?Template=document&Id=1386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":2027,"voices":16}}]);
